def physics_runtime_visual_kind(visual_kind: str) -> str:
    return PHYSICS_RUNTIME_VISUAL_KINDS.get(visual_kind, visual_kind)


def physics_topic_spec(title: str, *, fail_closed: bool = False) -> tuple[str, str, list[str]] | None:
    """Map a mechanics topic to the physical model its animation must preserve."""
    spec = resolve_physics_model(title, fail_closed=fail_closed)
    if spec is None:
        return None
    established = {
        "work and energy": ("physics_work", r"W=\Delta K"),
        "kinetic energy and work": ("physics_work", r"W=\Delta K"),
        "potential energy and energy conservation": ("physics_energy", r"E_i=E_f"),
        "center of mass": ("physics_center_of_mass", r"\vec r_{\mathrm{cm}}=\frac{\sum_i m_i\vec r_i}{\sum_i m_i}"),
        "rocket equation": ("physics_rocket", r"\Delta v=v_e\ln\!\left(\frac{m_i}{m_f}\right)"),
    }.get(re.sub(r"[^a-z0-9]+", " ", title.lower()).strip())
    if established is not None:
        return established[0], established[1], list(spec.prerequisites)
    video_route = resolve_physics_video_model(title)
    use_video_subtype = (
        video_route is not None
        and video_route.visual_kind in PHYSICS_VISUAL_KINDS
        and (
            video_route.family in {"mass_transfer", "rolling_kinematics"}
            or physics_runtime_visual_kind(video_route.visual_kind) == physics_runtime_visual_kind(spec.visual_kind)
        )
    )
    # Rolling kinematics historically renders through the translational
    # kinematics scene even though its exact typed model is rotational.  Keep
    # that public renderer alias without weakening the exact model identity.
    if video_route is not None and video_route.family == "rolling_kinematics":
        visual_kind = "physics_kinematics"
    else:
        visual_kind = physics_runtime_visual_kind(video_route.visual_kind) if use_video_subtype else spec.visual_kind
    formula = video_route.canonical_formula if use_video_subtype else spec.canonical_formula
    return visual_kind, formula, list(spec.prerequisites)


def semantic_physics_topic(short: dict[str, object]) -> str | None:
    """Return the authoritative physics subtype carried by a planned short."""
    for field in ("scenario_mode", "model_id"):
        value = str(short.get(field, "")).strip()
        if value and resolve_physics_video_model(value.replace("_", " ")) is not None:
            return value.replace("_", " ")
    return None


