def economics_topic_spec(title: str, *, fail_closed: bool = False) -> tuple[str, str, str, list[str]] | None:
    """Map an economics topic to the state transition its renderer must show."""
    spec = resolve_economics_model(title, fail_closed=fail_closed)
    if spec is None:
        return None
    mode = ECONOMICS_RENDER_MODE_BY_MODEL.get(spec.model_id)
    if mode is None:
        raise ValueError(f"Economics model {spec.model_id!r} has no renderer mode.")
    route = resolve_economics_video_route(spec.model_id)
    visual_kind = ECONOMICS_DEDICATED_VISUAL_KINDS.get(route.family, spec.visual_kind) if route else spec.visual_kind
    return visual_kind, mode, spec.canonical_formula, list(spec.prerequisites)


def physics_concrete_source_example(topic: str, visual: str, seed: int) -> tuple[str, str, str, str, str]:
    """Build one parseable mechanics experiment whose conclusion is recomputed."""
    resolved_model = resolve_physics_model(topic, fail_closed=True)
    assert resolved_model is not None
    model_id = resolved_model.model_id

    specialized: dict[str, tuple[str, str, str, str, str]] = {
        "impulse_momentum": (
            "A m1=0.4 kg ball at v1=3 m/s meets a m2=0.6 kg ball at v2=-1 m/s; they stick after a 0.3 s collision whose average force on ball 1 is -3.2 N.",
            "Ball 1 receives J1=F dt=-3.2(0.3)=-0.96 N s, changing p1 from 1.2 to 0.24 kg m/s; ball 2 receives +0.96 N s, changing p2 from -0.6 to 0.36 kg m/s, so both leave at 0.6 m/s.",
            "Equal-and-opposite impulses change each ball's momentum while preserving the two-ball total of 0.6 kg m/s.",
            "What area on a force-time graph gives the momentum change?",
            "The area under the force-time curve is the impulse.",
        ),
        "momentum_conservation": (
            "A m1=2 kg cart at v1=4 m/s catches a m2=6 kg cart at v2=0 m/s on a level isolated track.",
            "Total momentum stays 2(4)+6(0)=8 kg m/s, so the joined 8 kg system moves at 1 m/s.",
            "Conservation compares the total momentum of an isolated multi-object system before and after interaction.",
            "Why can the carts' individual momenta change?",
            "Internal forces transfer momentum between carts while their total remains fixed.",
        ),
        "collision_momentum": (
            "Classify a collision where m1=1 kg at v1=4 m/s meets m2=1 kg at v2=0 m/s and they leave together at 2 m/s.",
            "Momentum is 4 kg m/s both before and after, but kinetic energy falls from 8 J to 4 J, so the collision is perfectly inelastic.",
            "Collision type is determined by what happens to kinetic energy after momentum balance is checked.",
            "What distinguishes an elastic collision?",
            "An elastic collision conserves both total momentum and total kinetic energy.",
        ),
        "elastic_collision": (
            "A m1=1 kg cart at v1=5 m/s elastically strikes an identical m2=1 kg cart at v2=0 m/s head-on.",
            "For equal masses, momentum and kinetic energy are both conserved when the first cart stops and the second leaves at 5 m/s.",
            "The elastic constraints transfer the incident velocity between identical masses without losing kinetic energy.",
            "Which two totals constrain this result?",
            "Total linear momentum and total kinetic energy.",
        ),
        "point_particle_angular_momentum": (
            "For dt=1 s, F=1 N acts tangentially at lever arm r=2 m on a m1=0.5 kg particle with v1=6 m/s; a reference m2=1 kg particle has v2=0 m/s.",
            "Its momentum is p=(0,3) kg m/s, so Lz=x*py-y*px=2(3)=6 kg m^2/s.",
            "A point particle has angular momentum because its linear momentum has a perpendicular lever arm about the chosen origin.",
            "When would this particle's angular momentum be zero?",
            "It is zero when the momentum line passes through the chosen origin.",
        ),
        "rigid_body_angular_momentum": (
            "For dt=1 s, F=1 N acts at r=1 m on a rigid disk represented by m1=0.4 kg and m2=0.4 kg rim masses with v1=5 m/s and v2=-5 m/s, I=0.8 kg m^2, and omega=5 rad/s.",
            "For this principal-axis rotation, L=I omega=0.8(5)=4 kg m^2/s.",
            "Rigid-body angular momentum combines the body's mass distribution with its common angular speed.",
            "What property of the body enters besides angular speed?",
            "Its moment of inertia about the rotation axis.",
        ),
        "rolling_kinetic_energy": (
            "For dt=1 s, contact force F=1 N acts at r=0.5 m on a solid cylinder modeled as m1=1 kg and m2=1 kg halves rolling with v1=3 m/s and v2=3 m/s.",
            "I=MR^2/2=0.25 kg m^2 and omega=v/R=6 rad/s, so K=mv^2/2+Iomega^2/2=9+4.5=13.5 J and Lcm=Iomega=1.5 kg m^2/s.",
            "Rolling motion carries simultaneous translational and rotational energy, linked by the no-slip condition.",
            "Why can the rotational term not be omitted?",
            "Every material point rotates about the moving center while the center translates.",
        ),
        "rigid_body_motion": (
            "During dt=1 s, a perpendicular F=2 N force acts at r=0.6 m on a 1.2 m rigid bar translating at vcm=(3,1) m/s and rotating at omega=2 rad/s; point A is 0.6 m right of center.",
            "The rotational velocity of A is omega cross r=(0,1.2) m/s, so vA=(3,2.2) m/s.",
            "Rigid-body motion is the sum of center-of-mass translation and rotation about the center.",
            "What two motions determine every point velocity?",
            "Center translation and angular rotation about the center.",
        ),
        "moment_of_inertia": (
            "During dt=1 s, compare a 3 kg point mass at r=2 m from an axis under tangential F=1 N with the same mass at 1 m.",
            "I=mr^2 gives 12 kg m^2 at 2 m and 3 kg m^2 at 1 m, a factor of four from doubling radius.",
            "Moment of inertia weights mass by squared distance from the chosen axis.",
            "Why does moving mass outward strongly resist angular acceleration?",
            "The radius enters moment of inertia as r squared.",
        ),
        "torque": (
            "A F=10 N force acts at r=0.4 m from a pivot for dt=1 s, at 30 degrees to the lever arm.",
            "Only the perpendicular component turns the arm: tau=r F sin(theta)=0.4(10)(0.5)=2 N m.",
            "Torque depends on the perpendicular lever arm, not force magnitude alone.",
            "When does the same force produce zero torque?",
            "When its line of action passes through the pivot.",
        ),
        "rotational_dynamics": (
            "For dt=1 s, a wheel with I=2 kg m^2 receives F=9 N at r=1 m clockwise and a 3 N m counterclockwise torque.",
            "Net torque is 6 N m clockwise, so alpha=tau_net/I=6/2=3 rad/s^2 clockwise.",
            "Rotational dynamics applies the net torque to the body's moment of inertia to determine angular acceleration.",
            "What must be combined before solving for alpha?",
            "Combine signed torques about the same axis.",
        ),
        "angular_impulse": (
            "A flywheel starts with angular momentum 4 kg m^2/s; apply a perpendicular F=3 N force at lever arm r=1 m for dt=2 s.",
            "Torque is rF=3 N m and angular impulse is tau dt=3(2)=6 kg m^2/s, so angular momentum rises from 4 to 10 kg m^2/s.",
            "Angular impulse is the time integral of torque and changes angular momentum directly.",
            "What does the area under a torque-time graph measure?",
            "It measures the change in angular momentum.",
        ),
        "rolling_dynamics": (
            "For dt=1 s, a solid 2 kg cylinder of r=0.5 m rolls down a 30 degree incline without slipping while contact friction is F=3.27 N; use I=MR^2/2 and g=9.8 m/s^2.",
            "Translation and rotation give a=g sin(theta)/(1+I/MR^2)=9.8(0.5)/1.5=3.27 m/s^2; static friction supplies the torque.",
            "Rolling acceleration follows from coupled force and torque equations, with static friction enforcing no slip.",
            "What role does static friction play here?",
            "It provides the torque needed to match angular and translational acceleration.",
        ),
    }
    specialized_aliases = {
        "collision_classification": "collision_momentum",
        "rolling_energy_angular_momentum": "rolling_kinetic_energy",
    }
    model_id = specialized_aliases.get(model_id, model_id)
    if model_id in specialized:
        return specialized[model_id]

    if model_id == "work_energy_multidimensional":
        return (
            "A 2 kg puck moves from (0,0) to (3,4) m under constant force F=(6,8) N, starting at 5 m/s.",
            "Work is F dot d=6(3)+8(4)=50 J; Ki=25 J, so Kf=75 J and vf=sqrt(75)=8.66 m/s.",
            "In multiple dimensions, only the force component along the displacement contributes work.",
            "Why is the dot product required?",
            "It selects the component of force parallel to displacement.",
        )
    if model_id == "work_energy_1d":
        return (
            "A 7 N force pulls a 3 kg sled with initial speed u=2 m/s through d=6 m along a straight track.",
            "Work is 7(6)=42 J; Ki=6 J, so Kf=48 J and vf=sqrt(2(48)/3)=5.66 m/s.",
            "In one dimension, signed force over displacement directly changes kinetic energy.",
            "What sign would a backward force contribute?",
            "A backward force over forward displacement does negative work.",
        )
    if model_id == "conservative_nonconservative_forces":
        return (
            "A body moves 1 m while a conservative force does 14 J of work and friction does -1 J.",
            "Delta U=-Wc=-14 J, while Wnc=-1 J changes mechanical energy by -1 J.",
            "Conservative work transfers energy between K and U; nonconservative work changes their total.",
            "Which work changes the body's mechanical-energy total?",
            "The -1 J of nonconservative friction work changes K+U.",
        )
    if model_id == "potential_energy_configuration":
        return (
            "A m=2 kg block is held at spring displacement x0=0.3 m with k=80 N/m, using equilibrium as the zero-energy reference.",
            "Its stored potential energy is U=kx0^2/2=40(0.09)=3.6 J; release to equilibrium gives v=sqrt(2U/m)=1.9 m/s.",
            "Potential energy assigns stored energy to configuration relative to a stated reference.",
            "What determines the spring's stored energy?",
            "Its stiffness and squared displacement from equilibrium.",
        )
    if model_id == "circular_dynamics":
        return (
            "A 2 kg body moves at 6 m/s on a circle of radius 6 m under an inward net force.",
            "Newton's second law requires Fr=m v^2/r=2(36)/6=12 N toward the center.",
            "Circular dynamics identifies which real forces supply the required inward net force.",
            "Which direction must the net force point?",
            "It points radially inward, parallel to the centripetal acceleration.",
        )

    if model_id == "work_energy_theorem" and "2d" in topic.lower():
        return (
            "A 2 kg puck moves from (0,0) to (3,4) m under constant force F=(6,8) N, starting at 5 m/s.",
            "Work is F dot d=6(3)+8(4)=50 J; Ki=25 J, so Kf=75 J and vf=sqrt(75)=8.66 m/s.",
            "In multiple dimensions, only the force component along the displacement contributes work.",
            "Why is the dot product required?",
            "It selects the component of force parallel to displacement.",
        )
    if model_id == "work_energy_theorem":
        return (
            "A 7 N force pulls a 3 kg sled with initial speed u=2 m/s through d=6 m along a straight track.",
            "Work is 7(6)=42 J; Ki=6 J, so Kf=48 J and vf=sqrt(2(48)/3)=5.66 m/s.",
            "In one dimension, signed force over displacement directly changes kinetic energy.",
            "What sign would a backward force contribute?",
            "A backward force over forward displacement does negative work.",
        )
    if model_id == "potential_energy":
        return (
            "A m=2 kg block is held at spring displacement x0=0.3 m with k=80 N/m, using equilibrium as the zero-energy reference.",
            "Its stored potential energy is U=kx0^2/2=40(0.09)=3.6 J; release to equilibrium converts that store to kinetic energy and gives v=sqrt(2U/m)=1.9 m/s.",
            "Potential energy assigns stored energy to configuration relative to a stated reference.",
            "What determines the spring's stored energy?",
            "Its stiffness and squared displacement from equilibrium.",
        )
    if visual == "physics_mass_transfer" or any(marker in topic.lower() for marker in ("continuous mass transfer", "control volume", "mass flow")):
        inlet_rate = float(3 + (seed % 3))
        outlet_rate = float(1 + ((seed // 5) % 2))
        duration = 4.0
        initial_mass = 10.0
        accumulated = (inlet_rate - outlet_rate) * duration
        final_mass = initial_mass + accumulated
        return (
            f"A fixed control volume starts with M0={format_scalar(initial_mass)} kg. Mass enters at mdot_in={format_scalar(inlet_rate)} kg/s and leaves at mdot_out={format_scalar(outlet_rate)} kg/s for t={format_scalar(duration)} s.",
            f"dMcv/dt={format_scalar(inlet_rate)}-{format_scalar(outlet_rate)}={format_scalar(inlet_rate - outlet_rate)} kg/s, so Mcv={format_scalar(initial_mass)}+({format_scalar(inlet_rate - outlet_rate)})({format_scalar(duration)})={format_scalar(final_mass)} kg.",
            f"This teaches {topic} by tracking flux across a fixed boundary and the resulting accumulation inside it.",
            f"What condition makes this {topic} control volume steady?",
            "Total inlet mass flow must equal total outlet mass flow, so the stored mass stops changing.",
        )
    if resolve_physics_video_model(topic) is not None and resolve_physics_video_model(topic).family == "rolling_kinematics":
        scenario = get_physics_model_scenario("rolling_kinematics").as_dict()
        setup = scenario["setup"]
        calculation = scenario["calculation"]
        result = scenario["result"]
        return (
            f"A rolling body has radius R={format_scalar(setup['radius'])} m, initial angular speed omega={format_scalar(setup['angular_speed'])} rad/s, angular acceleration alpha={format_scalar(setup['angular_acceleration'])} rad/s^2, and rolls without slipping for t={format_scalar(setup['elapsed_time'])} s.",
            f"No slip gives v_cm=omega R={format_scalar(calculation['center_speed'])} m/s and a_cm=alpha R={format_scalar(calculation['center_acceleration'])} m/s^2; after the interval, omega={format_scalar(result['final_angular_speed'])} rad/s and v_cm={format_scalar(result['final_center_speed'])} m/s.",
            f"The rolling body couples translation and rotation while its contact point has speed {format_scalar(result['contact_speed'])} m/s relative to the ground.",
            f"What condition distinguishes rolling without slipping in this {topic} example?",
            "The contact point is instantaneously at rest, so center speed equals angular speed times radius.",
        )
    if visual == "physics_kinematics":
        x0 = float(seed % 3)
        v0 = float(2 + ((seed // 5) % 4))
        acceleration = float(1 + ((seed // 11) % 3))
        duration = float(3 + ((seed // 17) % 3))
        position = x0 + v0 * duration + 0.5 * acceleration * duration**2
        velocity = v0 + acceleration * duration
        return (
            f"A particle has x0={format_scalar(x0)} m, v0={format_scalar(v0)} m/s, and a={format_scalar(acceleration)} m/s^2; evaluate the motion at t={format_scalar(duration)} s.",
            f"At t={format_scalar(duration)} s, x={format_scalar(position)} m and v={format_scalar(velocity)} m/s from the same trajectory.",
            f"This teaches {topic} by moving one particle while its position and velocity graphs update together.",
            f"What does the slope of the position curve mean in this {topic} example?",
            "It is the instantaneous velocity of the same moving particle.",
        )
    if visual == "physics_vector":
        components = (3.0, 4.0) if seed % 2 == 0 else (5.0, 12.0)
        magnitude = math.hypot(*components)
        unit = tuple(value / magnitude for value in components)
        return (
            f"Normalize the vector u=({format_scalar(components[0])},{format_scalar(components[1])}) m.",
            f"Its magnitude is {format_scalar(magnitude)} m, so u_hat=({format_scalar(unit[0])},{format_scalar(unit[1])}) and its length is 1.",
            f"This teaches {topic} by separating direction from the original vector's size.",
            f"What must be true after normalizing a vector in this {topic} example?",
            "The direction is unchanged and the new magnitude is exactly one.",
        )
    if visual == "physics_center_of_mass":
        m1, x1, m2, x2 = 2.0, 1.0, 3.0, 6.0
        center = (m1 * x1 + m2 * x2) / (m1 + m2)
        return (
            f"Place m1={format_scalar(m1)} kg at x1={format_scalar(x1)} m and m2={format_scalar(m2)} kg at x2={format_scalar(x2)} m.",
            f"The weighted center is ({format_scalar(m1)}({format_scalar(x1)})+{format_scalar(m2)}({format_scalar(x2)}))/({format_scalar(m1)}+{format_scalar(m2)})={format_scalar(center)} m.",
            f"This teaches {topic} by showing the balance point shift toward the heavier mass.",
            f"Which mass pulls the center closer in this {topic} example?",
            "The 3 kg mass has the larger weight in the average, so the center lies closer to it.",
        )
    if visual == "physics_rocket":
        initial_mass, final_mass, exhaust_speed = 500.0, 300.0, 2000.0
        delta_v = exhaust_speed * math.log(initial_mass / final_mass)
        delta_v_display = format_scalar(round(delta_v))
        return (
            f"A rocket changes from mi={format_scalar(initial_mass)} kg to mf={format_scalar(final_mass)} kg with exhaust speed ve={format_scalar(exhaust_speed)} m/s.",
            f"The velocity gain is {format_scalar(exhaust_speed)} ln({format_scalar(initial_mass)}/{format_scalar(final_mass)})={delta_v_display} m/s.",
            f"This teaches {topic} by tying every velocity gain to expelled momentum and decreasing vehicle mass.",
            f"Why does the logarithm appear in this {topic} example?",
            "Each equal amount of expelled mass acts on a rocket whose remaining mass is different.",
        )
    if visual == "physics_ode":
        decay, initial, duration = 0.5, 8.0, 4.0
        final = initial * math.exp(-decay * duration)
        return (
            f"A velocity obeys dv/dt=-{format_scalar(decay)}v with v(0)={format_scalar(initial)} m/s; evaluate it at t={format_scalar(duration)} s.",
            f"v(t)={format_scalar(initial)} exp(-{format_scalar(decay)}t), so v({format_scalar(duration)})={format_scalar(final)} m/s.",
            f"This teaches {topic} by evolving an initial state continuously under its rate law.",
            f"What determines the entire curve in this {topic} example?",
            "The differential equation and the initial velocity together determine one trajectory.",
        )
    if visual == "physics_work":
        force, mass, distance, initial_speed = 4.0, 2.0, 6.0, 2.0
        if topic.lower() == "work and energy":
            force, mass, distance, initial_speed = 5.0, 2.0, 3.0, 0.0
        work = force * distance
        initial_energy = 0.5 * mass * initial_speed**2
        final_energy = initial_energy + work
        final_speed = math.sqrt(2.0 * final_energy / mass)
        return (
            f"A {format_scalar(force)} N force pushes a {format_scalar(mass)} kg cart with initial speed u={format_scalar(initial_speed)} m/s through d={format_scalar(distance)} m.",
            f"W={format_scalar(work)} J, Ki={format_scalar(initial_energy)} J, Kf={format_scalar(final_energy)} J, and vf={format_scalar(final_speed)} m/s.",
            f"This teaches {topic} by making the force-distance area become a measured change in kinetic energy.",
            f"What equality must the animation preserve in this {topic} example?",
            "The work done must equal final kinetic energy minus initial kinetic energy.",
        )
    if visual == "physics_energy":
        if "potential energy and energy conservation" in topic.lower() or "spring" in topic.lower():
            mass, spring_constant, compression = 2.0, 50.0, 0.4
            spring_energy = 0.5 * spring_constant * compression**2
            equilibrium_speed = math.sqrt(2.0 * spring_energy / mass)
            return (
                f"A m={format_scalar(mass)} kg block compresses a spring with k={format_scalar(spring_constant)} N/m by x0={format_scalar(compression)} m, then passes equilibrium without friction.",
                f"The spring initially stores {format_scalar(spring_energy)} J. At equilibrium that is {format_scalar(spring_energy)} J of kinetic energy, giving v={format_scalar(equilibrium_speed)} m/s.",
                f"This teaches {topic} by releasing stored spring energy into motion while the total-energy marker stays fixed.",
                f"Where is the potential energy smallest in this {topic} example?",
                "At the spring's equilibrium position, where the block's kinetic energy is largest.",
            )
        mass, initial_height, final_height, gravity = 2.0, 5.0, 1.0, 9.8
        if topic.lower().strip() == "conservation of energy":
            mass, initial_height, final_height = 3.0, 6.0, 2.0
        released = mass * gravity * (initial_height - final_height)
        final_speed = math.sqrt(2.0 * released / mass)
        return (
            f"A {format_scalar(mass)} kg object starts from rest at h0={format_scalar(initial_height)} m and falls to h1={format_scalar(final_height)} m with g={format_scalar(gravity)} m/s^2.",
            f"Potential energy falls by {format_scalar(released)} J, so Kf={format_scalar(released)} J and vf={format_scalar(final_speed)} m/s.",
            f"This teaches {topic} by moving energy between height and speed while the total bar stays fixed.",
            f"What remains unchanged in this {topic} example?",
            "Total mechanical energy remains constant when no nonconservative work enters the system.",
        )
    if visual == "physics_momentum":
        m1, v1, m2, v2 = 2.0, 3.0, 1.0, 0.0
        momentum = m1 * v1 + m2 * v2
        final_velocity = momentum / (m1 + m2)
        return (
            f"A m1={format_scalar(m1)} kg cart at v1={format_scalar(v1)} m/s hits a m2={format_scalar(m2)} kg cart at v2={format_scalar(v2)} m/s, and they stick.",
            f"p={format_scalar(momentum)} kg m/s, so vf=p/(m1+m2)={format_scalar(final_velocity)} m/s.",
            f"This teaches {topic} by showing momentum move between bodies while the system total remains fixed.",
            f"What system boundary makes conservation valid in this {topic} example?",
            "Include both carts so their interaction forces are internal to the system.",
        )
    if visual == "physics_potential":
        center, floor, total_energy = 2.0, 1.0, 5.0
        reach = math.sqrt(total_energy - floor)
        left, right = center - reach, center + reach
        return (
            f"Let U(x)=(x-{format_scalar(center)})^2+{format_scalar(floor)} J and total energy E={format_scalar(total_energy)} J.",
            f"Turning points satisfy U=E, giving x={format_scalar(left)} m and x={format_scalar(right)} m; between them K=E-U is nonnegative.",
            f"This teaches {topic} by reading allowed motion and turning points directly from the energy curve.",
            f"Why does the particle turn around at either endpoint in this {topic} example?",
            "Its kinetic energy reaches zero there, so it cannot enter the region where U exceeds E.",
        )
    if visual == "physics_circular":
        if "position" in topic.lower():
            radius, omega, duration = 3.0, 1.5, 2.0
            angle = omega * duration
            x = radius * math.cos(angle)
            y = radius * math.sin(angle)
            return (
                f"A particle moves on a circle with r={format_scalar(radius)} m and omega={format_scalar(omega)} rad/s; locate it at t={format_scalar(duration)} s.",
                f"theta=omega t={format_scalar(angle)} rad, so (x,y)=({format_scalar(x)},{format_scalar(y)}) m.",
                f"This teaches {topic} by turning angular phase into a moving Cartesian position.",
                f"What stays fixed in this {topic} example?",
                "The distance from the center remains equal to the radius even though both coordinates change.",
            )
        radius, speed = (2.0, 6.0) if "uniform" in topic.lower() else (4.0, 8.0)
        acceleration = speed**2 / radius
        omega = speed / radius
        if "uniform" in topic.lower():
            period = 2.0 * math.pi / omega
            return (
                f"A marker travels at constant speed v={format_scalar(speed)} m/s around a circle of radius r={format_scalar(radius)} m.",
                f"omega=v/r={format_scalar(omega)} rad/s, so one full lap takes T=2pi/omega={format_scalar(period)} s while speed stays {format_scalar(speed)} m/s.",
                f"This teaches {topic} by keeping the speedometer fixed while the velocity arrow rotates through one complete lap.",
                f"What changes during the lap in this {topic} example?",
                "Velocity direction changes continuously even though the speed does not.",
            )
        return (
            f"Compare velocity arrows for a particle at two nearby points on a circle with r={format_scalar(radius)} m and speed v={format_scalar(speed)} m/s.",
            f"Their difference points inward; in the small-angle limit ar=v^2/r={format_scalar(acceleration)} m/s^2.",
            f"This teaches {topic} by constructing the inward acceleration from the change between two tangent velocity vectors.",
            f"What points inward in this {topic} construction?",
            "The velocity-difference vector, and therefore the acceleration vector, points toward the center.",
        )
    if visual == "physics_rotation":
        radius, force, duration = 0.5, 6.0, 2.0
        torque = radius * force
        angular_impulse = torque * duration
        return (
            f"Apply a perpendicular F={format_scalar(force)} N force at lever arm r={format_scalar(radius)} m for dt={format_scalar(duration)} s.",
            f"The torque is {format_scalar(torque)} N m, so the {format_scalar(duration)} s angular impulse is {format_scalar(angular_impulse)} kg m^2/s.",
            f"This teaches {topic} by turning a tangential push into angular momentum that accumulates over the stated interval.",
            f"What would halve the torque in this {topic} example without changing force?",
            "Halving the perpendicular lever arm halves the torque.",
        )
    if visual == "physics_recoil":
        launcher_mass, projectile_mass, projectile_speed = 4.0, 0.2, 20.0
        launcher_speed = -projectile_mass * projectile_speed / launcher_mass
        return (
            f"A {format_scalar(launcher_mass)} kg launcher fires a {format_scalar(projectile_mass)} kg projectile at {format_scalar(projectile_speed)} m/s in the ground frame from rest.",
            f"Zero total momentum gives v_launcher={format_scalar(launcher_speed)} m/s, opposite the projectile; their relative speed is {format_scalar(projectile_speed - launcher_speed)} m/s.",
            f"This teaches {topic} by keeping signed velocities and the chosen reference frame visible.",
            f"Why is the launcher velocity negative in this {topic} example?",
            "The sign marks motion opposite the projectile so the two momenta sum to zero.",
        )
    if visual == "physics_wave":
        wavelength = 1 + (seed % 5)
        frequency = 2 + ((seed // 7) % 8)
        speed_value = wavelength * frequency
        return (
            f"A wave has wavelength {wavelength} m and frequency {frequency} Hz.",
            f"Its speed is v=lambda f = {wavelength}*{frequency} = {speed_value} m/s.",
            f"This teaches {topic} by tying the moving pattern to measurable spacing and timing.",
            f"What two measurements determine speed in this {topic} example?",
            "Wavelength and frequency determine the wave speed.",
        )
    if visual == "physics_force":
        if "laws of motion" in topic.lower():
            mass_a, mass_b, interaction_force = 2.0, 3.0, 6.0
            acceleration_a = -interaction_force / mass_a
            acceleration_b = interaction_force / mass_b
            return (
                f"Two skaters with mA={format_scalar(mass_a)} kg and mB={format_scalar(mass_b)} kg push each other with interaction force F={format_scalar(interaction_force)} N.",
                f"Forces on A and B are -{format_scalar(interaction_force)} N and +{format_scalar(interaction_force)} N; accelerations are aA={format_scalar(acceleration_a)} m/s^2 and aB={format_scalar(acceleration_b)} m/s^2.",
                f"This teaches {topic} by separating the equal-and-opposite interaction pair from each skater's mass-dependent acceleration.",
                f"Why are the accelerations unequal in this {topic} example?",
                "The forces are equal in magnitude, but acceleration is force divided by each skater's different mass.",
            )
        mass = 1 + (seed % 5)
        push = 6 + ((seed // 5) % 10)
        friction = 1 + ((seed // 11) % min(5, push - 1))
        net = push - friction
        accel = net / mass
        return (
            f"A {mass} kg cart feels a {push} N push and {friction} N friction.",
            f"Net force is {net} N, so acceleration is a=F/m={net}/{mass}={format_scalar(accel)} m/s^2.",
            f"This teaches {topic} by separating individual forces from the net force that changes motion.",
            f"What should be computed before acceleration in this {topic} example?",
            "Compute the net force first, then divide by mass.",
        )
    raise ValueError(f"Physics visual {visual!r} has no source-example synthesizer.")


def economics_model_source_example(title: str) -> tuple[str, str, str, str, str] | None:
    """Author one worked example from the exact resolved economics scenario."""
    model = resolve_economics_model(title)
    if model is None:
        return None
    scenario = get_economics_model_scenario(model.model_id).as_dict()
    setup = scenario["setup"]
    result = scenario["results"]
    model_id = model.model_id

    def value(source: dict[str, object], key: str) -> str:
        number = float(source[key])
        if math.isfinite(number) and abs(number - round(number)) < 1e-9:
            return str(int(round(number)))
        return f"{number:.6f}".rstrip("0").rstrip(".")

    def s(key: str) -> str:
        return value(setup, key)

    def r(key: str) -> str:
        return value(result, key)

    if model_id in {"supply_demand_intro", "supply_demand_curves"}:
        return (
            f"At P={s('price')}, demand is Qd={s('demand_intercept')}-{s('demand_slope')}P and supply is Qs={s('supply_intercept')}+{s('supply_slope')}P.",
            f"Qd={r('quantity_demanded')} and Qs={r('quantity_supplied')}, so the market gap is {r('market_gap')}.",
            "The same price clears the market because quantity demanded equals quantity supplied.",
            "How do we verify that this price clears the market?",
            f"Substitute P={s('price')}; both schedules give quantity {r('quantity_demanded')}.",
        )
    if model_id == "market_equilibrium":
        return (
            f"Demand is Qd={s('demand_intercept')}-{s('demand_slope')}P and supply is Qs={s('supply_intercept')}+{s('supply_slope')}P.",
            f"Setting Qd=Qs gives P={r('equilibrium_price')} and Q={r('equilibrium_quantity')}; both schedules equal {r('quantity_demanded')}.",
            "Market equilibrium is the price-quantity pair where the two retained schedules agree.",
            "Which equality identifies the market equilibrium?",
            f"Qd=Qs={r('equilibrium_quantity')} at P={r('equilibrium_price')}.",
        )
    if model_id == "demand_curve":
        return (
            f"Use Qd={s('demand_intercept')}-{s('own_price_slope')}P+{s('income_coefficient')}I+{s('cross_price_coefficient')}Py+{s('taste_shift')}, with P={s('own_price')}, I={s('income')}, and Py={s('related_good_price')}.",
            f"Holding income, the related-good price, and tastes fixed gives Qd={r('quantity_demanded')} at own price {r('own_price')}.",
            "A demand curve traces own price against quantity while other demand shifters stay fixed.",
            "What stays fixed while tracing this demand curve?",
            "Income, the related-good price, and tastes stay fixed.",
        )
    if model_id == "supply_curve":
        return (
            f"Use Qs={s('supply_intercept')}+{s('output_price_slope')}P-{s('wage_coefficient')}w-{s('rental_coefficient')}r+{s('technology_coefficient')}A, with P={s('output_price')}, w={s('wage')}, r={s('rental_price')}, and A={s('technology')}.",
            f"Holding input prices and technology fixed gives Qs={r('quantity_supplied')} at output price {r('output_price')}.",
            "A supply curve traces output price against quantity while supply shifters stay fixed.",
            "What stays fixed while tracing this supply curve?",
            "Wages, rental price, and technology stay fixed.",
        )
    if model_id == "comparative_statics":
        return (
            f"Demand shifts from Qd={s('initial_demand_intercept')}-{s('demand_slope')}P to Qd={s('new_demand_intercept')}-{s('demand_slope')}P while Qs={s('supply_intercept')}+{s('supply_slope')}P stays fixed.",
            f"Equilibrium moves from (P,Q)=({r('initial_equilibrium_price')},{r('initial_equilibrium_quantity')}) to ({r('new_equilibrium_price')},{r('new_equilibrium_quantity')}), changes of {r('price_change')} and {r('quantity_change')}.",
            "Comparative statics changes one schedule and compares the two resulting equilibria.",
            "Which object is held fixed in this comparison?",
            "The supply schedule is held fixed while demand shifts outward.",
        )
    if model_id == "price_ceiling_shortage":
        return (
            f"The market equilibrium price is {r('equilibrium_price')}; impose a ceiling at {s('ceiling_price')} on Qd={s('demand_intercept')}-{s('demand_slope')}P and Qs={s('supply_intercept')}+{s('supply_slope')}P.",
            f"At the ceiling, Qd={r('quantity_demanded')} and Qs={r('quantity_supplied')}, so shortage={r('shortage')}.",
            "A ceiling below equilibrium binds and creates excess demand.",
            "Why does this price ceiling bind?",
            f"Its price {s('ceiling_price')} is below equilibrium {r('equilibrium_price')}.",
        )
    if model_id == "price_floor_surplus":
        return (
            f"The market equilibrium price is {r('equilibrium_price')}; impose a floor at {s('floor_price')} on Qd={s('demand_intercept')}-{s('demand_slope')}P and Qs={s('supply_intercept')}+{s('supply_slope')}P.",
            f"At the floor, Qd={r('quantity_demanded')} and Qs={r('quantity_supplied')}, so surplus={r('surplus')}.",
            "A floor above equilibrium binds and creates excess supply.",
            "Why does this price floor bind?",
            f"Its price {s('floor_price')} is above equilibrium {r('equilibrium_price')}.",
        )
    if model_id == "price_controls":
        return (
            f"With equilibrium price {r('equilibrium_price')}, compare a ceiling at {s('ceiling_price')} with a floor at {s('floor_price')} on the same demand and supply schedules.",
            f"The ceiling creates shortage {r('ceiling_shortage')}; the floor creates surplus {r('floor_surplus')}.",
            "The direction of the market imbalance depends on which side of equilibrium the control fixes price.",
            "What imbalances do the two binding controls create?",
            f"The ceiling creates shortage {r('ceiling_shortage')}, while the floor creates surplus {r('floor_surplus')}.",
        )
    if model_id in {"consumer_preferences", "utility_representation"}:
        score_a = "bundle_a_score" if model_id == "consumer_preferences" else "utility_a"
        score_b = "bundle_b_score" if model_id == "consumer_preferences" else "utility_b"
        return (
            f"Compare bundle A=({s('bundle_a_x')},{s('bundle_a_y')}) with bundle B=({s('bundle_b_x')},{s('bundle_b_y')}).",
            f"The same utility representation assigns A={r(score_a)} and B={r(score_b)}, so bundle A is ranked higher.",
            "Utility numbers represent the bundle ranking; their ordering, not their units, carries the preference.",
            "Which bundle is preferred under this utility representation?",
            f"Bundle A, because {r(score_a)} exceeds {r(score_b)}.",
        )
    if model_id == "budget_constraint":
        return (
            f"Income is {s('income')}, prices are px={s('price_x')} and py={s('price_y')}, and the candidate bundle is ({s('bundle_x')},{s('bundle_y')}).",
            f"Expenditure is {r('expenditure')}, leaving slack {r('budget_slack')}; the intercepts are {r('x_intercept')} and {r('y_intercept')} and slope is {r('budget_slope')}.",
            "Affordability and budget geometry come from the same income and prices.",
            "Is the candidate bundle affordable?",
            f"Yes; expenditure {r('expenditure')} is below income {s('income')} by {r('budget_slack')}.",
        )
    if model_id == "marginal_rate_of_substitution":
        return (
            f"At bundle (x,y)=({s('quantity_x')},{s('quantity_y')}), compare the two marginal utilities along one indifference curve.",
            f"MUx={r('marginal_utility_x')} and MUy={r('marginal_utility_y')}, so MRS=MUx/MUy={r('MRS')} and the curve slope is {r('curve_slope')}.",
            "The indifference-curve slope is the negative of the marginal willingness to trade y for x.",
            "What is the indifference-curve slope at this bundle?",
            f"It is -MRS={r('curve_slope')}.",
        )
    if model_id == "consumer_choice":
        return (
            f"A consumer has income {s('income')}, px={s('price_x')}, py={s('price_y')}, and Cobb-Douglas share on x of {s('utility_share_x')}.",
            f"The tangency choice is x={r('chosen_x')} and y={r('chosen_y')}; expenditure is exactly {r('expenditure')}.",
            "The utility-maximizing bundle satisfies the tangency condition and exhausts the same budget.",
            "How can we check this chosen bundle is feasible?",
            f"Its expenditure is {r('expenditure')}, exactly equal to income {s('income')}.",
        )
    if model_id == "income_substitution_effects":
        return (
            f"Quantity starts at {s('initial_quantity')}, moves to compensated quantity {s('compensated_quantity')}, then to final quantity {s('final_quantity')}.",
            f"The substitution effect is {r('substitution_effect')}, the income effect is {r('income_effect')}, and total change is {r('total_change')}.",
            "The compensated bundle separates the substitution movement from the income movement.",
            "How does the total quantity change decompose?",
            f"{r('substitution_effect')} from substitution plus {r('income_effect')} from income equals {r('total_change')}.",
        )
    if model_id in {"own_price_elasticity", "income_elasticity", "cross_price_elasticity"}:
        if model_id == "own_price_elasticity":
            setup_text = f"Own price rises from {s('initial_price')} to {s('new_price')} while quantity falls from {s('initial_quantity')} to {s('new_quantity')}."
            calc_text = f"Quantity changes {r('percent_quantity_change')} and price changes {r('percent_own_price_change')}, so own-price elasticity is {r('own_price_elasticity')}."
            answer = f"It is {r('own_price_elasticity')}, the quantity percentage change divided by the own-price percentage change."
        elif model_id == "income_elasticity":
            setup_text = f"Income rises from {s('initial_income')} to {s('new_income')} while quantity rises from {s('initial_quantity')} to {s('new_quantity')}."
            calc_text = f"Both proportional changes are {r('percent_quantity_change')}, so income elasticity is {r('income_elasticity')} and the good is normal."
            answer = f"It is {r('income_elasticity')}, so quantity rises proportionally with income."
        else:
            setup_text = f"Good y's price rises from {s('initial_price_y')} to {s('new_price_y')} while quantity of x rises from {s('initial_quantity_x')} to {s('new_quantity_x')}."
            calc_text = f"Quantity x changes {r('percent_quantity_x_change')} and price y changes {r('percent_price_y_change')}, so cross-price elasticity is {r('cross_price_elasticity')} and the goods are substitutes."
            answer = f"It is {r('cross_price_elasticity')}; the positive sign identifies substitutes."
        return setup_text, calc_text, "Elasticity uses two changes from one retained before-and-after scenario.", "What does the computed elasticity say?", answer
    if model_id == "production_function":
        return (
            f"Technology is {s('technology')} with labor {s('labor')}, capital {s('capital')}, and labor share {s('labor_share')}.",
            f"The production surface gives output {r('output')}, MPL={r('marginal_product_labor')}, and MPK={r('marginal_product_capital')}.",
            "One labor-capital bundle determines output and both marginal products on the same production surface.",
            "What output does this input bundle produce?",
            f"It produces {r('output')} units.",
        )
    if model_id in {"labor_market", "labor_input_market", "capital_input_market"}:
        if model_id == "labor_market":
            return (
                f"Labor demand is {s('labor_demand_intercept')}-{s('labor_demand_slope')}w and labor supply is {s('labor_supply_intercept')}+{s('labor_supply_slope')}w.",
                f"Their intersection gives wage {r('equilibrium_wage')} and employment {r('employment')}, where labor demanded and supplied both equal {r('employment')}.",
                "The labor market clears where labor demand equals labor supply.",
                "What wage clears this labor market?",
                f"Wage {r('equilibrium_wage')} clears it at employment {r('employment')}.",
            )
        factor = "labor" if model_id == "labor_input_market" else "capital"
        price_key = "wage" if factor == "labor" else "rental_price"
        input_key = "labor_input" if factor == "labor" else "capital_input"
        product_key = "marginal_product_labor" if factor == "labor" else "marginal_product_capital"
        mrp_key = "marginal_revenue_product_labor" if factor == "labor" else "marginal_revenue_product_capital"
        return (
            f"The firm faces {factor} price {s(price_key)} and marginal revenue {s('marginal_revenue')} with a declining marginal product schedule.",
            f"At {factor} input {r(input_key)}, marginal product is {r(product_key)}, so MRP={s('marginal_revenue')}*{r(product_key)}={r(mrp_key)} equals the factor price.",
            f"Derived {factor} demand chooses the input where marginal revenue product equals its price.",
            f"What condition chooses the firm's {factor} input?",
            f"Choose {r(input_key)} units where MRP={r(mrp_key)} equals price {s(price_key)}.",
        )
    if model_id == "factor_input_markets":
        return (
            f"A firm with technology {s('technology')} must produce {s('target_output')} using labor at wage {s('wage')} and capital at rental price {s('rental_price')}.",
            f"Cost minimization gives L={r('labor_input')}, K={r('capital_input')}, K/L={r('capital_labor_ratio')}, and MRTS={r('MRTS_labor_for_capital')}=w/r={r('factor_price_ratio')}; output is {r('produced_output')} and cost is {r('minimum_cost')}.",
            "The cost-minimizing isoquant tangency matches the technical tradeoff to the factor-price ratio.",
            "Which equality verifies the cost-minimizing input mix?",
            f"MRTS={r('MRTS_labor_for_capital')} equals w/r={r('factor_price_ratio')} while output remains {r('produced_output')}.",
        )
    if model_id == "intertemporal_choice":
        return (
            f"Income is {s('income_now')} now and {s('income_later')} later, the interest rate is {s('interest_rate')}, and chosen current consumption is {s('chosen_consumption_now')}.",
            f"Present-value wealth is {r('present_value_wealth')}; choosing c0={r('chosen_consumption_now')} leaves c1={r('chosen_consumption_later')} and saving {r('saving_now')}.",
            "Current and future consumption lie on one present-value budget linked by the interest rate.",
            "How is this intertemporal choice budget-feasible?",
            f"{r('chosen_consumption_now')}+{r('chosen_consumption_later')}/(1+{s('interest_rate')})={r('present_value_wealth')}.",
        )
    if model_id == "cost_curves":
        return (
            f"At output {s('output')}, fixed cost is {s('fixed_cost')} and variable cost is {s('variable_linear_cost')}q+{s('variable_quadratic_cost')}q^2.",
            f"FC={r('FC')}, VC={r('VC')}, TC={r('TC')}, AC={r('AC')}, AVC={r('AVC')}, and MC={r('MC')}.",
            "All five cost measures reconcile at the same output and cost function.",
            "Which equality checks total cost here?",
            f"TC=FC+VC={r('FC')}+{r('VC')}={r('TC')}.",
        )
    if model_id == "perfect_competition":
        return (
            f"A price-taking firm faces P={s('market_price')}, MC={s('marginal_cost_intercept')}+{s('marginal_cost_slope')}q, and fixed cost {s('fixed_cost')}.",
            f"P=MC={r('price')} (and MR={r('marginal_revenue')}) gives q={r('chosen_output')}; revenue {r('total_revenue')} minus cost {r('total_cost')} gives profit {r('profit')}.",
            "The competitive firm takes price as fixed and chooses output where price equals marginal cost.",
            "What output maximizes this competitive firm's profit?",
            f"q={r('chosen_output')}, where P=MC={r('price')}.",
        )
    if model_id == "competitive_shutdown":
        return (
            f"Market price is {s('market_price')}, minimum AVC is {s('minimum_average_variable_cost')}, and fixed cost is {s('fixed_cost')}.",
            f"P-min AVC={r('price_minus_minimum_AVC')}<0, so chosen output is {r('chosen_output')} and short-run profit is {r('short_run_profit')}.",
            "Below minimum average variable cost, shutting down avoids variable cost but not fixed cost.",
            "Why does this firm shut down?",
            f"Price {s('market_price')} is below minimum AVC {s('minimum_average_variable_cost')}.",
        )
    if model_id in {"monopoly", "marginal_revenue", "price_discrimination"}:
        if model_id == "monopoly":
            return (
                f"A monopolist faces P={s('demand_intercept')}-{s('demand_slope')}Q, MC={s('marginal_cost')}, and fixed cost {s('fixed_cost')}.",
                f"MR=MC gives Q={r('monopoly_quantity')}; demand gives P={r('monopoly_price')}, and profit is {r('profit')}.",
                "The monopolist chooses quantity with marginal revenue, then reads price from demand.",
                "Why is monopoly price read from demand rather than MR?",
                f"MR chooses Q={r('monopoly_quantity')}; demand values that quantity at P={r('monopoly_price')}.",
            )
        if model_id == "marginal_revenue":
            return (
                f"Demand is P={s('demand_intercept')}-{s('demand_slope')}Q at Q={s('quantity')}.",
                f"Price is {r('price')} and total revenue is {r('total_revenue')}; the quantity-price effect leaves marginal revenue {r('marginal_revenue')}.",
                "Marginal revenue includes the gain on the next unit and the price reduction on prior units.",
                "Why is marginal revenue below price here?",
                f"The quantity-price effect is {r('quantity_price_effect')}, reducing marginal revenue to {r('marginal_revenue')}.",
            )
        return (
            f"Two separated markets have demands P1={s('demand_1_intercept')}-{s('demand_1_slope')}q1 and P2={s('demand_2_intercept')}-{s('demand_2_slope')}q2, with MC={s('marginal_cost')} and fixed cost {s('fixed_cost')}.",
            f"MR1=MR2=MC={r('common_marginal_revenue')} gives q1={r('market_1_quantity')}, q2={r('market_2_quantity')}; demand gives P1={r('market_1_price')}, P2={r('market_2_price')}, and profit {r('profit')}.",
            "Price discrimination equalizes marginal revenue across markets before reading each price from its demand.",
            "What condition allocates output across the two markets?",
            f"MR1=MR2=MC={r('common_marginal_revenue')}.",
        )
    if model_id in {"oligopoly", "oligopoly_collusion"}:
        demand = f"P={s('demand_intercept')}-{s('demand_slope')}Q"
        if model_id == "oligopoly":
            return (
                f"Two symmetric Cournot firms face {demand} and MC={s('marginal_cost')}, choosing quantities simultaneously.",
                f"Mutual best responses give q1=q2={r('firm_1_quantity')}, so Q={r('total_quantity')}, P={r('market_price')}, and each firm's profit is {r('firm_1_profit')}.",
                "Cournot-Nash output is the intersection of the two firms' quantity best responses.",
                "What makes this Cournot quantity pair stable?",
                f"At q1=q2={r('firm_1_quantity')}, each quantity is a best response to the other.",
            )
        return (
            f"Two symmetric firms face {demand} and MC={s('marginal_cost')}; compare Cournot-Nash with equal sharing of joint-profit-maximizing collusion.",
            f"Cournot has q1=q2={r('cournot_firm_quantity')}, QN={r('cournot_total_quantity')}, PN={r('cournot_price')}, and profit {r('cournot_firm_profit')} each; collusion restricts each to {r('collusive_firm_quantity')}, QC={r('collusive_total_quantity')}, raises PC={r('collusive_price')}, and raises profit to {r('collusive_firm_profit')} each.",
            f"Joint output falls by {r('output_restriction')}, so price rises by {r('price_increase')} and per-firm profit rises from {r('cournot_firm_profit')} to {r('collusive_firm_profit')}.",
            "How does joint-profit-maximizing collusion differ from Cournot-Nash here?",
            f"It restricts Q from {r('cournot_total_quantity')} to {r('collusive_total_quantity')}, raising P from {r('cournot_price')} to {r('collusive_price')} and each profit from {r('cournot_firm_profit')} to {r('collusive_firm_profit')}.",
        )
    if model_id in {"strategic_game", "nash_equilibrium", "dominant_strategy"}:
        matrix = (
            f"A,A=({s('row_aa')},{s('column_aa')}), A,B=({s('row_ab')},{s('column_ab')}), "
            f"B,A=({s('row_ba')},{s('column_ba')}), and B,B=({s('row_bb')},{s('column_bb')})"
        )
        if model_id == "nash_equilibrium":
            return (f"Two players choose A or B; payoffs are {matrix}.", f"Marking mutual best responses gives {r('nash_equilibrium_count')} Nash cells; the largest Nash total payoff is {r('largest_nash_total_payoff')}.", "Nash equilibrium is an intersection of unilateral best responses in the retained payoff matrix.", "How is a Nash cell checked?", "Hold the rival action fixed and verify neither player gains by deviating alone.")
        if model_id == "dominant_strategy":
            return (f"Two players choose A or B; payoffs are {matrix}.", f"Strategy B dominates A for both players, so B,B is the dominant-strategy equilibrium with total payoff {r('dominant_equilibrium_total_payoff')}.", "Dominance compares one player's payoff across every fixed rival action.", "Which strategy is dominant for both players?", "Strategy B, because it gives each player the higher payoff against either rival action.")
        return (f"Two players choose A or B; payoffs are {matrix}.", f"The game has {r('strategy_profiles')} profiles; the largest individual payoff is {r('largest_row_payoff')} and joint payoff at A,A is {r('payoff_sum_at_aa')}.", "A normal-form game keeps players, strategies, and both payoffs visible for every profile.", "What must every cell of this game report?", "It reports one payoff for each player at that strategy profile.")
    if model_id in {"consumer_surplus", "producer_surplus", "total_surplus", "welfare_surplus", "equity_efficiency"}:
        if model_id == "consumer_surplus":
            return (f"Demand's choke price is {s('choke_price')}, market price is {s('market_price')}, and quantity is {s('quantity')}.", f"Consumer surplus is 1/2*({s('choke_price')}-{s('market_price')})*{s('quantity')}={r('CS')}.", "Consumer surplus is the willingness-to-pay area above market expenditure.", "What area measures consumer surplus?", f"The demand triangle above price, with area {r('CS')}.")
        if model_id == "producer_surplus":
            return (f"Supply begins at price {s('supply_intercept_price')}, market price is {s('market_price')}, and quantity is {s('quantity')}.", f"Producer surplus is 1/2*({s('market_price')}-{s('supply_intercept_price')})*{s('quantity')}={r('PS')}.", "Producer surplus is the price-above-cost area below the market price.", "What area measures producer surplus?", f"The supply triangle below price, with area {r('PS')}.")
        if model_id == "total_surplus":
            return (f"At one market allocation, consumer surplus is {s('consumer_surplus')} and producer surplus is {s('producer_surplus')}.", f"Total surplus is CS+PS={r('CS')}+{r('PS')}={r('TS')}.", "Total surplus adds buyer and seller gains from the same trades.", "How is total surplus computed?", f"CS+PS={r('TS')}.")
        if model_id == "equity_efficiency":
            return (f"Two people move from payoffs ({s('person_1_before')},{s('person_2_before')}) to ({s('person_1_after')},{s('person_2_after')}).", f"Total welfare stays {r('social_welfare_before')} to {r('social_welfare_after')}, so efficiency gain is {r('efficiency_gain')}, while the equity gap shrinks by {r('equity_gap_reduction')}.", "A distribution can become more equal without changing total measured welfare.", "What changes, and what stays fixed, in this redistribution?", f"The equity gap falls by {r('equity_gap_reduction')}; total welfare stays {r('social_welfare_after')}.")
        return (f"Marginal benefit is {s('marginal_benefit_intercept')}-{s('marginal_benefit_slope')}Q and marginal cost is {s('marginal_cost_intercept')}+{s('marginal_cost_slope')}Q.", f"MB=MC gives efficient Q={r('efficient_quantity')} and P={r('equilibrium_price')}; CS={r('CS')}, PS={r('PS')}, and TS={r('TS')}.", "Welfare is maximized where marginal benefit equals marginal cost, using surplus from the same allocation.", "What quantity maximizes total surplus?", f"Q={r('efficient_quantity')}, where MB=MC={r('equilibrium_price')}.")
    if model_id in {"tax_incidence", "tax_deadweight_loss"}:
        if model_id == "tax_incidence":
            return (f"A tax of {s('tax')} enters a market with pre-tax price {s('pre_tax_price')}, demand elasticity {s('absolute_demand_elasticity')}, and supply elasticity {s('supply_elasticity')}.", f"Buyers bear {r('buyer_burden')} and pay {r('buyer_price')}; sellers bear {r('seller_burden')} and receive {r('seller_price')}; the wedge is {r('tax_wedge')}.", "The less elastic side bears more of the same tax wedge.", "Which side bears more of this tax?", f"Sellers bear {r('seller_burden')}, more than buyers' {r('buyer_burden')}.")
        return (f"A tax of {s('tax')} reduces quantity from {s('quantity_before_tax')} to {s('quantity_after_tax')}.", f"Quantity falls by {r('quantity_reduction')}; revenue is {s('tax')}*{s('quantity_after_tax')}={r('tax_revenue')} and DWL=1/2*{s('tax')}*{r('quantity_reduction')}={r('DWL')}.", "Tax revenue and deadweight loss use the same wedge and post-tax quantity.", "What creates the deadweight-loss triangle?", f"The tax eliminates {r('quantity_reduction')} trades, producing DWL {r('DWL')}.")
    if model_id in {"externality", "coase_bargaining", "common_resource", "public_good"}:
        if model_id == "externality":
            return (f"Marginal benefit is {s('benefit_intercept')}-{s('benefit_slope')}Q, private cost is {s('private_cost_intercept')}+{s('private_cost_slope')}Q, and external cost is {s('external_cost_per_unit')} per unit.", f"The private market chooses Q={r('market_quantity')}; adding external cost moves the efficient quantity to {r('efficient_quantity')}, so overproduction is {r('overproduction')}.", "The social-cost wedge reduces output from the private-market quantity to the efficient quantity.", "Which quantity accounts for the external damage?", f"The efficient quantity {r('efficient_quantity')}, found with marginal social cost.")
        if model_id == "coase_bargaining":
            return (f"Abatement benefit is {s('abatement_benefit_intercept')}-{s('abatement_benefit_slope')}A, abatement cost is {s('abatement_cost_intercept')}+{s('abatement_cost_slope')}A, and transaction costs are {s('transaction_costs')}.", f"MB=MC={r('marginal_benefit')} at abatement {r('efficient_abatement')}; gross gains {r('gross_bargaining_gains')} minus transaction costs give net gains {r('net_bargaining_gains')}.", "Bargaining can reach efficient abatement when net gains remain positive after transaction costs.", "Is bargaining feasible in this scenario?", f"Yes; net gains remain {r('net_bargaining_gains')} after transaction costs.")
        if model_id == "common_resource":
            return (f"A common resource has benefit {s('benefit_intercept')}-{s('benefit_slope')}Q, private cost {s('private_cost_intercept')}+{s('private_cost_slope')}Q, and rising external cost.", f"Open access yields Q={r('open_access_quantity')}; including external cost gives efficient Q={r('efficient_quantity')}, so overuse is {r('overuse')}.", "Open access ignores the congestion or depletion cost imposed on other users.", "How much does open access overuse the resource?", f"By {r('overuse')} units relative to efficient quantity {r('efficient_quantity')}.")
        return (f"Person 1 has MB1={s('person_1_benefit_intercept')}-{s('person_1_benefit_slope')}G, person 2 has MB2={s('person_2_benefit_intercept')}-{s('person_2_benefit_slope')}G, and MC={s('marginal_cost_intercept')}+{s('marginal_cost_slope')}G.", f"Vertical summation and SMB=MC give G={r('efficient_public_good_quantity')}, with SMB=MC={r('social_marginal_benefit')} and net benefit {r('total_net_benefit')}.", "Public-good willingness to pay adds vertically at the same shared quantity.", "How are the two marginal benefits combined?", f"Add them vertically at G={r('efficient_public_good_quantity')} before setting SMB=MC.")
    if model_id in {"international_trade", "tariff"}:
        if model_id == "international_trade":
            return (f"Domestic demand is {s('demand_intercept')}-{s('demand_slope')}P, supply is {s('supply_intercept')}+{s('supply_slope')}P, and world price is {s('world_price')}.", f"Autarky has P={r('autarky_price')}, Q={r('autarky_quantity')}; at world price, demand is {r('domestic_demand')}, supply is {r('domestic_supply')}, and imports are {r('imports')}.", "A world price below autarky price creates imports equal to domestic demand minus domestic supply.", "How many units does this economy import?", f"{r('domestic_demand')}-{r('domestic_supply')}={r('imports')} units.")
        return (f"Use the same domestic demand and supply with world price {s('world_price')} and tariff {s('tariff')}.", f"Domestic price rises to {r('domestic_price')}; demand becomes {r('domestic_demand_after')}, supply {r('domestic_supply_after')}, imports fall from {r('imports_before')} to {r('imports_after')}, revenue is {r('tariff_revenue')}, and DWL is {r('tariff_deadweight_loss')}.", "The tariff raises domestic price, contracts imports, raises revenue, and creates two distortion triangles.", "What happens to imports under this tariff?", f"They fall by {r('import_reduction')}, from {r('imports_before')} to {r('imports_after')}.")
    if model_id in {"choice_under_uncertainty", "social_insurance", "adverse_selection", "moral_hazard"}:
        if model_id == "choice_under_uncertainty":
            return (f"A loss occurs with probability {s('loss_probability')}, paying {s('loss_payoff')}; otherwise payoff is {s('no_loss_payoff')}.", f"Expected payoff is {r('expected_payoff')}, expected utility is {r('expected_utility')}, certainty equivalent is {r('certainty_equivalent')}, and risk premium is {r('risk_premium')}.", "Concave utility makes the certainty equivalent lower than the expected payoff by the risk premium.", "What is the risk premium in this lottery?", f"{r('expected_payoff')}-{r('certainty_equivalent')}={r('risk_premium')}.")
        if model_id == "social_insurance":
            return (f"Initial wealth is {s('initial_wealth')}; loss {s('loss')} occurs with probability {s('loss_probability')}, while insurance contribution is {s('contribution')} and benefit is {s('benefit')}.", f"Consumption is {r('loss_state_consumption')} after loss and {r('no_loss_state_consumption')} without loss, leaving gap {r('consumption_gap')} and expected utility {r('expected_utility')}.", "Social insurance uses contributions and benefits to smooth consumption across states.", "How much consumption risk remains after insurance?", f"The state consumption gap is {r('consumption_gap')}.")
        if model_id == "adverse_selection":
            return (f"High-risk share is {s('high_risk_share')}, loss cost is {s('loss_cost')}, high- and low-risk probabilities are {s('high_risk_probability')} and {s('low_risk_probability')}, and {s('low_risk_exit_rate')} of low risks exit.", f"Fair premiums are {r('high_risk_fair_premium')} and {r('low_risk_fair_premium')}; pooling starts at {r('pooling_premium')} and rises to {r('post_exit_pooling_premium')} after exit.", "Hidden risk and low-risk exit raise the pooled premium by worsening the remaining risk mix.", "Why does the pooling premium rise?", f"Low-risk exit raises the high-risk share to {r('post_exit_high_risk_share')}, pushing premium to {r('post_exit_pooling_premium')}.")
        return (f"Insurance coverage is {s('coverage_rate')} on loss {s('loss_cost')}; effort falls from {s('uncovered_effort')} to {s('covered_effort')} and loss probability rises from {s('uncovered_loss_probability')} to {s('covered_loss_probability')}.", f"The probability increase is {r('loss_probability_increase')}; expected insurer cost becomes {r('expected_insurer_cost')} and patient loss cost is {r('expected_patient_loss_cost')}.", "Coverage lowers the patient's marginal loss exposure, reducing effort and increasing hidden-action risk.", "What behavioral change creates moral hazard here?", f"Effort falls by {r('effort_change')} and loss probability rises by {r('loss_probability_increase')}.")
    if model_id == "behavioral_economics":
        return (f"Utility is {s('now_utility')} now or {s('later_utility')} after {s('delay_periods')} period, with discount factor {s('discount_factor')} and present-bias factor {s('present_bias')}.", f"The benchmark later value is {r('benchmark_later_value')}, but present bias lowers it to {r('behavioral_later_value')}, a gap of {r('present_bias_value_gap')}, reversing choice toward now.", "Present bias adds an extra discount to delayed utility beyond exponential discounting.", "Why does the observed choice switch to now?", f"Present bias lowers later value from {r('benchmark_later_value')} to {r('behavioral_later_value')}, below now utility {s('now_utility')}.")
    if model_id == "health_economics":
        return (f"Healthcare marginal benefit is {s('marginal_benefit_intercept')}-{s('marginal_benefit_slope')}Q, marginal cost is {s('marginal_cost_intercept')}+{s('marginal_cost_slope')}Q, resource price is {s('resource_price')}, and insurance covers {s('insurance_coverage_rate')}.", f"The efficient quantity is {r('efficient_health_care_quantity')}; coverage lowers patient price to {r('patient_price')}, raises demand to {r('patient_demanded_quantity')}, and creates overuse {r('insurance_induced_overuse')}.", "Insurance separates patient price from resource cost, expanding care beyond the efficient quantity.", "How much insurance-induced overuse occurs?", f"Demand exceeds the efficient quantity by {r('insurance_induced_overuse')} units.")

    route = resolve_economics_video_route(model_id, fail_closed=True)
    setup_values = ", ".join(f"{key}={value(setup, key)}" for key in setup)
    result_values = ", ".join(f"{key}={value(result, key)}" for key in result)
    return (
        f"Use the {scenario['mode']} scenario with {setup_values}.",
        f"The scenario resolves to {result_values}.",
        str(route.invariant),
        f"Which result verifies the {scenario['mode']} mechanism?",
        str(route.verification[-1]),
    )


def concrete_source_example(title: str, domain: str | None, visual: str) -> tuple[str, str, str, str, str]:
    topic = title.strip() or "the concept"
    seed = stable_example_seed(topic)
    if domain == "group_theory":
        if visual == "algebra_ring_structure":
            return (
                "Work in the integers and compare 2(3+4) with 2*3+2*4.",
                "The left side is 2*7=14, while the right side is 6+8=14, so distributivity preserves the same result.",
                f"This teaches {topic} by applying both ring operations to the same persistent elements.",
                f"Which law links addition and multiplication in this {topic} example?",
                "Distributivity requires a(b+c)=ab+ac for every three ring elements.",
            )
        if visual == "algebra_ideal_quotient":
            return (
                "In the ring of integers, let I be the ideal of all multiples of 3.",
                "Adding multiples of 3 stays in I, and multiplying 6 by any integer r gives 6r in I; modulo I, every integer collapses to one of [0], [1], or [2].",
                f"This teaches {topic} by checking absorption before forming the quotient ring.",
                f"What must be verified before publishing the quotient in this {topic} example?",
                "The subset must be an ideal, including absorption under multiplication by arbitrary ring elements.",
            )
        if visual == "algebra_field_structure":
            return (
                "Work in Z5 and select the nonzero element 2.",
                "Testing candidates gives 2*1=2, 2*2=4, and 2*3=1 mod 5, so 3 is the inverse of 2 and 4/2=4*3=2 mod 5.",
                f"This teaches {topic} by retaining the inverse that turns a concrete division into multiplication.",
                f"Why does every nonzero element support division in this {topic} example?",
                "Because Z5 has prime modulus, every nonzero residue has a multiplicative inverse.",
            )
        if visual == "group_cosets":
            coset_count = 2 + (seed % 4)
            subgroup_size = 2 + ((seed // 5) % 3)
            modulus = coset_count * subgroup_size
            subgroup = [coset_count * i for i in range(subgroup_size)]
            cosets = [[(r + h) % modulus for h in subgroup] for r in range(coset_count)]
            setup = f"In Z{modulus} under addition, let H={{{','.join(map(str, subgroup))}}} and compare the cosets 0+H through {coset_count - 1}+H."
            calc = f"The cosets are " + ", ".join("{" + ",".join(map(str, block)) + "}" for block in cosets) + f"; {coset_count} equal blocks account for all {modulus} elements."
            return (
                setup,
                calc,
                f"This teaches {topic} by showing how one subgroup pattern organizes the whole group into equal-size blocks.",
                f"What would fail if the {topic} blocks overlapped?",
                "They would not form a clean partition, so the coset-counting argument would break.",
            )
        if visual == "group_homomorphism":
            target_mod = 2 + (seed % 4)
            source_mod = target_mod * (2 + ((seed // 7) % 3))
            a = 1 + ((seed // 11) % (source_mod - 1))
            b = 1 + ((seed // 17) % (source_mod - 1))
            lhs_input = (a + b) % source_mod
            lhs = lhs_input % target_mod
            rhs = ((a % target_mod) + (b % target_mod)) % target_mod
            setup = f"Use the map phi: Z{source_mod} -> Z{target_mod} where phi(k)=k mod {target_mod}."
            calc = f"phi({a}+{b})=phi({lhs_input})={lhs}, and phi({a})+phi({b})={a % target_mod}+{b % target_mod}={rhs} mod {target_mod}, so addition is preserved."
            return (
                setup,
                calc,
                f"This teaches {topic} by testing structure preservation on an explicit operation, not just naming a map.",
                f"How can you test whether a proposed {topic} preserves structure?",
                "Compute both phi(a*b) and phi(a)*phi(b) on a small pair and compare them.",
            )
        if visual == "group_action":
            sides = 3 + (seed % 4)
            angle = 360 // sides
            labels = [str(i) for i in range(1, sides + 1)]
            orbit = " -> ".join(labels + [labels[0]])
            setup = f"Let rotations of a regular {sides}-gon act on vertices {', '.join(labels)}; one turn rotates by {angle} degrees."
            calc = f"Repeated turns move {orbit}, so the orbit of vertex 1 has {sides} vertices and the identity is the only rotation fixing it."
            return (
                setup,
                calc,
                f"This teaches {topic} by making orbit and stabilizer visible on a concrete object.",
                f"What are the object and motion in this {topic} example?",
                "The object is a labeled vertex or corner, and the motion is a symmetry acting on it.",
            )
        modulus = 4 + (seed % 8)
        element = 1 + ((seed // 7) % (modulus - 1))
        inverse = (-element) % modulus
        order = modulus // math.gcd(element, modulus)
        setup = f"In Z{modulus}, add modulo {modulus}; select {element}."
        calc = f"{element}+{inverse}=0 mod {modulus}, so {inverse} is the inverse of {element}; after {order} repeated additions, {element} returns to 0."
        return (
            setup,
            calc,
            f"This teaches {topic} by checking identity, inverse, and repetition in the smallest useful setting.",
            f"What should you name first in a {topic} example?",
            "Name the set, operation, identity, and the element or subset being tested.",
        )

    if domain == "calculus":
        if visual == "calculus_area":
            slope = 2 * (1 + (seed % 4))
            right = 2 + ((seed // 5) % 5)
            height = slope * right
            area = slope * right * right // 2
            setup = f"Let f(x)={slope}x on the interval from 0 to {right}."
            calc = f"The area is a triangle with base {right} and height {height}, so area = {area}; the integral gives {slope}/2*x^2 from 0 to {right}, also {area}."
            return (
                setup,
                calc,
                f"This teaches {topic} by tying the symbolic integral to the visible accumulated area.",
                f"What does the picture measure in this {topic} example?",
                "It measures accumulated area under the graph, not just a formal antiderivative.",
            )
        coeff = 1 + (seed % 7)
        point = 1 + ((seed // 7) % 8)
        linear = (seed // 13) % 6
        value = coeff * point * point + linear * point
        slope = 2 * coeff * point + linear
        linear_term = f"+{linear}x" if linear else ""
        setup = f"Let f(x)={coeff}x^2{linear_term} and look near x={point}."
        calc = f"The secant slope is (f({point}+h)-{value})/h = {slope}+{coeff}h, which approaches {slope} as h goes to 0."
        return (
            setup,
            calc,
            f"This teaches {topic} by showing a moving secant line becoming the tangent slope.",
            f"What quantity settles down in this {topic} example?",
            "The secant slope settles to the derivative value.",
        )

    if domain == "probability":
        if visual == "markov":
            first = 50 + 10 * (seed % 5)
            second = 100 - first
            stay_first = 0.6 + 0.1 * ((seed // 7) % 4)
            from_second = 0.2 + 0.1 * ((seed // 13) % 4)
            next_first = stay_first * first + from_second * second
            next_second = 100 - next_first
            setup = f"A system is in state A or B; start with state vector ({first},{second})."
            calc = f"With transition matrix [[{stay_first:.1f},{from_second:.1f}],[{1-stay_first:.1f},{1-from_second:.1f}]], the next state is ({next_first:.1f},{next_second:.1f})."
            return (
                setup,
                calc,
                f"This teaches {topic} by showing probability mass move while the total stays 100.",
                f"What should stay constant in this {topic} example?",
                "Total probability or total population should stay conserved.",
            )
        total = 12 + (seed % 9)
        condition = 4 + ((seed // 5) % 6)
        both = 1 + ((seed // 11) % max(1, condition - 1))
        event = min(total, both + 3 + ((seed // 17) % 4))
        setup = f"In a set of {total} cases, {event} satisfy A, {condition} satisfy B, and {both} satisfy both A and B."
        calc = f"P(A | B) = {both}/{condition} because the condition B narrows the denominator to {condition} cases."
        return (
            setup,
            calc,
            f"This teaches {topic} by shrinking the sample space before measuring the event.",
            f"What is the new sample space in this {topic} example?",
            "The condition selects the denominator; the numerator is the part inside that condition that also satisfies the target event.",
        )

    if domain == "economics":
        exact_example = economics_model_source_example(topic)
        if exact_example is not None:
            return exact_example
        topic_spec = economics_topic_spec(topic)
        mode = topic_spec[1] if topic_spec is not None else "marginal_curve"
        if visual == "game_payoff":
            if re.search(r"\boligopoly\s+i\b", topic, flags=re.I):
                return (
                    "Two Cournot firms face P=30-Q with zero marginal cost, where Q=qA+qB; hold firm B at qB=6.",
                    "Firm A's profit is (30-qA-6)qA; its best response is qA=(30-6)/2=12, giving price 12 and profit 144.",
                    "Cournot rivalry makes one firm's profit-maximizing quantity depend on the rival's fixed quantity.",
                    "What strategic variable does each Cournot firm choose?",
                    "Each firm chooses a quantity while treating the rival's quantity as given.",
                )
            if re.search(r"\boligopoly\s+ii\b", topic, flags=re.I):
                return (
                    "Two firms choose High or Low price. Payoffs are High,High=(8,8), High,Low=(2,10), Low,High=(10,2), and Low,Low=(5,5).",
                    "Low pays 10 rather than 8 against High and 5 rather than 2 against Low, so both best responses intersect at Low,Low=(5,5).",
                    "A Nash equilibrium is a mutual best response even when both firms would earn more at another joint outcome.",
                    "Why is Low,Low stable?",
                    "Neither firm can improve by changing its own price alone.",
                )
            cooperative = 6 + (seed % 3)
            temptation = cooperative + 2
            punished = cooperative - 2
            sucker = max(0, cooperative - 4)
            setup = (
                "Firm A chooses rows Hold or Cut, and Firm B chooses columns Hold or Cut. "
                f"Payoffs are Hold,Hold=({cooperative},{cooperative}); Hold,Cut=({sucker},{temptation}); "
                f"Cut,Hold=({temptation},{sucker}); Cut,Cut=({punished},{punished})."
            )
            calc = (
                f"Cut yields {temptation} rather than {cooperative} against Hold and {punished} rather than {sucker} "
                f"against Cut, so both best-response markings meet at Cut,Cut=({punished},{punished})."
            )
            return (
                setup,
                calc,
                f"This teaches {topic} with a payoff comparison for every fixed rival action.",
                f"Which cell is stable in this {topic} game?",
                "The stable cell is the intersection of the two players' best responses.",
            )
        if visual == "econ_tax_wedge":
            demand_intercept = 140 + 10 * (seed % 5)
            demand_slope = 1 + ((seed // 5) % 3)
            supply_slope = 1 + ((seed // 11) % 3)
            no_tax_price = 12 + 2 * ((seed // 17) % 6)
            no_tax_qty = demand_intercept - demand_slope * no_tax_price
            supply_intercept = no_tax_qty - supply_slope * no_tax_price
            wedge = 4 + 2 * ((seed // 23) % 5)
            seller_price = (demand_intercept - supply_intercept - demand_slope * wedge) / (demand_slope + supply_slope)
            buyer_price = seller_price + wedge
            taxed_qty = demand_intercept - demand_slope * buyer_price
            deadweight_loss = 0.5 * wedge * (no_tax_qty - taxed_qty)
            setup = f"Let demand be Qd={demand_intercept}-{demand_slope}P and supply be Qs={supply_intercept}+{supply_slope}P, then add a tax wedge of {wedge}."
            calc = (
                f"Before tax, P0={no_tax_price} and Q0={no_tax_qty}; after tax, Pb={format_scalar(buyer_price)}, "
                f"Ps={format_scalar(seller_price)}, and Qt={format_scalar(taxed_qty)}, so DWL={format_scalar(deadweight_loss)}."
            )
            return (
                setup,
                calc,
                f"This teaches {topic} by showing the wedge between what buyers pay and sellers receive.",
                f"What two prices must be tracked in this {topic} example?",
                "Track the buyer price and seller price separately.",
            )
        if visual == "econ_supply_demand":
            demand_intercept = 140 + 10 * (seed % 7)
            demand_slope = 1 + ((seed // 5) % 3)
            supply_slope = 1 + ((seed // 11) % 3)
            price = 8 + 2 * ((seed // 17) % 6)
            quantity = demand_intercept - demand_slope * price
            supply_intercept = quantity - supply_slope * price
            setup = f"Let demand be Qd={demand_intercept}-{demand_slope}P and supply be Qs={supply_intercept}+{supply_slope}P."
            calc = f"Set {demand_intercept}-{demand_slope}P = {supply_intercept}+{supply_slope}P to get P={price} and Q={quantity}."
            return (
                setup,
                calc,
                f"This teaches {topic} by turning the crossing point into a solved numerical equilibrium.",
                f"What makes the market balanced in this {topic} example?",
                "Quantity demanded equals quantity supplied.",
            )
        if visual == "econ_elasticity":
            price = 10 + 5 * (seed % 5)
            price_change_pct = 10 + 5 * ((seed // 7) % 3)
            quantity = 40 + 10 * ((seed // 11) % 6)
            quantity_change_pct = 10 + 5 * ((seed // 17) % 4)
            new_price = price * (100 + price_change_pct) / 100
            new_quantity = quantity * (100 - quantity_change_pct) / 100
            elasticity = -quantity_change_pct / price_change_pct
            setup = f"Price rises from {price:g} to {new_price:g} while quantity falls from {quantity:g} to {new_quantity:g}."
            calc = f"Quantity changes by -{quantity_change_pct} percent and price changes by +{price_change_pct} percent, so elasticity is {elasticity:g}."
            return (
                setup,
                calc,
                f"This teaches {topic} by converting a story into percentage response.",
                f"What two percent changes define this {topic} example?",
                "Percent change in quantity divided by percent change in price.",
            )
        if visual == "econ_budget":
            price_x = 2 + (seed % 4)
            price_y = 3 + ((seed // 5) % 5)
            x_choice = 2 + ((seed // 11) % 5)
            y_choice = 2 + ((seed // 17) % 5)
            income = price_x * x_choice + price_y * y_choice
            setup = f"A consumer has income {income}, good x costs {price_x}, and good y costs {price_y}."
            calc = f"The budget line is {price_x}x+{price_y}y={income}; if x={x_choice}, then y={y_choice} exactly spends the budget."
            return (
                setup,
                calc,
                f"This teaches {topic} by showing how prices turn income into a visible constraint.",
                f"What changes if income rises in this {topic} example?",
                "The budget line shifts outward because more bundles become affordable.",
            )
        if mode == "externality":
            private_cost = 4 + (seed % 4)
            external_cost = 2 + ((seed // 7) % 4)
            social_cost = private_cost + external_cost
            setup = f"A producer's private marginal cost is {private_cost}, while each unit creates external damage {external_cost}."
            calc = f"Marginal social cost is {private_cost}+{external_cost}={social_cost}; the efficient crossing uses MSC, not the lower private-cost curve."
            return setup, calc, f"This teaches {topic} by shifting the cost curve by the measured spillover.", "Which cost belongs in the social optimum?", "Use marginal social cost, including the external cost."
        if mode == "production":
            productivity = 2 + (seed % 4)
            labor = 3 + ((seed // 7) % 5)
            output = productivity * labor
            setup = f"With capital fixed, a production function is q={productivity}L; choose L={labor}."
            calc = f"The technology maps {labor} units of labor to q={productivity}*{labor}={output} units of output."
            return setup, calc, f"This teaches {topic} by moving one input point onto its output curve.", "What is held fixed in this short-run production example?", "Capital is fixed while labor changes."
        if mode == "costs":
            fixed = 8 + (seed % 7)
            marginal = 2 + ((seed // 7) % 5)
            quantity = 4 + ((seed // 13) % 6)
            total = fixed + marginal * quantity
            average = total / quantity
            setup = f"A firm's total cost is TC={fixed}+{marginal}q; evaluate q={quantity}."
            calc = f"TC={total}, MC={marginal}, and AC={total}/{quantity}={format_scalar(average)}; each curve answers a different cost question."
            return setup, calc, f"This teaches {topic} with fixed, marginal, total, and average cost from the same function.", "Which cost changes when one more unit is produced?", "Marginal cost measures the next unit."
        if mode == "short_run_avc_shutdown_test":
            return (
                "A price-taking firm faces market price P=5, minimum average variable cost of 6, and fixed cost of 4 in the short run.",
                "Because P-min AVC=5-6=-1<0, producing cannot cover avoidable variable cost, so the firm chooses q=0 and still pays the fixed cost.",
                "The shutdown decision compares price with average variable cost: below minimum AVC, the short-run output is zero.",
                "When should this firm shut down in the short run?",
                "It shuts down when price falls below minimum average variable cost.",
            )
        if mode == "competition":
            price = 6 + (seed % 7)
            mc_slope = 2 + ((seed // 5) % 3)
            quantity = price / mc_slope
            setup = f"A competitive firm faces market price P={price} and marginal cost MC(q)={mc_slope}q."
            calc = f"Set P=MC: {price}={mc_slope}q, so the profit-maximizing output is q={format_scalar(quantity)}."
            return setup, calc, f"This teaches {topic} by moving along the firm's MC curve to the fixed market-price line.", "What does the competitive firm choose?", "It chooses quantity; it takes market price as given."
        if mode in {"monopoly", "two_market_equal_mr_allocation"}:
            if re.search(r"\bmonopoly\s+ii\b", topic, flags=re.I):
                return (
                    "A monopolist can sell one unit to a high-value buyer for 18 and one to a low-value buyer for 10; each unit costs 4.",
                    "Separate prices yield profit (18-4)+(10-4)=20, while one price of 10 yields 12 and one price of 18 yields 14.",
                    "Price discrimination converts differences in willingness to pay into additional captured surplus.",
                    "What information makes separate pricing possible?",
                    "The seller must distinguish buyer groups and limit resale between them.",
                )
            choke_price = 18 + 2 * (seed % 5)
            marginal_cost = 2 + ((seed // 7) % 5)
            quantity = (choke_price - marginal_cost) / 2.0
            price = choke_price - quantity
            setup = f"A monopolist faces demand P={choke_price}-Q and constant marginal cost MC={marginal_cost}."
            calc = f"MR={choke_price}-2Q; MR=MC gives Qm={format_scalar(quantity)}, then demand gives Pm={format_scalar(price)}."
            return setup, calc, f"This teaches {topic} by finding quantity on MR=MC before reading price from demand.", "Why not set demand equal to marginal cost?", "The monopolist chooses output where marginal revenue equals marginal cost."
        if mode == "public_goods":
            first = 5 + (seed % 4)
            second = 3 + ((seed // 7) % 4)
            cost = 5
            social = first + second
            setup = f"At one unit of a public good, buyer A's marginal benefit is {first} and buyer B's is {second}; marginal cost is {cost}."
            calc = f"Vertical summation gives social marginal benefit {first}+{second}={social}, which exceeds marginal cost {cost}."
            return setup, calc, f"This teaches {topic} by stacking simultaneous benefits rather than adding quantities horizontally.", "How are public-good demands combined?", "Add marginal benefits vertically at the same quantity."
        units = 6 + (seed % 15)
        price = 5 + ((seed // 5) % 11)
        new_units = units + 1 + ((seed // 11) % 7)
        discount = 1 + ((seed // 17) % 2)
        new_price = max(1, price - discount)
        old_revenue = units * price
        new_revenue = new_units * new_price
        setup = f"A firm sells {units} units at price {price} and considers lowering price to {new_price} to sell {new_units} units."
        calc = f"Revenue changes from {old_revenue} to {new_revenue}, so the model compares the gain from extra units with the lower price per unit."
        return (
            setup,
            calc,
            f"This teaches {topic} by comparing one marginal change instead of speaking only in generalities.",
            f"What input changes in this {topic} example?",
            "One input changes first, then the model tracks the resulting output or payoff.",
        )

    if domain == "physics":
        if visual not in PHYSICS_VISUAL_KINDS:
            raise ValueError(f"Unsupported physics visual {visual!r} for {topic!r}.")
        return physics_concrete_source_example(topic, visual, seed)

    lower_topic = topic.lower()
    if any(word in lower_topic for word in ("graph", "tree", "path", "network")):
        offset = seed % 20
        nodes = [chr(ord("A") + offset + i) for i in range(4)]
        setup = f"Model {topic} with nodes {', '.join(nodes)} and edges {nodes[0]}-{nodes[1]}, {nodes[0]}-{nodes[2]}, {nodes[1]}-{nodes[3]}."
        calc = f"Starting at {nodes[0]}, the one-edge neighbors are {nodes[1]} and {nodes[2]}, and {nodes[3]} is reached in two edges through {nodes[1]}."
        return (
            setup,
            calc,
            f"This teaches {topic} by making adjacency and reachability visible before any formal rule.",
            f"What object carries the information in this {topic} example?",
            "The nodes and edges carry the structure; the algorithm reads that structure.",
        )
    if any(word in lower_topic for word in ("algorithm", "complexity", "runtime", "recursion", "dynamic")):
        n1 = 2 ** (2 + (seed % 3))
        n2 = 2 * n1
        variant = (seed // 5) % 3
        if variant == 0:
            setup = f"Test {topic} on input sizes n={n1} and n={n2}."
            calc = f"If the work is n^2, the cost grows from {n1*n1} to {n2*n2} when the input doubles."
        elif variant == 1:
            setup = f"Test {topic} on lists with n={n1 + 1} and n={n2 + 2} items."
            calc = f"If the work is 3n+2, the operation count grows from {3*(n1+1)+2} to {3*(n2+2)+2}, which is close to linear."
        else:
            setup = f"Test {topic} on n={n1} and n={n2} data points."
            calc = f"If the work is n log2(n), the count grows from {int(n1*math.log2(n1))} to {int(n2*math.log2(n2))}, between linear and quadratic growth."
        return (
            setup,
            calc,
            f"This teaches {topic} by comparing growth rather than only naming the algorithm.",
            f"What changes when n doubles in this {topic} example?",
            "The input size doubles, and the measured work reveals the growth rule.",
        )
    if any(word in lower_topic for word in ("field", "ring", "ideal", "modular")):
        primes = [5, 7, 11, 13]
        modulus = primes[seed % len(primes)]
        a = 2 + ((seed // 5) % (modulus - 3))
        b = 2 + ((seed // 11) % (modulus - 3))
        inv = next(x for x in range(1, modulus) if (a * x) % modulus == 1)
        setup = f"Use arithmetic mod {modulus} as a small test case for {topic}."
        calc = f"{a}+{b}={(a+b)%modulus} mod {modulus} and {a}*{inv}=1 mod {modulus}, so wraparound and inverses can both be checked directly."
        return (
            setup,
            calc,
            f"This teaches {topic} by checking the operation rules on a finite arithmetic system.",
            f"Why is mod 5 useful for testing {topic}?",
            "A tiny arithmetic system is small enough to compute fully while still showing the algebraic rules.",
        )
    if any(word in lower_topic for word in ("equation", "root", "solution", "constraint")):
        a = 2 + (seed % 5)
        x = 2 + ((seed // 7) % 6)
        b = 1 + ((seed // 11) % 8)
        rhs = a * x + b
        setup = f"Use the equation {a}x+{b}={rhs} as a small case of {topic}."
        calc = f"Subtract {b} to get {a}x={a*x}, then divide by {a} to get x={x}."
        return (
            setup,
            calc,
            f"This teaches {topic} by showing which operations preserve the solution.",
            f"What should remain unchanged in this {topic} example?",
            "The solution set should remain the same after each legal transformation.",
        )
    if any(word in lower_topic for word in ("optimization", "minimum", "maximum", "gradient")):
        center = -2 + (seed % 7)
        floor = 1 + ((seed // 7) % 8)
        shifted = f"x+{abs(center)}" if center < 0 else f"x-{center}"
        setup = f"Use the cost C(x)=({shifted})^2+{floor} as a small case of {topic}."
        calc = f"C({center})={floor}, while C({center - 1})={floor + 1} and C({center + 1})={floor + 1}, so x={center} is the visible minimum."
        return (
            setup,
            calc,
            f"This teaches {topic} by comparing nearby values around the optimum.",
            f"What must be checked in this {topic} example?",
            "Check how the quantity changes near the candidate optimum.",
        )
    multiplier = 2 + (seed % 4)
    offset = 1 + ((seed // 5) % 6)
    first_x = 1 + ((seed // 11) % 4)
    second_x = first_x + 2
    first_y = multiplier * first_x + offset
    second_y = multiplier * second_x + offset
    return (
        f"Use {topic} as an input-output test: start with x={first_x} and the rule output = {multiplier}x+{offset}.",
        f"For x={first_x} the output is {first_y}; for x={second_x} the output is {second_y}, so changing x by 2 changes the output by {second_y - first_y}.",
        f"This teaches {topic} by making the definition testable on concrete inputs and outputs.",
        f"If the same {topic} rule receives x={second_x + 1}, what output should it produce?",
        f"Compute {multiplier}*{second_x + 1}+{offset} = {multiplier * (second_x + 1) + offset}, then compare with the earlier outputs.",
    )


CS_VISUAL_KINDS = frozenset({"cs_array", "cs_graph"})
CS_SEMANTIC_FAMILIES = frozenset({
    "array", "sort", "divide", "hash", "dynamic_array", "graph", "heap", "tree", "avl", "complexity", "dp",
})


def cs_semantic_family_for_topic(text: str) -> str | None:
    """Classify a CS topic into a renderer-independent semantic family."""
    normalized = re.sub(r"[^a-z0-9+()]+", " ", text.lower()).strip()
    ordered_rules = (
        (("dynamic programming", "memoization", "memoized", "pseudopolynomial", "dp table", "bellman equation"), "dp"),
        (("topological", "shortest path", "shortest paths", "dijkstra", "bellman ford", "johnson", "breadth first", "depth first", "bfs", "dfs", "graph", "network", "minimum spanning", "mst"), "graph"),
        (("avl", "red black tree", "balanced tree", "tree rotation"), "avl"),
        (("priority queue", "binary heap", "binary heaps", "min heap", "max heap", "heap"), "heap"),
        (("binary tree", "binary search tree", "binary search trees", "search tree", "search trees", "tree traversal", "binary trees"), "tree"),
        (("hash table", "hash function", "hashing", "collision", "hash"), "hash"),
        (("dynamic array", "resizable array", "amortized array"), "dynamic_array"),
        (("sorted array", "direct access array"), "array"),
        (("divide and conquer",), "divide"),
        (("selection sort", "insertion sort", "merge sort", "quick sort", "quicksort", "sorting", " sort", "sort "), "sort"),
        (("running time", "constant time", "linear time", "quadratic time", "asymptotic", "complexity", "big o", "runtime", "growth rate", "algorithm analysis", "recurrence"), "complexity"),
        (("direct access array", "sorted array", "array", "data structure", "data structures", "linked list", "stack", "queue", "pointer", "binary search"), "array"),
    )
    padded = f" {normalized} "
    for terms, kind in ordered_rules:
        if any(
            re.search(rf"(?<![a-z0-9]){re.escape(term.strip())}(?![a-z0-9])", padded)
            for term in terms
        ):
            return kind
    return None


def cs_visual_kind_for_topic(text: str) -> str | None:
    family = cs_semantic_family_for_topic(text)
    if family is None:
        return None
    return "cs_graph" if family in {"graph", "heap", "tree", "avl"} else "cs_array"


def concrete_cs_example(title: str, family: str) -> tuple[str, str, str, str, str]:
    """Create a deterministic worked trace that the renderer can recompute."""
    lower = title.lower()
    if "depth-first" in lower or re.search(r"\bdfs\b", lower):
        return (
            "Run DFS from A on directed edges A->B, A->C, B->D, D->E, and C->E.",
            "Push A, then follow A->B->D->E; backtrack to A and finish C. Discovery order is A, B, D, E, C.",
            "The LIFO call stack keeps one unfinished path visible while backtracking exposes the next branch.",
            "Why can DFS finish a vertex before every vertex has been discovered?",
            "Finishing means that vertex has no unexplored outgoing edge; a different branch may still remain on the stack.",
        )
    if "bellman-ford" in lower or "bellman ford" in lower:
        return (
            "From A, use directed weighted edges A->B:4, A->C:5, B->C:-2, B->D:6, and C->D:3.",
            "Relax every edge for three passes: B becomes 4, C improves from 5 to 2 through B, and D becomes 5 through C; a fourth scan makes no change.",
            "Repeated whole-edge passes propagate improvements even when a useful edge has negative weight.",
            "What would an improvement on the extra verification pass prove?",
            "A reachable negative-weight cycle would still be lowering a distance.",
        )
    if "johnson" in lower:
        return (
            "Reweight directed edges A->B:-2, A->C:4, B->C:3, B->D:2, and C->D:-1 using a new zero-weight source q.",
            "Bellman-Ford gives potentials h(A)=0, h(B)=-2, h(C)=0, h(D)=-1; w'(u,v)=w(u,v)+h(u)-h(v) makes the five weights 0, 4, 1, 1, and 0.",
            "Potential differences remove negative edge weights while preserving every path comparison between the same endpoints.",
            "Why can Dijkstra run after Johnson reweights the graph?",
            "Every reweighted edge is nonnegative, and the potential terms telescope along each path.",
        )
    if "dijkstra" in lower:
        return (
            "Find shortest paths from A using nonnegative edges A->B:4, A->C:1, C->B:2, B->D:1, and C->D:5.",
            "Settle A=0, then C=1, B=3, and D=4; every successful relaxation lowers a tentative label before that vertex is settled.",
            "Extracting the smallest tentative distance makes each settled label final when all edge weights are nonnegative.",
            "Why would one negative edge invalidate the settling argument?",
            "A later path through that edge could lower a vertex that had already been declared final.",
        )
    if "state design" in lower:
        return (
            "Count paths through a 3 by 4 grid when moves may go only right or down.",
            "Use dp[r,c]=dp[r-1,c]+dp[r,c-1] with ones along the top row and left column; the table ends with 10 paths at the lower-right cell.",
            "A state is sufficient when its row and column contain everything future path choices need.",
            "Why is the current cell alone not enough without its coordinates?",
            "Different cells have different remaining moves, so position is part of the state.",
        )
    if "applications" in lower:
        return (
            "Parenthesize matrices with dimensions 10 by 30, 30 by 5, and 5 by 60.",
            "(AB)C costs 10*30*5 + 10*5*60 = 4500 multiplications, while A(BC) costs 30*5*60 + 10*30*60 = 27000.",
            "Interval states compare every split and retain the cheapest subchain cost.",
            "Which split should the DP retain for the full chain?",
            "It retains (AB)C because 4500 is smaller than 27000.",
        )
    if "pseudopolynomial" in lower:
        return (
            "Solve 0/1 knapsack with capacity 6 and items (weight,value)=(2,3),(3,4),(4,5).",
            "Fill dp[i,w] by comparing exclusion with value_i+dp[i-1,w-weight_i]; the best value at capacity 6 is 8 from weights 2 and 4.",
            "The table is polynomial in numeric capacity, not in the number of bits used to write that capacity.",
            "Why is this running time called pseudopolynomial?",
            "O(nW) depends on the magnitude W, which can be exponential in the length of W's binary encoding.",
        )
    if "memoization" in lower:
        return (
            "Compute Fibonacci F(7) from F(0)=0 and F(1)=1 with top-down memoization.",
            "The recursion first reaches each state F(7) through F(0), stores it once, and reuses repeated calls; F(7)=13.",
            "The dependency graph has eight states even though the naive call tree repeats many of them.",
            "What turns the exponential recursion into linear work?",
            "Each argument value is solved once and every later call reads its saved result.",
        )
    if "linear sorting" in lower or "counting sort" in lower:
        return (
            "Counting-sort keys [3, 1, 2, 3, 0, 2, 1] from the universe 0 through 3.",
            "The count array becomes [1, 2, 2, 2], then emits [0, 1, 1, 2, 2, 3, 3] in key order.",
            "Scanning a bounded key universe replaces pairwise comparisons with counts.",
            "When is counting sort linear in the input size?",
            "When the universe size is O(n), its O(n+k) work is O(n).",
        )
    if "priority queue" in lower or family == "heap":
        return (
            "Use the min-heap [2, 4, 7, 9, 6] and insert key 1.",
            "Append 1, then swap it with 7 and 2; the heap becomes [1, 4, 2, 9, 6, 7].",
            "Each swap repairs the parent-child ordering while the same heap objects stay visible.",
            "Why does insertion only inspect one path to the root?",
            "Only ancestors of the new leaf can violate the heap order.",
        )
    if "shortest path" in lower:
        return (
            "Find shortest paths from A in the weighted graph A-B:4, A-C:1, C-B:2, B-D:1, C-D:5.",
            "Relax A-C to 1, C-B to 3, and B-D to 4; final distances are A=0, B=3, C=1, D=4.",
            "The frontier moves by smallest known distance and every successful relaxation lowers a label.",
            "Why is the direct A-B edge not on the shortest route to B?",
            "A-C-B costs 1+2=3, which beats the direct cost 4.",
        )
    if "topological" in lower:
        return (
            "Topologically order the DAG with edges A->C, B->C, and C->D.",
            "A and B start with indegree 0; remove them, then C reaches 0, then D, giving A, B, C, D.",
            "Removing a frontier node visibly releases the next zero-indegree node.",
            "What prevents a topological order from existing?",
            "A directed cycle prevents every remaining node from reaching indegree zero.",
        )
    if lower == "data structures":
        return (
            "Use a stack containing [4, 7, 2]; push 9, then pop once.",
            "The states are [4, 7, 2] -> [4, 7, 2, 9] -> [4, 7, 2], and the popped value is 9.",
            "The last value pushed is the first value removed, making the LIFO invariant visible.",
            "Which value would a second pop remove?",
            "It would remove 2, the new top of the stack.",
        )
    if family == "graph":
        return (
            "Run BFS from A on edges A-B, A-C, B-D, and C-E.",
            "The queue visits layer 0: A; layer 1: B, C; layer 2: D, E.",
            "The queue frontier establishes shortest unweighted distances one layer at a time.",
            "Why does a FIFO queue preserve BFS layers?",
            "Every node already in the queue is no farther than nodes appended behind it.",
        )
    if "avl" in lower or family == "avl":
        return (
            "Insert 30, 20, then 10 into an empty AVL tree.",
            "The root balance becomes +2, so rotate right at 30; the result has root 20 with children 10 and 30.",
            "The rotation changes links without changing the in-order key sequence.",
            "What invariant does the rotation restore?",
            "Every node's left and right subtree heights differ by at most one.",
        )
    if "binary tree" in lower or family == "tree":
        return (
            "Insert keys 4, 2, 6, 1, and 3 into a binary search tree, then search for 3.",
            "The search follows 4 -> 2 -> 3; each comparison discards the opposite subtree.",
            "Ordered links turn a global search into one persistent root-to-leaf path.",
            "Why is the search path short in a balanced tree?",
            "Each comparison removes roughly half of the remaining keys.",
        )
    if "hash function" in lower:
        return (
            "Use h(k)=k mod 7 to map keys 10, 18, and 25 into bucket indices.",
            "The mappings are h(10)=3, h(18)=4, and h(25)=4, so the range sequence is [3, 4, 4].",
            "The same key always reaches the same index, while different keys may share an index.",
            "What range must this hash function return?",
            "It must return one of the seven indices 0 through 6.",
        )
    if "hash" in lower or family == "hash":
        return (
            "Use 5 buckets with h(k)=k mod 5 and insert keys 12, 7, and 18 using separate chaining.",
            "Keys 12 and 7 both map to bucket 2, while 18 maps to bucket 3; the buckets are [[], [], [12, 7], [18], []].",
            "The animation follows each key through the hash function into its exact bucket and exposes the collision.",
            "Why must a hash table still handle equal bucket indices?",
            "Different keys can produce the same hash index, so a collision policy is required.",
        )
    if "dynamic array" in lower or family == "dynamic_array":
        return (
            "A dynamic array of capacity 4 contains [3, 8, 1, 6]; append 5.",
            "Allocate capacity 8, copy 3, 8, 1, 6 into the same indices, then place 5 at index 4.",
            "One expensive resize creates spare capacity for later constant-time appends.",
            "Why does the capacity usually grow geometrically?",
            "Geometric growth spreads copying cost across many later appends.",
        )
    if "selection sort" in lower:
        return (
            "Selection-sort the array [4, 2, 5, 1].",
            "Select 1 and swap with 4 to get [1, 2, 5, 4], then swap 5 and 4 to get [1, 2, 4, 5].",
            "The sorted prefix grows by one position after each selected minimum.",
            "Which part of the array is guaranteed sorted after pass i?",
            "The first i positions contain the i smallest keys in order.",
        )
    if "insertion sort" in lower:
        return (
            "Insertion-sort the array [5, 2, 4, 6, 1].",
            "Insert each key into the sorted prefix: [2, 5, 4, 6, 1], [2, 4, 5, 6, 1], then [1, 2, 4, 5, 6].",
            "Shifts make room while the sorted prefix remains a visible invariant.",
            "Why can insertion sort be fast on nearly sorted input?",
            "Each key moves only a short distance when few inversions remain.",
        )
    if family == "divide":
        return (
            "Solve a size-8 problem with T(n)=2T(n/2)+n.",
            "Build four recursion-tree levels with 1, 2, 4, and 8 subproblems; each level contributes 8 units of work.",
            "The persistent tree exposes 4 times 8 total work, so T(8)=32 and T(n)=Theta(n log n).",
            "Why does every internal level cost n?",
            "There are 2^d subproblems of size n/2^d, whose work sums to n.",
        )
    if family == "sort":
        return (
            "Merge-sort the array [8, 3, 6, 2, 7, 1, 5, 4].",
            "Split to singletons, then merge in order to obtain [1, 2, 3, 4, 5, 6, 7, 8] across 3 merge levels.",
            "Every level preserves all keys while replacing many sorted runs with fewer longer runs.",
            "Why is each merge level linear in the number of keys?",
            "Every key is copied into exactly one merged run at that level.",
        )
    if "sorted array" in lower:
        return (
            "Insert 6 into the sorted array [2, 4, 7, 9].",
            "Find index 2, shift 9 and 7 one cell right, then write 6 to obtain [2, 4, 6, 7, 9].",
            "Fast search does not remove the linear shifts needed to preserve contiguous order.",
            "Which values move during this insertion?",
            "Only the suffix beginning at the insertion index moves right.",
        )
    if "direct access" in lower or "random access" in lower:
        return (
            "Read index 1 from the direct-access array [4, 7, 2, 9].",
            "Compute base + 1 times cellsize, jump directly to index 1, and return 7.",
            "Address arithmetic selects one requested cell without examining the cells before it.",
            "Why does the access time not grow with the array length?",
            "The address calculation uses the index directly and does not scan neighboring cells.",
        )
    if "constant time" in lower:
        return (
            "Read index 2 from the direct-access array [8, 3, 5, 2].",
            "The address calculation jumps directly to index 2 and returns 5 in one access, independent of array length.",
            "Constant time means the operation count does not grow with n.",
            "Does constant time mean zero time?",
            "No; it means a bounded number of steps independent of input size.",
        )
    if "linear time" in lower:
        return (
            "Scan arrays of sizes n=4, n=8, and n=16 once.",
            "The scan performs 4, 8, and 16 visits, so doubling n doubles the work.",
            "The moving counter and plotted points share the same T(n)=n data.",
            "What slope appears when work is plotted against n?",
            "A constant slope, because each extra item adds one visit.",
        )
    if family == "complexity":
        return (
            "Compare T(n)=1, T(n)=n, T(n)=n log2(n), and T(n)=n^2 at n=2, 4, 8, and 16.",
            "At n=16 the counts are 1, 16, 64, and 256, so the curves separate as input grows.",
            "The plot derives growth from operation counts rather than from curve labels alone.",
            "Which growth rate eventually dominates the others here?",
            "Quadratic n^2 grows fastest among the four shown rates.",
        )
    if family == "dp":
        return (
            "Compute Fibonacci F(5) from F(0)=0 and F(1)=1.",
            "Fill the table left to right as [0, 1, 1, 2, 3, 5], reusing the previous two saved cells each time.",
            "The table makes every dependency and reuse visible.",
            "Which saved states are needed to compute F(i)?",
            "Only F(i-1) and F(i-2) for this recurrence.",
        )
    return (
        "Store [4, 7, 2, 9] in indexed cells and read index 1.",
        "The index points directly to value 7, while the other cells remain unchanged.",
        "The data layout and the operation are both visible instead of being replaced by an unrelated arithmetic rule.",
        "What does the index identify?",
        "It identifies the exact storage position used by the operation.",
    )


def cs_source_copy(title: str, semantic_family: str) -> tuple[str, str, str, list[str], str]:
    lower = title.lower()
    if "breadth-first" in lower or re.search(r"\bbfs\b", lower):
        return (
            f"{title}: A FIFO frontier discovers an unweighted graph one distance layer at a time.",
            "Keep the graph fixed while dequeue, discovery, predecessor, and layer state advance together.",
            r"d[s]=0,\qquad d[v]=d[u]+1",
            ["graphs", "queues", "unweighted distance"],
            "BFS assigns a distance only on first discovery; it does not repeatedly relax weighted path estimates.",
        )
    if "depth-first" in lower or re.search(r"\bdfs\b", lower):
        return (
            f"{title}: Depth-first search follows one unfinished path before backtracking.",
            "Keep the directed graph fixed while a visible LIFO stack grows, retreats, and records discovery and finish order.",
            r"O(V+E)",
            ["graphs", "recursion", "stacks"],
            "DFS is not a breadth-first queue traversal; its active frontier is one stack path.",
        )
    if "bellman-ford" in lower or "bellman ford" in lower:
        return (
            f"{title}: Repeated edge scans propagate shortest-path bounds through negative edges.",
            "Show every successful relaxation by pass, then perform the extra scan that detects a reachable negative cycle.",
            r"d[v]\leftarrow\min(d[v],d[u]+w(u,v))",
            ["weighted directed graphs", "relaxation", "path length"],
            "Bellman-Ford permits negative edges, but not a reachable negative-weight cycle when finite shortest paths are required.",
        )
    if "johnson" in lower:
        return (
            f"{title}: Potentials reweight every edge without changing which paths are shortest.",
            "Compute vertex potentials, transform each edge visibly, and verify that every new weight is nonnegative before invoking Dijkstra.",
            r"w'(u,v)=w(u,v)+h(u)-h(v)",
            ["Bellman-Ford", "Dijkstra's algorithm", "all-pairs shortest paths"],
            "Reweighting changes edge labels, not the relative cost of two paths with the same endpoints.",
        )
    if "dijkstra" in lower:
        return (
            f"{title}: The smallest tentative label becomes final under nonnegative edge weights.",
            "Keep tentative distances on the graph while the minimum-priority frontier settles one vertex and relaxes its outgoing edges.",
            r"d[v]\leftarrow\min(d[v],d[u]+w(u,v))",
            ["weighted graphs", "priority queues", "relaxation"],
            "Settling is valid only when no negative edge can create a later improvement.",
        )
    if "state design" in lower:
        return (
            f"{title}: A state must preserve exactly the information future transitions need.",
            "Fill a two-dimensional path table from its boundary and draw the two dependencies entering each new cell.",
            r"dp[r,c]=dp[r-1,c]+dp[r,c-1]",
            ["recurrences", "grids", "topological dependency order"],
            "A smaller state is not better if it forgets information needed by the recurrence.",
        )
    if "applications" in lower:
        return (
            f"{title}: Interval dynamic programming compares every legal split of a subchain.",
            "Build the matrix-chain table by interval length and retain the split with minimum scalar-multiplication cost.",
            r"C[i,j]=\min_k\{C[i,k]+C[k+1,j]+p_{i-1}p_kp_j\}",
            ["matrix multiplication", "intervals", "optimization"],
            "Matrix multiplication is associative in value but not in computational cost.",
        )
    if "pseudopolynomial" in lower:
        return (
            f"{title}: Knapsack tabulation is polynomial in numeric capacity rather than its bit length.",
            "Fill each row from the previous row so include/exclude choices cannot reuse an item.",
            r"dp[i,w]=\max\{dp[i-1,w],v_i+dp[i-1,w-w_i]\}",
            ["dynamic programming", "binary encoding", "optimization"],
            "O(nW) is not polynomial in the input length when W is written in binary.",
        )
    if "memoization" in lower:
        return (
            "Cache each recursive state once; reuse every repeated call.",
            "Expose the dependency graph, solve each state once, and route later calls back to the stored value.",
            r"F(i)=F(i-1)+F(i-2),\qquad M[i]\leftarrow F(i)\ \text{once}",
            ["recursion", "dependencies", "saved state"],
            "Memoization changes repeated evaluation into reuse; it does not change the recurrence being computed.",
        )
    if "linear sorting" in lower or "counting sort" in lower:
        return (
            f"{title}: Counting sort exchanges comparisons for a scan over a bounded key universe.",
            "Move each key into its count bucket, then emit buckets in order while preserving the exact multiplicities.",
            r"T(n,k)=\Theta(n+k)",
            ["arrays", "integer keys", "frequency counts"],
            "Linear time requires the key universe k to remain O(n).",
        )
    concept_specific = {
        "topological sort": (
            "Topological order repeatedly exposes prerequisites that are already satisfied.",
            "Keep the DAG fixed, track every indegree, and append only zero-indegree vertices to the order.",
            r"\operatorname{indegree}(v)=0",
            ["directed acyclic graphs", "indegree", "queues"],
            "A topological order is constrained by edge direction; it is not a shortest-path computation.",
        ),
        "direct access array": (
            "A direct-access array turns an integer index into one storage address.",
            "Keep indices aligned with cells and show the address jump touching exactly one requested cell.",
            r"\operatorname{address}(A[i])=base+i\cdot cellsize",
            ["indices", "contiguous storage"],
            "Direct access does not search through earlier cells.",
        ),
        "data structures": (
            "A data structure is defined by the state changes its operations permit.",
            "Preserve one stack while push and pop change only its exposed top.",
            r"\operatorname{pop}(\operatorname{push}(S,x))=(S,x)",
            ["sequences", "interfaces", "state"],
            "Choosing a structure means choosing operation invariants, not merely a storage picture.",
        ),
        "hash tables": (
            "A hash table stores every key in the bucket selected by its hash index.",
            "Keep buckets fixed while keys move through h and collisions extend a bucket chain.",
            r"k\in B_{h(k)},\qquad \alpha=n/m",
            ["arrays", "hash functions", "collision resolution"],
            "A table still needs a collision policy when two keys receive the same bucket.",
        ),
        "hash function": (
            "A hash function deterministically maps a large key space into a finite index range.",
            "Move distinct keys through the same rule and retain their exact output indices for comparison.",
            r"h:K\to\{0,1,\ldots,m-1\}",
            ["functions", "modular arithmetic", "finite ranges"],
            "A deterministic hash value is not a promise of a unique index.",
        ),
    }
    if lower in concept_specific:
        copy = concept_specific[lower]
        return (f"{title}: {copy[0]}", copy[1], copy[2], copy[3], copy[4])
    copy = {
        "array": ("An index is a coordinate into stored data.", "Track indices, values, and the cells touched by each operation.", r"A[i]", ["indices", "sequences"], "Do not confuse an array value with its index."),
        "sort": ("Sorting is controlled motion toward an order invariant.", "Keep every key visible while comparisons, shifts, swaps, or merges grow the sorted region.", r"a_0\leq a_1\leq\cdots\leq a_{n-1}", ["arrays", "comparisons"], "A sorted final frame is not an explanation of the algorithm."),
        "hash": ("A hash function turns a key into a bucket address.", "Follow each key through the function and show how the collision policy stores equal indices.", r"h(k)=k\bmod m", ["arrays", "modular arithmetic"], "A hash function cannot guarantee that every key receives a unique bucket."),
        "dynamic_array": ("A dynamic array trades occasional copying for cheap appends.", "Show capacity, occupied cells, the copy pass, and the new free space after resizing.", r"C_{new}=2C", ["arrays", "amortized analysis"], "A single resize is not constant time even though appends are amortized constant time."),
        "graph": ("A graph algorithm moves a frontier through nodes and edges.", "Keep the graph fixed while queue, indegree, or distance state changes on the same nodes.", r"d[v]=\min(d[v],d[u]+w(u,v))", ["graphs", "queues"], "A visited order is not enough; show why each node enters the frontier."),
        "heap": ("A heap keeps the next priority at its root.", "Show the array and tree positions together while a key bubbles along one ancestor path.", r"parent(i)=\lfloor(i-1)/2\rfloor", ["arrays", "trees"], "Heap order is weaker than globally sorted order."),
        "tree": ("A search tree turns comparisons into a path.", "Preserve the tree while each comparison selects one child and excludes the other subtree.", r"left<root<right", ["trees", "ordering"], "A binary tree is not automatically balanced or a search tree."),
        "avl": ("An AVL rotation repairs height without changing key order.", "Animate the same nodes and links through imbalance, rotation, and restored balance factors.", r"|h_L-h_R|\leq1", ["binary search trees", "height"], "A rotation relinks nodes; it does not reorder the in-order sequence."),
        "complexity": ("Running time is a function of input size.", "Derive plotted points from operation counts, then compare how those counts separate as n grows.", r"T(n)", ["functions", "counting"], "Big-O names growth, not a stopwatch duration."),
        "dp": ("Dynamic programming makes repeated subproblems into reusable state.", "Show dependencies feeding each table cell and preserve earlier cells as later ones are filled.", r"dp[i]=F(dp[i-1],dp[i-2])", ["recurrences", "tables"], "Memoization alone does not choose a correct state or recurrence."),
    }[semantic_family]
    return (f"{title}: {copy[0]}", copy[1], copy[2], copy[3], copy[4])


def source_term_concept(term: str, domain: str | None) -> Concept:
    raw_title = re.sub(r"\s+", " ", term).strip()
    exact_course_title = (
        raw_title in MIT_8_01_VIDEO_ROUTES
        or resolve_group_video_model(raw_title, fail_closed=False) is not None
    )
    title = raw_title if exact_course_title else raw_title.title()
    if not exact_course_title:
        title = re.sub(r"(['’])S\b", lambda match: match.group(1) + "s", title)
        for acronym in SOURCE_TERM_APPROVED_ACRONYMS:
            title = re.sub(rf"\b{re.escape(acronym)}\b", acronym.upper(), title, flags=re.I)
        title = re.sub(r"(?<!^)\b(A|An|And|For|In|Of|On|To)\b", lambda match: match.group(1).lower(), title)
        title = re.sub(r"\b(\d+)(St|Nd|Rd|Th)\b", lambda match: match.group(1) + match.group(2).lower(), title)
    lower = title.lower()
    if any(word in lower for word in ("sphere surface area", "surface area of sphere", "sphere area", "archimedes", "4 pi r", "4\pi r")):
        return Concept(
            title,
            "A sphere's area can be seen by matching latitude bands to a cylinder around it.",
            "Slice the sphere into thin horizontal bands, project each band to a matching cylinder band, then stack the bands to reveal the area.",
            r"A=4\pi R^2",
            ["circles", "area", "cylinders"],
            "Do not treat the formula as magic; the band matching is the reason the factor 4 appears.",
            "Put a sphere of radius R inside a cylinder of radius R and height 2R.",
            "Match each thin sphere band to the cylinder band at the same height; the band areas agree in the limiting picture.",
            "The cylinder side has area circumference times height, so 2 pi R times 2R equals 4 pi R squared.",
            "What visual object has the same area as the sphere?",
            "The side of the enclosing cylinder, not its top and bottom caps.",
            "sphere_surface_area",
        )
    if domain == "algorithms":
        semantic_family = cs_semantic_family_for_topic(lower)
        visual = cs_visual_kind_for_topic(lower)
        if semantic_family not in CS_SEMANTIC_FAMILIES or visual not in CS_VISUAL_KINDS:
            raise ValueError(
                f"Unsupported source-derived CS topic {title!r}: add a semantic visual family before planning it"
            )
        hook, intuition, formula, prereqs, misconception = cs_source_copy(title, semantic_family)
        setup, calc, takeaway, question, answer = concrete_cs_example(title, semantic_family)
        return Concept(
            title,
            hook,
            intuition,
            formula,
            prereqs,
            misconception,
            setup,
            calc,
            takeaway,
            question,
            answer,
            visual,
        )
    if domain == "group_theory":
        visual = "group_structure"
        formula = r"(G,*)"
        prereqs = ["groups", "sets", "maps"]
        algebra_spec = resolve_algebra_video_model(title)
        if algebra_spec is not None:
            visual = algebra_spec.visual_kind
            formula = algebra_spec.canonical_formula
            prereqs = ["groups", "operations", "subsets"]
        elif any(word in lower for word in ("coset", "quotient", "normal", "lagrange")):
            visual, formula, prereqs = "group_cosets", r"gH", ["subgroups", "equivalence classes"]
        elif any(word in lower for word in ("homomorphism", "isomorphism", "kernel", "image")):
            visual, formula, prereqs = "group_homomorphism", r"\phi(ab)=\phi(a)\phi(b)", ["groups", "functions"]
        elif any(word in lower for word in ("action", "orbit", "stabilizer", "permutation", "symmetry")):
            visual, formula, prereqs = "group_action", r"Gx", ["groups", "sets"]
        setup, calc, takeaway, question, answer = concrete_source_example(title, domain, visual)
        algebra_copy = {
            "algebra_ring_structure": (
                "A ring links addition and multiplication through distributivity.",
                "Keep the same elements visible while both sides of the distributive law resolve to one value.",
            ),
            "algebra_ideal_quotient": (
                "An ideal absorbs multiplication before it defines a quotient ring.",
                "Check additive closure and absorption on one subset, then collapse its elements to zero in the quotient.",
            ),
            "algebra_field_structure": (
                "A field turns division by a nonzero element into multiplication by its inverse.",
                "Search one finite carrier for the inverse, retain it, and use it to resolve a concrete quotient.",
            ),
        }
        hook, intuition = algebra_copy.get(
            visual,
            (
                f"{title} organizes how algebraic objects behave.",
                f"{title} names its objects, operation, and preserved property.",
            ),
        )
        return Concept(
            title,
            hook,
            intuition,
            formula,
            prereqs,
            "Do not use the term as a label only; check the hypotheses in a small example.",
            setup,
            calc,
            takeaway,
            question,
            answer,
            visual,
        )
    if domain == "calculus":
        visual = "calculus_tangent"
        formula = r"f'(x)=\lim_{h\to0}\frac{f(x+h)-f(x)}{h}"
        prereqs = ["functions", "graphs", "limits"]
        if any(word in lower for word in ("integral", "area", "riemann", "accumulation")):
            visual, formula, prereqs = "calculus_area", r"\int_a^b f(x)\,dx", ["functions", "area", "limits"]
        setup, calc, takeaway, question, answer = concrete_source_example(title, domain, visual)
        return Concept(
            title,
            f"{title} is a visual calculus idea about how a quantity changes or accumulates.",
            f"Study {title} by animating the graph, the local tangent or the accumulated area, and the limiting motion that makes the formula true.",
            formula,
            prereqs,
            "Do not treat the notation as the idea; the moving tangent or growing area is the idea.",
            setup,
            calc,
            takeaway,
            question,
            answer,
            visual,
        )
    if domain == "probability":
        visual = "probability"
        formula = r"P(A\mid B)=\frac{P(A\cap B)}{P(B)}"
        prereqs = ["sets", "fractions", "counting"]
        if any(word in lower for word in ("markov", "transition", "state")):
            visual, formula, prereqs = "markov", r"p_{t+1}=Pp_t", ["probability", "matrices", "states"]
        setup, calc, takeaway, question, answer = concrete_source_example(title, domain, visual)
        return Concept(
            title,
            f"{title} describes how uncertainty is split, moved, or updated.",
            f"Study {title} by drawing the sample space or states, moving probability mass, and highlighting what is conditioned or updated.",
            formula,
            prereqs,
            "Do not leave probability as an abstract number; show the mass or region it measures.",
            setup,
            calc,
            takeaway,
            question,
            answer,
            visual,
        )
    if domain == "economics":
        spec = economics_topic_spec(title, fail_closed=True)
        assert spec is not None
        visual, mode, formula, prereqs = spec
        family_copy = {
            "econ_tax_wedge": ("A tax changes both the traded quantity and the price seen on each side of the market.", "Keep the original equilibrium fixed, insert the wedge, and measure the lost-trade triangle from the same curves."),
            "game_payoff": ("A strategic choice is incomplete until the rival's action and both payoffs are visible.", "Compare each player's payoff against one fixed rival action at a time, then intersect the best responses."),
            "econ_elasticity": ("Elasticity turns two proportional changes into one unit-free response measure.", "Move between two measured price-quantity states and compute the percentage ratio from those same points."),
            "econ_budget": ("Consumer choice is a movement among bundles constrained by prices and income.", "Keep the budget or utility object visible while the feasible bundle, slope, or decomposition changes."),
            "econ_supply_demand": ("Market outcomes come from a crossing plus the policy or shift imposed on that same graph.", "Preserve both market curves while the equilibrium, surplus region, or control line changes."),
            "econ_curve": ("Marginal reasoning compares concept-specific benefit, cost, product, or revenue curves.", "Name each economic quantity on the axes and transform the curve state that determines the optimum."),
            "econ_externality_wedge": ("An external cost separates private cost from social cost.", "Keep MPC fixed, construct MSC from the wedge, and move quantity from the private to the social optimum."),
            "econ_production_isoquants": ("A production function maps input bundles to output levels.", "Move one persistent labor-capital bundle along an isoquant, then expand it onto a higher-output isoquant."),
            "econ_cost_curves": ("Marginal and average cost answer different output questions.", "Preserve both curves and move the output marker to the point where marginal cost crosses average cost at its minimum."),
            "econ_perfect_competition": ("A competitive firm takes the market price as given.", "Resolve the market price, carry it into the firm panel, and choose output where that price meets marginal cost."),
            "econ_monopoly": ("A monopolist chooses quantity with marginal revenue, then reads price from demand.", "Keep demand, marginal revenue, and marginal cost distinct while the chosen quantity and price are projected in order."),
            "econ_public_goods_vertical_sum": ("Public-good value adds willingness to pay at a shared quantity.", "Align every person's marginal benefit at one quantity and stack those values vertically before comparing with marginal cost."),
            "econ_international_trade": ("A world price separates domestic consumption from domestic production, with the gap becoming imports or exports.", "Keep domestic demand and supply fixed, place the world-price line on the same graph, and measure the quantity gap at that price."),
            "econ_tariff": ("A tariff raises the domestic price above the world price and contracts the import gap.", "Preserve the free-trade benchmark, add the tariff wedge, move both import endpoints, and account for revenue and deadweight loss from the same curves."),
            "econ_labor_market": ("A labor market clears where firms' labor demand meets workers' labor supply.", "Keep labor demand and supply distinct while a wage or demand change moves employment to the new intersection."),
            "econ_adverse_selection": ("Adverse selection changes the composition of a market when privately known risk affects participation.", "Track the low-risk and high-risk groups separately as the pooled price changes who remains in the market."),
            "econ_moral_hazard": ("Moral hazard changes behavior after coverage lowers the private cost of an action.", "Hold the underlying resource cost visible while coverage changes the price faced by the decision maker and therefore the chosen quantity."),
            "econ_healthcare_insurance": ("Health insurance separates the price paid by a patient from the resource cost of care.", "Show the patient price, insurer payment, and total resource cost together before comparing the insured and uninsured quantities."),
        }
        hook, intuition = family_copy[visual]
        model = resolve_economics_model(title, fail_closed=True)
        assert model is not None
        video_route = resolve_economics_video_route(model.model_id, fail_closed=True)
        assert video_route is not None
        hook = video_route.invariant
        intuition = " ".join(step[1] for step in video_route.steps)
        setup, calc, takeaway, question, answer = concrete_source_example(title, domain, visual)
        return Concept(
            title,
            f"{title}: {hook}",
            intuition,
            formula,
            prereqs,
            f"Do not explain {title} with an unnamed generic curve; preserve the economic objects and the state change the formula summarizes.",
            setup,
            calc,
            takeaway,
            question,
            answer,
            visual,
        )
    if domain == "physics":
        spec = physics_topic_spec(title, fail_closed=True)
        assert spec is not None
        visual, formula, prereqs = spec
        family_copy = {
            "physics_force": ("A force diagram should predict the acceleration, not merely decorate a cart.", "Resolve every force into the net vector before changing the object's motion."),
            "physics_kinematics": ("One moving point can be read three ways: position, velocity, and acceleration.", "Evolve one trajectory and keep its object, graph, and numerical state synchronized."),
            "physics_vector": ("A unit vector keeps a direction while stripping away its scale.", "Build the vector from components, measure its length, then normalize the same arrow."),
            "physics_center_of_mass": ("The center of mass is the point where weighted positions balance.", "Place the actual masses, accumulate their moments, and mark the computed balance point."),
            "physics_rocket": ("Variable mass carries momentum across a moving system boundary.", "Track mass flow and exhaust velocity so every thrust or velocity gain has a visible momentum source."),
            "physics_mass_transfer": ("A fixed control volume gains mass only when inlet flow exceeds outlet flow.", "Keep the boundary fixed, move mass through its ports, and let net flux update the stored amount."),
            "physics_ode": ("A differential equation is a rule that continuously updates a state.", "Start from an initial condition and let the rate field generate the trajectory rather than showing a static formula."),
            "physics_work": ("Work turns force along a path into a change in kinetic energy.", "Move the same object through the measured displacement while its energy bar changes by the computed work."),
            "physics_energy": ("Energy conservation follows one total while its forms exchange.", "Keep the total fixed and transfer measured amounts between potential and kinetic energy."),
            "physics_momentum": ("Interactions redistribute momentum without changing an isolated system's total.", "Move the actual bodies into the interaction and recompute the shared final velocity from total momentum."),
            "physics_potential": ("A potential curve is a map of where motion is energetically allowed.", "Compare U(x) with a fixed total-energy line and derive turning points from their intersections."),
            "physics_circular": ("Circular motion changes direction even when speed stays fixed.", "Rotate the position and velocity continuously while the radial acceleration remains pointed at the center."),
            "physics_rotation": ("Torque measures how effectively a force changes angular momentum.", "Apply the force at its real lever arm and let angular impulse grow over the stated time."),
            "physics_recoil": ("Recoil is signed momentum balance viewed from a chosen frame.", "Send the two bodies in opposite directions and preserve zero total momentum throughout."),
            "physics_wave": ("A wave carries a repeating pattern through space and time.", "Animate phase motion while wavelength and frequency determine the measured speed."),
        }
        hook, intuition = family_copy[visual]
        if "gyroscope" in lower:
            hook = "A gyroscope precesses because torque turns its angular-momentum vector."
            intuition = "Keep the spin angular momentum visible, apply gravity's torque about the support, and rotate the vector sideways at the precession rate."
            formula = r"\Omega_p=\frac{\tau}{L}=\frac{Mgr}{I\omega}"
            prereqs = ["torque", "angular momentum", "rigid-body rotation"]
        video_model = resolve_physics_video_model(title)
        if "gyroscope" in lower:
            pass
        elif video_model is not None and video_model.model_id == "rigid_body_angular_momentum":
            hook = "Mass distribution sets I; I maps ω to L."
            intuition = "Rotate an extended body about a principal axis, then apply the inertia tensor to the angular-velocity vector to obtain angular momentum."
        elif video_model is not None and video_model.family == "rolling_kinematics":
            hook = "Rolling without slipping ties a body's center motion to its rotation at one instantaneously stationary contact point."
            intuition = "Track one rolling body, match center displacement to rotated arc length, and preserve zero relative speed at the ground contact."
        elif "laws of motion" in lower:
            hook = "An interaction force pair is equal and opposite, but unequal masses do not share an acceleration."
            intuition = "Draw the force on each body separately, preserve the signed pair, and divide by each body's own mass."
        elif "potential energy and energy conservation" in lower:
            hook = "A compressed spring stores a fixed total that becomes kinetic energy as it crosses equilibrium."
            intuition = "Animate one oscillator while its spring and kinetic energy bars exchange without changing their sum."
        elif lower.strip() == "conservation of energy":
            hook = "A falling mass loses gravitational potential energy by exactly the amount its kinetic energy gains."
            intuition = "Move the mass between measured heights while transferring the computed energy between the same two bars."
        elif "uniform circular motion" in lower:
            hook = "Uniform circular motion keeps speed fixed while the velocity arrow rotates through every tangent direction."
            intuition = "Complete a full orbit with one moving point, a tangent velocity, an inward acceleration, and a measured period."
        elif "circular motion acceleration" in lower:
            hook = "Nearby tangent velocities differ inward."
            intuition = "Subtract the tangent velocities, then divide inward Delta v by Delta t."
        elif "circular motion position" in lower:
            hook = "A rotating radius generates two synchronized coordinate projections."
            intuition = "Rotate one radius and project the same endpoint onto both axes before evaluating its ordered pair."
        setup, calc, takeaway, question, answer = concrete_source_example(title, domain, visual)
        if "gyroscope" in lower:
            setup = "A rapidly spinning wheel has angular momentum L=12 kg m^2/s while gravity produces a horizontal torque of 3 N m about its support."
            calc = "For steady precession, Omega_p=tau/L=3/12=0.25 rad/s; the torque changes L's direction rather than its spin-axis magnitude in the ideal approximation."
            takeaway = "The spin axis precesses around the vertical because dL/dt is perpendicular to L."
            question = "Why does the wheel not simply fall in the ideal steady-precession picture?"
            answer = "The gravitational torque continually redirects the large spin angular momentum, producing sideways precession."
        return Concept(
            title,
            hook,
            intuition,
            formula,
            prereqs,
            "Do not substitute a generic force cart; the visual state must preserve this topic's own quantities and units.",
            setup,
            calc,
            takeaway,
            question,
            answer,
            visual,
        )
    setup, calc, takeaway, question, answer = concrete_source_example(title, domain, "numeric_rule")
    return Concept(
        title,
        f"{title} is a core idea in this course.",
        f"Understand {title} by connecting definition, formula, and example.",
        title,
        ["course definitions", "worked examples"],
        "Do not memorize the term without testing it on a concrete example.",
        setup,
        calc,
        takeaway,
        question,
        answer,
        "numeric_rule",
    )


def source_term_quality(term: str, count: int = 1) -> int:
    normalized = re.sub(r"\s+", " ", term.lower()).strip()
    words = normalized.split()
    score = min(count, 8) * 3 + min(len(words), 3)
    if any(word in SOURCE_TERM_PREFERRED_MARKERS for word in words):
        score += 18
    if any(marker in normalized for marker in SOURCE_TERM_CONTEXT_MARKERS):
        score += 6
    if len(words) == 1 and normalized not in SOURCE_TERM_PREFERRED_MARKERS:
        score -= 4
    if any(word in {"course", "lecture", "notes", "problem", "resource", "section"} for word in words):
        score -= 5
    if any(pattern in normalized for pattern in SOURCE_TERM_BLOCK_PATTERNS):
        score -= 60
    return score


def canonical_source_term(term: str) -> str:
    normalized = re.sub(r"\s+", " ", term.lower()).strip()
    rewrites = (
        (r"\bpriority queue\b", "priority queue"),
        (r"\bshortest paths?\b", "shortest paths"),
        (r"\btopological sort\b", "topological sort"),
        (r"\bdata structures?\b", "data structures"),
        (r"\bbinary trees?\b", "binary trees"),
        (r"\bhash tables?\b", "hash tables"),
    )
    for pattern, replacement in rewrites:
        if re.search(pattern, normalized):
            return replacement
    return normalized


def source_person_name_data(text: str) -> tuple[set[str], set[str]]:
    """Return instructor names and their tokens without treating arbitrary title case as a person."""
    names: set[str] = set()
    tokens: set[str] = set()
    pattern = re.compile(r"\b(?i:prof(?:essor)?|dr)\.?\s+([A-Z][A-Za-z'-]+\s+[A-Z][A-Za-z'-]+)\b")
    for match in pattern.finditer(text):
        normalized = re.sub(r"\s+", " ", match.group(1).lower()).strip()
        names.add(normalized)
        tokens.update(normalized.split())
    return names, tokens


def is_person_name_term(term: str, names: set[str], name_tokens: set[str]) -> bool:
    normalized = re.sub(r"\s+", " ", term.lower()).strip()
    words = normalized.split()
    return normalized in names or bool(words) and all(word in name_tokens for word in words)


def canonical_outline_topic(title: str, domain: str | None) -> str:
    topic = re.sub(r"\s+", " ", title).strip(" -:;,.")
    if domain == "algorithms":
        lower = topic.lower()
        if "binary tree" in lower and "avl" in lower:
            return "AVL Trees and Rotations"
        if "binary tree" in lower:
            return "Binary Search Trees"
        if "dynamic programming" in lower and "recursive" in lower:
            return "Memoization and Recursive Dynamic Programming"
        if "dynamic programming" in lower and "subproblem" in lower:
            return "Dynamic Programming State Design"
        if "dynamic programming" in lower and any(term in lower for term in ("apsp", "paren", "piano", "application")):
            return "Dynamic Programming Applications"
        if "dynamic programming" in lower and "pseudopolynomial" in lower:
            return "Pseudopolynomial Dynamic Programming"
    return topic


def source_outline_topics(pack: dict[str, object], limit: int = 80) -> list[str]:
    """Extract ordered, numbered course units before statistical term ranking."""
    if is_mit_18_703_pack(pack):
        return list(MIT_18_703_CALENDAR_ORDER[:limit])
    domain = detected_domain(pack)
    unit_re = re.compile(
        r"\b(?:lecture|lec\.?|lesson|unit|chapter|session)\s+(\d{1,3}[a-z]?)\s*[:\-]\s*"
        r"(.{3,120}?)(?=\s+(?:lecture|lec\.?|lesson|unit|chapter|session)\s+\d{1,3}[a-z]?\s*[:\-]|[\n\r|]|$)",
        re.I,
    )
    generic = {
        "introduction", "overview", "course overview", "course review", "review",
        "final review", "next steps", "algorithms next steps",
    }
    candidates: dict[tuple[int, str], tuple[int, str]] = {}
    materials = pack.get("materials") if isinstance(pack.get("materials"), list) else []
    preferred_materials = [
        material for material in materials
        if isinstance(material, dict)
        and any(
            marker in f"{material.get('title', '')} {material.get('url', '')}".lower()
            for marker in ("calendar", "schedule", "syllabus", "course-outline", "course_outline")
        )
    ]
    scanned_materials = preferred_materials or materials
    for material_index, material in enumerate(scanned_materials):
        if not isinstance(material, dict):
            continue
        text = str(material.get("text", ""))
        for match in unit_re.finditer(text):
            unit_digits = re.match(r"\d+", match.group(1))
            if not unit_digits:
                continue
            unit_number = int(unit_digits.group(0))
            raw_title = re.sub(r"\s+", " ", match.group(2)).strip(" -:;,.")
            raw_title = re.sub(r"\s*\[[^\]]+\]\s*$", "", raw_title).strip()
            raw_title = re.sub(r"\s+(?:MIT OpenCourseWare|Introduction to .*)$", "", raw_title, flags=re.I).strip()
            topic = canonical_outline_topic(raw_title, domain)
            normalized = re.sub(r"[^a-z0-9]+", " ", topic.lower()).strip()
            if normalized in generic or not 4 <= len(topic) <= 100:
                continue
            key = (unit_number, normalized)
            if key not in candidates:
                candidates[key] = (material_index, topic)
    ordered = sorted(candidates.items(), key=lambda item: (item[0][0], item[1][0], item[0][1]))
    topics: list[str] = []
    seen: set[str] = set()
    for (_unit, normalized), (_material_index, topic) in ordered:
        if normalized in seen:
            continue
        seen.add(normalized)
        topics.append(topic)
        if len(topics) >= limit:
            break
    if len(topics) < limit:
        deep_dive_re = re.compile(
            r"\bdeep\s+dive\s*:\s*(.{3,100}?)(?=\s*\[(?:DD|deep\s+dive)|[\n\r|]|$)",
            re.I,
        )
        for material in scanned_materials:
            if not isinstance(material, dict):
                continue
            for match in deep_dive_re.finditer(str(material.get("text", ""))):
                topic = canonical_outline_topic(match.group(1).strip(" -:;,.") , domain)
                normalized = re.sub(r"[^a-z0-9]+", " ", topic.lower()).strip()
                if normalized and normalized not in seen:
                    seen.add(normalized)
                    topics.append(topic)
                    if len(topics) >= limit:
                        return topics
    return topics


def frequent_terms(text: str) -> list[str]:
    stop = {
        "course", "lecture", "lectures", "chapter", "section", "the", "and", "for", "with", "this", "that",
        "from", "have", "notes", "page", "problem", "problems", "example", "examples", "using", "where",
        "there", "which", "then", "than", "into", "will", "shall", "their", "about", "between", "through",
        "also", "available", "content", "copyright", "download", "file", "files", "instructor", "learn", "learning",
        "material", "materials", "metadata", "navigation", "online", "open", "publication", "related", "reserved", "rights",
        "share", "site", "student", "students", "study", "studies", "topic", "topics", "undergraduate", "back", "top",
    }
    person_names, person_tokens = source_person_name_data(text)
    counts: dict[str, int] = {}
    phrase_counts: dict[str, int] = {}
    segments = re.split(r"[\n\r|,;]+|(?<=[.!?])\s+", text)
    for segment in segments:
        original_words = re.findall(r"\b[A-Za-z][A-Za-z'-]*\b", segment)
        words = [word.lower() for word in original_words]
        for original, word in zip(original_words, words):
            if word in SOURCE_TERM_APPROVED_ACRONYMS and original.isupper():
                counts[original.upper()] = counts.get(original.upper(), 0) + 1
            elif len(word) >= 4 and word not in stop and is_course_vocabulary_term(word):
                if not is_person_name_term(word, person_names, person_tokens):
                    counts[word] = counts.get(word, 0) + 1
        for size in (2, 3, 4, 5, 6):
            for i in range(max(0, len(words) - size + 1)):
                phrase_words = words[i : i + size]
                phrase = " ".join(phrase_words)
                if len(set(phrase_words) - SOURCE_TERM_CONNECTORS) < 2:
                    continue
                if is_person_name_term(phrase, person_names, person_tokens):
                    continue
                if is_course_vocabulary_term(phrase):
                    phrase_counts[phrase] = phrase_counts.get(phrase, 0) + 1
    ranked_phrases = [
        p for p, n in sorted(
            phrase_counts.items(),
            key=lambda item: (source_term_quality(item[0], item[1]), item[1], len(item[0])),
            reverse=True,
        ) if n >= 2 or p in KNOWN_COURSE_PHRASES
    ]
    ranked_words = [
        w for w, n in sorted(
            counts.items(),
            key=lambda item: (source_term_quality(item[0], item[1]), item[1]),
            reverse=True,
        )
    ]
    out: list[str] = []
    for term in ranked_phrases + ranked_words:
        normalized = canonical_source_term(term)
        if normalized.lower() in SOURCE_TERM_APPROVED_ACRONYMS:
            normalized = normalized.upper()
        if normalized and all(normalized not in existing and existing not in normalized for existing in out):
            out.append(normalized)
    return out

def source_text(pack: dict[str, object]) -> str:
    return "\n".join(str(m.get("text", "")) for m in pack.get("materials", []) if isinstance(m, dict))


def is_course_vocabulary_term(term: str) -> bool:
    original_words = re.findall(r"[A-Za-z][A-Za-z'-]*", term)
    normalized = re.sub(r"\s+", " ", term.lower()).strip(" -_:;,.()[]")
    if normalized in SOURCE_TERM_APPROVED_ACRONYMS:
        return True
    normalized_words = set(re.findall(r"[a-z]+", normalized))
    if (
        2 <= len(original_words) <= 3
        and all(word[0].isupper() for word in original_words)
        and not normalized_words & SOURCE_TERM_PREFERRED_MARKERS
    ):
        return False
    if len(normalized) < 4 or len(normalized) > 60:
        return False
    if normalized in SOURCE_TERM_BLOCKLIST:
        return False
    if normalized in SOURCE_TERM_METADATA_LABELS:
        return False
    if any(pattern in normalized for pattern in SOURCE_TERM_BLOCK_PATTERNS):
        return False
    words = normalized.split()
    if len(words) > 6:
        return False
    if any(len(re.sub(r"[^a-z]", "", word)) == 1 for word in words):
        return False
    if any(word in SOURCE_TERM_BLOCKLIST for word in words):
        return False
    if any(word in SOURCE_TERM_FUNCTION_WORDS for word in words):
        return False
    if words[0] in SOURCE_TERM_CONNECTORS or words[-1] in SOURCE_TERM_CONNECTORS:
        return False
    if not any(re.search(r"[a-z]", word) for word in words):
        return False
    if re.fullmatch(r"(?:lecture|session|unit|chapter|section)\s+\d+[a-z]?", normalized):
        return False
    if re.fullmatch(r"(?:pdf|html|www|http|https|email|copyright|reserved)s?", normalized):
        return False
    if normalized.startswith("number of "):
        return False
    generic_words = {"activity", "available", "content", "description", "information", "material", "materials", "overview", "resource", "resources", "topic", "topics"}
    if all(word in generic_words for word in words):
        return False
    return True


def source_coverage_terms(pack: dict[str, object], shorts: list[dict[str, object]], limit: int = 80) -> list[str]:
    existing = {str(short.get("concept", "")).lower() for short in shorts}
    terms: list[str] = []
    for term in frequent_terms(source_text(pack)):
        if not is_course_vocabulary_term(term):
            continue
        term_words = set(re.findall(r"[a-z]+", term.lower()))
        if term.lower() not in SOURCE_TERM_APPROVED_ACRONYMS and not term_words & SOURCE_TERM_PREFERRED_MARKERS:
            continue
        normalized_term = term.lower()
        if any(normalized_term in concept or concept in normalized_term for concept in existing):
            continue
        if term not in terms:
            terms.append(term)
        if len(terms) >= limit:
            break
    return terms


def is_source_boilerplate_text(text: str) -> bool:
    normalized = re.sub(r"\s+", " ", text.lower()).strip()
    if normalized in SOURCE_TERM_METADATA_LABELS:
        return True
    if re.match(r"(?:lecture|recitation)\s+\d+", normalized) and len(normalized) < 120:
        return True
    if any(pattern in normalized for pattern in SOURCE_TERM_BLOCK_PATTERNS):
        return True
    boilerplate_tokens = {
        "accessibility", "copyright", "download", "faqs", "instructor", "license", "navigation",
        "opencourseware", "publication", "reserved", "transcript",
    }
    words = set(re.findall(r"[a-z]+", normalized))
    if words & {"instructor", "instructors", "prof", "professor"}:
        return True
    if len(words & {"lecture", "recitation", "notes", "pdf"}) >= 2:
        return True
    if words & {"homework", "assignment"} or "due" in words and words & {
        "monday", "tuesday", "wednesday", "thursday", "friday",
    }:
        return True
    return len(words & boilerplate_tokens) >= 2


def normalized_source_materials(pack: dict[str, object]) -> list[str]:
    return [
        re.sub(r"\s+", " ", str(material.get("text", ""))).strip()
        for material in pack.get("materials", [])
        if isinstance(material, dict) and str(material.get("text", "")).strip()
    ]


def source_snippets(
    pack: dict[str, object],
    term: str,
    limit: int = 2,
    materials: list[str] | None = None,
) -> list[str]:
    snippets: list[str] = []
    term_lower = term.lower().strip()
    if len(term_lower) < 3:
        return snippets
    for text in materials if materials is not None else normalized_source_materials(pack):
        lower = text.lower()
        pos = 0
        attempts = 0
        while len(snippets) < limit and attempts < 24:
            idx = lower.find(term_lower, pos)
            if idx < 0:
                break
            start = max(0, idx - 180)
            end = min(len(text), idx + len(term_lower) + 220)
            while start > 0 and text[start] not in ".?!":
                start -= 1
            if start > 0:
                start += 1
            while end < len(text) and text[end] not in ".?!":
                end += 1
            cleaned = re.sub(r"\s+", " ", text[start:end].strip(" .?!"))
            if is_source_boilerplate_text(cleaned):
                pos = idx + len(term_lower)
                attempts += 1
                continue
            if 40 <= len(cleaned) <= 360 and cleaned not in snippets:
                snippets.append(cleaned)
            pos = idx + len(term_lower)
            attempts += 1
        if len(snippets) >= limit:
            return snippets
    return snippets


def source_evidence_for_term(
    pack: dict[str, object],
    term: str,
    materials: list[str] | None = None,
    person_names: set[str] | None = None,
) -> list[str]:
    if person_names is None:
        person_names, _person_tokens = source_person_name_data(source_text(pack))

    def cleaned_evidence(value: str) -> str:
        cleaned = re.sub(r"\s+", " ", value).strip()
        if len(cleaned) < 30:
            return ""
        lower = cleaned.lower()
        if any(name in lower for name in person_names):
            return ""
        if is_source_boilerplate_text(cleaned):
            return ""
        return cleaned

    for snippet in source_snippets(pack, term, limit=3, materials=materials):
        cleaned = cleaned_evidence(snippet)
        if cleaned:
            return [cleaned]
    term_lower = term.lower().strip()
    for material in pack.get("materials", []):
        if not isinstance(material, dict):
            continue
        raw_lines = str(material.get("text", "")).splitlines()
        for index, raw_line in enumerate(raw_lines):
            line = re.sub(r"\s+", " ", raw_line).strip(" -:;,.()[]")
            if term_lower not in line.lower() or not 8 <= len(line) <= 240 or not cleaned_evidence(line):
                continue
            following = ""
            for candidate in raw_lines[index + 1 : index + 4]:
                following = re.sub(r"\s+", " ", candidate).strip()
                if following:
                    break
            combined = f"{line}. {following}".strip()
            if len(combined) <= 360 and (cleaned := cleaned_evidence(combined)):
                return [cleaned]
            if cleaned := cleaned_evidence(line):
                return [cleaned]
    return []


def source_evidences_term(pack: dict[str, object], term: str) -> bool:
    normalized = re.sub(r"[^a-z0-9]+", " ", term.lower()).strip()
    if not normalized:
        return False
    evidence = re.sub(r"[^a-z0-9]+", " ", source_text(pack).lower())
    variants = {normalized}
    if normalized == "singular value decomposition":
        variants.add("svd")
    if normalized == "breadth first search":
        variants.add("bfs")
    if normalized == "depth first search":
        variants.add("dfs")
    for variant in variants:
        if re.search(rf"\b{re.escape(variant)}\b", evidence):
            return True
    content_words = [
        word for word in normalized.split()
        if word not in SOURCE_TERM_CONNECTORS and word not in {"groups", "matrices", "theory"}
    ]
    if len(content_words) < 2:
        return False
    ordered = r"\b" + r"\b.{0,80}\b".join(re.escape(word) for word in content_words) + r"\b"
    return re.search(ordered, evidence) is not None


def routed_concept_visual_type(concept_name: object, declared_visual: object) -> str:
    declared = str(declared_visual or "").strip()
    physics_spec = physics_topic_spec(str(concept_name))
    if physics_spec is not None:
        return physics_spec[0]
    if declared.lower() not in {"", "generic", "numeric_rule"}:
        return declared
    algebra_spec = resolve_algebra_video_model(str(concept_name))
    return algebra_spec.visual_kind if algebra_spec is not None else (declared or "numeric_rule")


def canonical_scenario_worked_example(scenario: dict[str, object]) -> dict[str, str]:
    """Turn typed scenario evidence into readable prose without inventing evidence."""
    result_key = "result" if isinstance(scenario.get("result"), dict) else "results"

    def evidence_values(section: str, lead: str) -> str:
        values = scenario.get(section)
        if not isinstance(values, dict):
            raise ValueError(f"Model scenario is missing its {section!r} evidence mapping.")
        fields = "; ".join(f"{key} is {value}" for key, value in values.items())
        return f"{lead}: {fields}." if fields else f"{lead}: no additional values."

    required = scenario.get("required_example_tokens")
    tokens = [str(token) for token in required] if isinstance(required, (list, tuple)) else []
    token_text = "; ".join(tokens)
    setup = evidence_values("setup", "Use the exact scenario inputs")
    if token_text:
        setup += f" Track the required evidence labels exactly: {token_text}."
    return {
        "setup": setup,
        "calculation": evidence_values("calculation", "The recomputed calculation gives"),
        "takeaway": evidence_values(result_key, "Therefore the scenario result is"),
    }


def canonical_physics_worked_example(scenario: dict[str, object]) -> dict[str, str]:
    """Serialize one recomputed physics scenario with its exact evidence vocabulary."""
    return canonical_scenario_worked_example(scenario)


def attach_plan_model_identity(short: dict[str, object]) -> None:
    """Attach authoritative model/scenario identity before downstream planning."""
    visual_type = str(short.get("visual_type", ""))
    concept = str(short.get("concept", ""))
    group_route = resolve_group_video_model(concept, fail_closed=False)
    if group_route is not None:
        payload = build_group_video_payload(concept)
        short["visual_type"] = group_runtime_visual_kind(concept)
        short["hook"] = str(payload["transitions"][0]["claim"])
        short["intuition"] = str(payload["invariant"])
        short["formula"] = payload["canonical_formula"]
        short["plain_formula"] = plain_math(str(payload["canonical_formula"]))
        exact_worked = dict(payload["worked_example"])
        exact_worked["takeaway"] = str(payload["reveal"])
        short["worked_example"] = exact_worked
        short["model_id"] = group_route.route_key.rsplit(":", 1)[-1]
        short["scenario_mode"] = group_route.visual_family
        short["model_scenario"] = payload
        return
    exact_physics_route = MIT_8_01_VIDEO_ROUTES.get(concept)
    if exact_physics_route is not None:
        worked = short.get("worked_example") if isinstance(short.get("worked_example"), dict) else None
        try:
            payload = build_physics_video_payload(concept, worked)
        except ValueError as exc:
            if "worked_example" not in str(exc) or "structured scenario" not in str(exc):
                raise
            payload = build_physics_video_payload(concept)
            scenario_fallback = payload["scenario"]
            short["worked_example"] = {
                "setup": ", ".join(f"{str(key).replace('_', ' ')} = {value}" for key, value in scenario_fallback["setup"].items()),
                "calculation": ", ".join(f"{str(key).replace('_', ' ')} = {value}" for key, value in scenario_fallback["calculation"].items()),
                "takeaway": ", ".join(f"{str(key).replace('_', ' ')} = {value}" for key, value in scenario_fallback["result"].items()),
            }
        scenario = dict(payload["scenario"])
        short["worked_example"] = canonical_physics_worked_example(scenario)
        short["visual_type"] = (
            "physics_kinematics"
            if exact_physics_route.family == "rolling_kinematics"
            else physics_runtime_visual_kind(exact_physics_route.visual_kind)
        )
        short["formula"] = payload["canonical_formula"]
        short["plain_formula"] = plain_math(str(payload["canonical_formula"]))
        short["model_id"] = payload["model_id"]
        short["scenario_mode"] = payload["mode"]
        short["model_scenario"] = scenario
        short["numeric_evidence_fingerprint"] = payload["numeric_evidence_fingerprint"]
        return
    exact_economics_model_id = MIT_14_01_TITLE_MODEL_IDS.get(concept)
    if exact_economics_model_id is not None:
        model = resolve_economics_model(exact_economics_model_id, fail_closed=True)
        assert model is not None
        scenario = get_economics_model_scenario(model.model_id).as_dict()
        expected_kind, _mode, canonical_formula, _prerequisites = economics_topic_spec(
            concept, fail_closed=True
        )
        short["visual_type"] = expected_kind
        short["formula"] = canonical_formula
        short["plain_formula"] = plain_math(canonical_formula)
        short["worked_example"] = canonical_scenario_worked_example(scenario)
        short["model_id"] = model.model_id
        short["scenario_mode"] = scenario["mode"]
        short["model_scenario"] = scenario
        short["numeric_evidence_fingerprint"] = scenario["numeric_evidence_fingerprint"]
        return
    if visual_type in PHYSICS_VISUAL_KINDS:
        model = resolve_physics_model(concept, fail_closed=True)
        scenario = get_physics_model_scenario(model.model_id).as_dict()
    elif visual_type in ECON_VISUAL_KINDS:
        model = resolve_economics_model(concept, fail_closed=True)
        scenario = get_economics_model_scenario(model.model_id).as_dict()
    else:
        return
    short["model_id"] = model.model_id
    short["scenario_mode"] = scenario["mode"]
    short["model_scenario"] = scenario


def authoritative_plan_concept(topic: str, domain: str | None) -> Concept:
    """Preserve an outline label even when its domain model is not registered yet."""
    try:
        concept = source_term_concept(topic, domain)
    except ValueError:
        concept = source_term_concept(topic, None)
    if concept.name == topic:
        return concept
    return Concept(
        topic, concept.hook, concept.intuition, concept.formula,
        list(concept.prerequisites), concept.misconception, concept.example_setup,
        concept.example_calc, concept.example_takeaway, concept.application_question,
        concept.application_answer, concept.visual_type,
    )


def cmd_plan(args: argparse.Namespace) -> None:
    run = Path(args.run)
    pack = read_json(run / "source_pack.json")
    outline_topics = source_outline_topics(pack)
    requested_max = int(getattr(args, "max_shorts", 0) or 0)
    allow_partial = bool(getattr(args, "allow_partial_plan", False))
    if requested_max < 0:
        raise SystemExit("--max-shorts must be zero (auto full) or a positive integer")

    if outline_topics:
        authoritative_count = len(outline_topics)
        if requested_max and requested_max < authoritative_count and not allow_partial:
            raise SystemExit(
                f"Source contains {authoritative_count} authoritative course units, but --max-shorts={requested_max} "
                "would truncate them. Use --allow-partial-plan to request an explicitly partial plan."
            )
        if requested_max and requested_max < authoritative_count:
            concepts = choose_concepts(pack, requested_max)
        else:
            domain = detected_domain(pack)
            concepts = [authoritative_plan_concept(topic, domain) for topic in outline_topics]
    else:
        authoritative_count = 0
        effective_max = requested_max or DEFAULT_SHORTS
        concepts = choose_concepts(pack, effective_max)
    shorts = [
        {
            "index": i,
            "concept": c.name,
            "hook": c.hook,
            "intuition": c.intuition,
            "formula": c.formula,
            "plain_formula": plain_math(c.formula),
            "prerequisites": c.prerequisites,
            "misconception": c.misconception,
            "worked_example": {
                "setup": c.example_setup,
                "calculation": c.example_calc,
                "takeaway": concise_result_claim(c.example_takeaway),
            },
            "question_prompt": {"question": c.application_question, "answer": c.application_answer},
            "visual_type": routed_concept_visual_type(c.name, c.visual_type),
        }
        for i, c in enumerate(concepts, start=1)
    ]
    for short in shorts:
        attach_plan_model_identity(short)
    topic_signatures = [
        (topic, frozenset(note_term_signature(topic)))
        for topic in outline_topics
    ]
    short_signatures = {
        int(short["index"]): frozenset(note_term_signature(str(short["concept"])))
        for short in shorts
    }
    exact_outline_owners = {
        signature: index
        for index, signature in short_signatures.items()
        if signature and any(signature == topic_signature for _topic, topic_signature in topic_signatures)
    }
    outline_units_by_short: dict[int, list[str]] = {int(short["index"]): [] for short in shorts}
    for topic, topic_signature in topic_signatures:
        owner = exact_outline_owners.get(topic_signature)
        if owner is None and topic_signature:
            nested_candidates = [
                (index, signature)
                for index, signature in short_signatures.items()
                if signature and (signature < topic_signature or topic_signature < signature)
            ]
            if nested_candidates:
                owner = max(
                    nested_candidates,
                    key=lambda row: (len(row[1] & topic_signature), -abs(len(row[1]) - len(topic_signature))),
                )[0]
        if owner is not None:
            outline_units_by_short[owner].append(topic)
    library_names = {
        concept.name.lower()
        for library in DOMAIN_LIBRARY.values()
        for concept in library
    }
    for short in shorts:
        outline_units = outline_units_by_short[int(short["index"])]
        if outline_units:
            short["coverage_basis"] = "authoritative-outline"
            short["source_outline_units"] = outline_units
        else:
            short["coverage_basis"] = "domain-library" if str(short["concept"]).lower() in library_names else "source-term"
    if detected_domain(pack) == "algorithms":
        unsupported = [
            str(short["concept"])
            for short in shorts
            if str(short.get("visual_type", "")) not in CS_VISUAL_KINDS
        ]
        if unsupported:
            raise ValueError(
                "CS planning requires semantic visuals; unsupported topics: " + ", ".join(unsupported)
            )
    for i, short in enumerate(shorts):
        next_concepts = [s["concept"] for s in shorts[i + 1 : i + 4]]
        short["key_concept"] = f"{short['concept']}: {short['hook']}"
        short["concept_explanation"] = (
            f"{short['intuition']} The worked example makes the idea testable: "
            f"{short['worked_example']['takeaway']}"
        )
        short["recognition_cue"] = recognition_cue_for_short(short)
        short["concept_connections"] = {
            "builds_on": short["prerequisites"],
            "prepares_for": next_concepts,
        }
    covered_outline_units = sum(outline_units_by_short.values(), [])
    omitted_units = [topic for topic in outline_topics if topic not in covered_outline_units]
    plan = {
        "course_title": pack.get("title", "Course"),
        "source_url": pack.get("source_url"),
        "authoritative_unit_count": authoritative_count,
        "covered_unit_count": authoritative_count - len(omitted_units),
        "omitted_units": omitted_units,
        "coverage_truncated": bool(omitted_units),
        "shorts": shorts,
    }
    write_json(run / "short_plan.json", plan)
    print(run / "short_plan.json")


def latex_escape(s: str) -> str:
    normalized = str(s)
    for source, replacement in {
        chr(0x2018): "'", chr(0x2019): "'", chr(0x201C): '"', chr(0x201D): '"',
        chr(0x2013): "--", chr(0x2014): "---", chr(0x2026): "...",
        chr(0x00A0): " ", chr(0x00AD): "",
    }.items():
        normalized = normalized.replace(source, replacement)
    return (normalized.replace("\\", r"\textbackslash{}").replace("&", r"\&").replace("%", r"\%").replace("$", r"\$")
             .replace("#", r"\#").replace("_", r"\_").replace("^", r"\^{}").replace("~", r"\textasciitilde{}")
             .replace("{", r"\{").replace("}", r"\}"))


FORMULA_MACROS = {
    "alpha", "begin", "beta", "bmod", "cdot", "cdots", "cong", "cos", "det", "dim", "Delta", "end", "epsilon", "exp",
    "frac", "gcd", "ge", "geq", "hat", "im", "in", "ker", "lambda", "Lambda", "langle", "lcm", "ldots",
    "le", "leq", "left", "ln", "log", "mathbb", "mathcal", "mathbf", "mid", "mu", "neq",
    "mod", "notin", "operatorname", "phi", "pi", "pmod", "prod", "rangle", "right", "Rightarrow", "sigma",
    "Sigma", "sin", "sqrt", "subset", "subseteq", "sum", "tan", "text", "theta", "times",
    "deg", "iff", "Longrightarrow", "ne", "rho", "tau", "triangleleft", "trianglelefteq",
    "varnothing", "varphi", "vec", "xrightarrow",
}


def formula_text_value(formula: str) -> str:
    text_value = str(formula).replace(r"\ ", " ").replace("\\", " ")
    return re.sub(r"\s+", " ", plain_math(text_value)).strip()


def formula_has_unknown_macros(formula: str) -> bool:
    return any(match.group(1) not in FORMULA_MACROS for match in re.finditer(r"\\([A-Za-z]+)", str(formula)))


def formula_like_string(formula: str) -> bool:
    raw = str(formula).strip()
    if not raw:
        return False
    if MATRIX_LITERAL_RE.search(raw) or ROW_MATRIX_RE.fullmatch(raw):
        return True
    has_relation = bool(re.search(r"(?:=|<=|>=|<|>|\\leq|\\geq|\\neq|\\subseteq|\\subset|\\in|\\notin|\\Rightarrow)", raw))
    has_math_structure = bool(re.search(r"[0-9_^{}()+*/]|\\[A-Za-z]+\b", raw))
    if has_relation or has_math_structure:
        words = re.findall(r"[A-Za-z]{3,}", re.sub(r"\\[A-Za-z]+", " ", raw))
        prose_markers = {"after", "before", "because", "contract", "hidden", "private", "public", "where", "when"}
        return len([word for word in words if word.lower() in prose_markers]) <= 2 or has_relation
    return False


