def is_mit_18_703_pack(pack: dict[str, object]) -> bool:
    title = str(pack.get("title", "")).lower()
    source_url = str(pack.get("source_url", "")).lower()
    lecture_pdfs = sum(
        1 for material in pack.get("materials", [])
        if isinstance(material, dict)
        and material.get("kind") == "pdf"
        and re.search(r"pra[_-]?l[_-]?\d+", str(material.get("title", "")), flags=re.I)
    )
    return "18-703-modern-algebra" in source_url or ("modern algebra" in title and lecture_pdfs >= 20)


def mit_18_703_material_coverage(pack: dict[str, object]) -> dict[str, object]:
    homework_topics = {1: 2, 2: 6, 3: 5, 4: 9, 5: 10, 6: 12, 7: 15, 8: 16, 9: 19, 10: 20, 11: 21}
    records: list[dict[str, object]] = []
    for material_index, material in enumerate(pack.get("materials", []), start=1):
        if not isinstance(material, dict):
            records.append({"material_index": material_index, "status": "uncovered", "reason": "non-object material"})
            continue
        title = str(material.get("title", ""))
        locator = f"{title} {material.get('url', '')}"
        lecture_match = re.search(r"pra[_-]?l[_-]?(\d+)", locator, flags=re.I)
        homework_match = re.search(r"(?:^|[_/])h(\d+)(?:[._/]|$)", locator, flags=re.I)
        topic_indices: list[int] = []
        role = "course-context"
        if lecture_match:
            lecture_number = int(lecture_match.group(1))
            topic_indices = [lecture_number] if 1 <= lecture_number <= 23 else []
            role = "lecture-notes" if material.get("kind") == "pdf" else "lecture-resource-page"
        elif homework_match:
            homework_number = int(homework_match.group(1))
            mapped = homework_topics.get(homework_number)
            topic_indices = [mapped] if mapped else []
            role = "homework-problems" if material.get("kind") == "pdf" else "homework-resource-page"
        elif title in {"Course landing page", "Lecture Notes", "Readings", "Syllabus", "Calendar", "Assignments"}:
            topic_indices = list(range(1, 25))
            role = "course-sequence-context"
        elif title == "Related Resources":
            role = "reviewed-context"
        status = "covered" if topic_indices else ("reviewed-context" if role == "reviewed-context" else "uncovered")
        records.append({
            "material_index": material_index,
            "title": title,
            "kind": material.get("kind"),
            "role": role,
            "topic_indices": topic_indices,
            "status": status,
        })
    substantive = [record for record in records if record.get("role") in {"lecture-notes", "homework-problems"}]
    uncovered = [record for record in records if record.get("status") == "uncovered"]
    return {
        "source_material_count": len(records),
        "reviewed_material_count": len(records) - len(uncovered),
        "substantive_material_count": len(substantive),
        "substantive_material_covered_count": sum(record.get("status") == "covered" for record in substantive),
        "uncovered_material_count": len(uncovered),
        "materials": records,
    }


def notes_contract_tokens(text: object) -> list[str]:
    return re.findall(r"[a-z0-9]+", str(text).lower())


def notes_semantic_anchor_present(text: object, anchor: object) -> bool:
    required = set(notes_contract_tokens(anchor))
    return bool(required) and required.issubset(set(notes_contract_tokens(text)))


def mit_18_703_validate_result_claim(
    result_id: str,
    statement: object,
    proof: object,
) -> dict[str, object]:
    contract = MIT_18_703_RESULT_CLAIM_CONTRACTS.get(result_id, {})
    issues: list[dict[str, object]] = []
    for clause_kind in ("hypotheses", "conclusions"):
        clauses = contract.get(clause_kind, []) if isinstance(contract, dict) else []
        for clause_index, clause in enumerate(clauses, start=1):
            if not isinstance(clause, dict):
                issues.append({"kind": "invalid-claim-contract", "clause": clause_kind, "index": clause_index})
                continue
            for location, value in (("statement", statement), ("proof", proof)):
                anchors = clause.get(location, ())
                missing = [
                    str(anchor) for anchor in anchors
                    if not notes_semantic_anchor_present(value, anchor)
                ]
                if missing:
                    issues.append({
                        "kind": f"{clause_kind[:-1]}-anchor-missing",
                        "clause": clause_kind,
                        "index": clause_index,
                        "location": location,
                        "missing": missing,
                    })
    return {
        "result_id": result_id,
        "status": "ok" if not issues else "failed",
        "hypothesis_clause_count": len(contract.get("hypotheses", [])) if isinstance(contract, dict) else 0,
        "conclusion_clause_count": len(contract.get("conclusions", [])) if isinstance(contract, dict) else 0,
        "issues": issues,
    }


def mit_18_703_validate_concept_prerequisites(shorts: list[dict[str, object]]) -> dict[str, object]:
    result_units: dict[str, int] = {}
    for unit, short in enumerate(shorts, start=1):
        payload = short.get("note_depth") if isinstance(short.get("note_depth"), dict) else {}
        for result in payload.get("results", []):
            if isinstance(result, dict) and str(result.get("id", "")).strip():
                result_units[str(result["id"])] = unit

    introduced: set[str] = set()
    checks: list[dict[str, object]] = []
    issues: list[dict[str, object]] = []
    for contract in MIT_18_703_CONCEPT_PREREQUISITES:
        concept_id = str(contract["id"])
        unit = int(contract["unit"])
        if unit < 1 or unit > len(shorts):
            issues.append({"kind": "concept-unit-missing", "concept_id": concept_id, "unit": unit})
            continue
        missing_prerequisites = [
            str(required) for required in contract.get("requires", ())
            if str(required) not in introduced
        ]
        payload = shorts[unit - 1].get("note_depth")
        definition = str(payload.get("definition", "")) if isinstance(payload, dict) else ""
        missing_anchors = [
            str(anchor) for anchor in contract.get("definition_anchors", ())
            if not notes_semantic_anchor_present(definition, anchor)
        ]
        compact_definition = re.sub(r"\s+", " ", definition)
        missing_literals = [
            str(literal) for literal in contract.get("definition_literals", ())
            if re.sub(r"\s+", " ", str(literal)) not in compact_definition
        ]
        prior_payload = json.dumps(
            [short.get("note_depth", {}) for short in shorts[: unit - 1]],
            ensure_ascii=False,
        )
        premature_uses = [
            str(literal) for literal in contract.get("use_literals", ())
            if str(literal) in prior_payload
        ]
        dependent_errors = [
            str(result_id) for result_id in contract.get("dependent_result_ids", ())
            if result_units.get(str(result_id), 0) < unit
        ]
        concept_issues: list[dict[str, object]] = []
        for kind, values in (
            ("missing-prerequisite", missing_prerequisites),
            ("incomplete-definition-anchor", missing_anchors),
            ("incomplete-definition-literal", missing_literals),
            ("notation-used-before-definition", premature_uses),
            ("dependent-result-before-concept", dependent_errors),
        ):
            if values:
                concept_issues.append({"kind": kind, "values": values})
        checks.append({
            "concept_id": concept_id,
            "unit": unit,
            "status": "ok" if not concept_issues else "failed",
            "issues": concept_issues,
        })
        if concept_issues:
            issues.extend({"concept_id": concept_id, **issue} for issue in concept_issues)
        else:
            introduced.add(concept_id)

    report = {
        "status": "ok" if not issues else "failed",
        "contract_count": len(MIT_18_703_CONCEPT_PREREQUISITES),
        "checks": checks,
        "issues": issues,
    }
    if issues:
        details = "; ".join(
            f"{issue['concept_id']}: {issue['kind']}={','.join(issue['values'])}"
            for issue in issues
        )
        raise RuntimeError("MIT 18.703 prerequisite concept contract failed: " + details)
    return report


def mit_18_703_restore_inline_math(text: object) -> str:
    """Restore inline delimiters around structured MIT payload math markers."""
    source = str(text)

    def math_like(content: str) -> bool:
        value = content.strip()
        if not value or " " in value and not re.search(r"[\\=<>^_|{}+*/]", value):
            return False
        return bool(
            re.search(r"[\\=<>^_|{}+*/]", value)
            or re.fullmatch(r"-?\d+", value)
            or re.fullmatch(r"[A-Za-z](?:_[A-Za-z0-9{}]+|\^[A-Za-z0-9{}]+)?", value)
            or re.fullmatch(r"[A-Za-z]{2,3}", value)
            or re.fullmatch(r"[A-Za-z](?:_[A-Za-z0-9{}]+)?\([^()]+\)", value)
            or re.fullmatch(r"\[[A-Za-z0-9:]+\]", value)
            or re.fullmatch(r"[A-Za-z0-9]+(?:\s*[,/]\s*[A-Za-z0-9]+)+", value)
            or re.fullmatch(r"[A-Za-z]+\[[A-Za-z]+\]", value)
        )

    def restore(segment: str) -> str:
        rendered: list[str] = []
        index = 0
        while index < len(segment):
            protected_closer = None
            if segment.startswith(r"\(", index):
                protected_closer = r"\)"
            elif segment.startswith(r"\[", index):
                protected_closer = r"\]"
            if protected_closer:
                closing = segment.find(protected_closer, index + 2)
                if closing < 0:
                    rendered.append(segment[index:])
                    break
                rendered.append(segment[index : closing + 2])
                index = closing + 2
                continue
            if segment[index] != "(":
                rendered.append(segment[index])
                index += 1
                continue

            depth = 1
            cursor = index + 1
            content_end: int | None = None
            closing = cursor
            while cursor < len(segment):
                if segment.startswith(r"\)", cursor):
                    depth -= 1
                    if depth == 0:
                        content_end = cursor
                        closing = cursor + 2
                        break
                    cursor += 2
                    continue
                if segment[cursor] == "(" and (cursor == 0 or segment[cursor - 1] != "\\"):
                    depth += 1
                elif segment[cursor] == ")" and (cursor == 0 or segment[cursor - 1] != "\\"):
                    depth -= 1
                    if depth == 0:
                        content_end = cursor
                        closing = cursor + 1
                        break
                cursor += 1
            if content_end is None:
                rendered.append(segment[index:])
                break

            content = segment[index + 1 : content_end]
            if math_like(content):
                rendered.append(r"\(" + content + r"\)")
            else:
                rendered.append("(" + restore(content) + ")")
            index = closing
        return "".join(rendered)

    return restore(source)


def mit_18_703_normalize_math_nodes(value: object) -> object:
    if isinstance(value, str):
        return mit_18_703_restore_inline_math(value)
    if isinstance(value, list):
        return [mit_18_703_normalize_math_nodes(item) for item in value]
    if isinstance(value, dict):
        return {
            key: item if key in {"symbol", "math"} and isinstance(item, str)
            else mit_18_703_normalize_math_nodes(item)
            for key, item in value.items()
        }
    return value


def mit_18_703_bind_result_proofs(lecture_number: int, payload: dict[str, object]) -> None:
    results = payload.get("results") if isinstance(payload.get("results"), list) else []
    semantic_ids = MIT_18_703_RESULT_IDS.get(lecture_number, {})
    result_by_id: dict[str, dict[str, object]] = {}
    result_names: set[str] = set()
    for result in results:
        if not isinstance(result, dict):
            continue
        name = str(result.get("name", "")).strip()
        result_id = semantic_ids.get(name)
        if not name or name in result_names:
            raise RuntimeError(f"MIT 18.703 unit {lecture_number} has a missing or duplicate result title: {name!r}")
        if not result_id:
            raise RuntimeError(f"MIT 18.703 unit {lecture_number} result {name!r} has no stable semantic ID")
        if result_id in result_by_id:
            raise RuntimeError(f"MIT 18.703 unit {lecture_number} has duplicate semantic result ID {result_id!r}")
        result["id"] = result_id
        result_by_id[result_id] = result
        result_names.add(name)

    unused_ids = sorted(set(semantic_ids) - result_names)
    if unused_ids:
        raise RuntimeError(
            f"MIT 18.703 unit {lecture_number} semantic IDs target absent results: {unused_ids}"
        )

    bindings = MIT_18_703_PROOF_BINDINGS.get(lecture_number, [])
    proofs: list[dict[str, object]] = []
    seen_targets: set[str] = set()
    for binding in bindings:
        result_name = str(binding.get("result", ""))
        result_id = semantic_ids.get(result_name)
        result = result_by_id.get(result_id or "")
        if result is None or result_id is None:
            raise RuntimeError(f"MIT 18.703 unit {lecture_number} proof targets unknown result {result_name!r}")
        if result_id in seen_targets:
            raise RuntimeError(f"MIT 18.703 unit {lecture_number} has duplicate proof target {result_id!r}")
        source = str(binding.get("source", ""))
        if source == "development":
            body = str(payload.get("development", ""))
        elif source == "companion":
            body = str(payload.get("companion_development", ""))
        else:
            body = mit_18_703_restore_inline_math(binding.get("body", ""))
        if not body.strip():
            raise RuntimeError(f"MIT 18.703 unit {lecture_number} proof for {result_name!r} is empty")
        body_tokens = set(notes_contract_tokens(body))
        missing_terms = [
            str(term) for term in binding.get("required_terms", [])
            if not set(notes_contract_tokens(term)).issubset(body_tokens)
        ]
        if missing_terms:
            raise RuntimeError(
                f"MIT 18.703 unit {lecture_number} proof for {result_name!r} misses semantic anchors: "
                + ", ".join(missing_terms)
            )
        claim_report = mit_18_703_validate_result_claim(result_id, result.get("statement", ""), body)
        if claim_report["status"] != "ok":
            raise RuntimeError(
                f"MIT 18.703 unit {lecture_number} proof for {result_id!r} violates its "
                f"hypothesis/conclusion contract: {claim_report['issues']}"
            )
        proofs.append({
            "result_id": result_id,
            "body": body,
            "kind": str(binding.get("kind", "proof")),
            "semantic_anchors": list(binding.get("required_terms", [])),
            "claim_contract": claim_report,
        })
        seen_targets.add(result_id)

    expected_targets = set(result_by_id)
    if seen_targets != expected_targets:
        missing = sorted(expected_targets - seen_targets)
        extra = sorted(seen_targets - expected_targets)
        raise RuntimeError(
            f"MIT 18.703 unit {lecture_number} proof coverage mismatch; missing={missing}, extra={extra}"
        )
    payload["proofs"] = proofs


def mit_18_703_validate_topic_framing() -> None:
    expected_titles = set(MIT_18_703_CALENDAR_ORDER)
    actual_titles = set(MIT_18_703_TOPIC_FRAMING)
    if actual_titles != expected_titles:
        missing = sorted(expected_titles - actual_titles)
        extra = sorted(actual_titles - expected_titles)
        raise RuntimeError(f"MIT 18.703 topic framing mismatch; missing={missing}, extra={extra}")
    required_fields = {"hook", "formula", "prerequisites", "misconception", "question", "answer"}
    for title in MIT_18_703_CALENDAR_ORDER:
        framing = MIT_18_703_TOPIC_FRAMING[title]
        missing_fields = sorted(
            field for field in required_fields
            if not framing.get(field)
        )
        prerequisites = framing.get("prerequisites")
        if missing_fields or not isinstance(prerequisites, (list, tuple)):
            raise RuntimeError(
                f"MIT 18.703 topic framing for {title!r} is incomplete; missing={missing_fields}"
            )
    reused_titles = set(MIT_18_703_ALIGNED_EXAMPLE_SOURCES)
    bespoke_titles = set(MIT_18_703_TOPIC_SUPPLEMENTAL_EXAMPLES)
    if reused_titles & bespoke_titles or reused_titles | bespoke_titles != expected_titles:
        raise RuntimeError(
            "MIT 18.703 supplemental examples must assign every calendar title "
            "to exactly one explicit source"
        )


def mit_18_703_supplemental_example(title: str) -> dict[str, object]:
    bespoke = MIT_18_703_TOPIC_SUPPLEMENTAL_EXAMPLES.get(title)
    if bespoke is not None:
        return json.loads(json.dumps(bespoke))
    source_name = MIT_18_703_ALIGNED_EXAMPLE_SOURCES.get(title)
    concept_library = {concept.name.lower(): concept for concept in GROUP_THEORY}
    source = concept_library.get(str(source_name))
    if source is None:
        raise RuntimeError(f"MIT 18.703 topic {title!r} has no validated supplemental example source")
    return {
        "kind": "example",
        "title": f"Introductory case for {title}",
        "setup": source.example_setup,
        "calculation": source.example_calc,
        "takeaway": source.example_takeaway,
        "trusted_tex": False,
    }


def mit_18_703_note_shorts(pack: dict[str, object]) -> list[dict[str, object]]:
    if tuple(str(spec["title"]) for spec in MIT_18_703_NOTE_SEQUENCE) != MIT_18_703_CALENDAR_ORDER:
        raise RuntimeError("MIT 18.703 notes sequence must match the official Calendar order")
    mit_18_703_validate_topic_framing()
    shorts: list[dict[str, object]] = []
    for lecture_number, spec in enumerate(MIT_18_703_NOTE_SEQUENCE, start=1):
        title = str(spec["title"])
        depth_key = str(spec["depth"])
        source_payload = MIT_18_703_CUSTOM_NOTE_DEPTH.get(depth_key) or GROUP_THEORY_NOTE_DEPTH[depth_key]
        normalized_payload = mit_18_703_normalize_math_nodes(json.loads(json.dumps(source_payload)))
        if not isinstance(normalized_payload, dict):
            raise RuntimeError(f"MIT 18.703 unit {lecture_number} note payload is not an object")
        payload = normalized_payload
        payload.update({
            "content_basis": "curated-mit-18.703",
            "trusted_tex": True,
            "calendar_unit": lecture_number,
            "source_lecture": lecture_number if lecture_number <= 23 else None,
            "source_material_scope": [f"lecture-{lecture_number}"] if lecture_number <= 23 else ["calendar-review"],
        })
        companion = GROUP_THEORY_COMPANION_DEVELOPMENTS.get(depth_key)
        if companion:
            payload["companion_development"] = companion
        if lecture_number == 7:
            payload["results"].append({
                "id": "cayley-s-theorem",
                "name": "Cayley's theorem",
                "statement": r"Every group is isomorphic to a subgroup of \(\operatorname{Sym}(G)\) through left translation.",
            })
        elif lecture_number == 8:
            payload["results"].append({
                "id": "kernel-and-image-theorem",
                "name": "Kernel and image theorem",
                "statement": r"The kernel is normal, the image is a subgroup, and \(\varphi\) is injective exactly when \(\ker\varphi=\{e\}\).",
            })
        elif lecture_number == 13:
            payload["development_title"] = "Counting Sylow subgroups by group actions"
            payload["development"] = r"Let \(P\) be a Sylow \(p\)-subgroup. Conjugation makes \(G\) act transitively on the Sylow \(p\)-subgroups, so orbit-stabilizer gives \(n_p=[G:N_G(P)]\). Since \(P\leq N_G(P)\), this index divides the prime-to-\(p\) factor \(m\). Restrict the action to \(P\): every orbit has prime-power size, \(P\) itself is fixed, and every nontrivial orbit contributes a multiple of \(p\), hence \(n_p\equiv1\pmod p\). Existence follows by the standard left-translation action on suitable \(p^k\)-element subsets: an orbit whose size is not divisible by \(p\) has a stabilizer containing the full \(p^k\)-part. Together these arguments give existence, conjugacy, divisibility, and congruence."
        mit_18_703_bind_result_proofs(lecture_number, payload)
        examples = payload.get("examples") if isinstance(payload.get("examples"), list) else []
        primary_example = examples[0] if examples and isinstance(examples[0], dict) else None
        if primary_example is None:
            raise RuntimeError(f"MIT 18.703 topic {title!r} has no topic-specific worked example")
        framing = MIT_18_703_TOPIC_FRAMING[title]
        concept = Concept(
            title,
            str(framing["hook"]),
            str(payload.get("definition", "")),
            str(framing["formula"]),
            [str(item) for item in framing["prerequisites"]],
            str(framing["misconception"]),
            str(primary_example.get("setup", "")),
            str(primary_example.get("calculation", "")),
            str(primary_example.get("takeaway", "")),
            str(framing["question"]),
            str(framing["answer"]),
            str(spec["visual"]),
        )
        short = concept_to_short(concept, lecture_number)
        if spec.get("title_parts"):
            short["concept_heading"] = {"parts": spec["title_parts"]}
        payload["topic_framing_basis"] = "exact-calendar-title"
        payload["examples"] = [mit_18_703_supplemental_example(title), *examples]
        payload["examples_complete"] = True
        if lecture_number in MIT_18_703_FIGURE_COPY:
            caption, discussion = MIT_18_703_FIGURE_COPY[lecture_number]
            payload.update({
                "figure": True,
                "figure_caption": caption,
                "figure_discussion": discussion,
                "figure_label": f"fig:mit-18-703-{lecture_number:02d}",
            })
        else:
            payload["figure"] = False
        if lecture_number in MIT_18_703_ALGORITHMS:
            payload["algorithms"] = [MIT_18_703_ALGORITHMS[lecture_number]]
        if lecture_number == 24:
            payload.setdefault("properties", []).extend([
                r"A quotient argument begins with an equivalence relation that respects the operation. For groups this is supplied by a normal subgroup; for rings it is supplied by an ideal. The parallel notation does not make the hypotheses interchangeable.",
                r"A quotient identifies elements in the same kernel fiber. The first isomorphism theorem then describes exactly what information survives: the quotient is isomorphic to the image, not automatically to the whole codomain.",
                r"A structural conclusion should be read back through the quotient. If \(R/I\) is a domain then \(I\) is prime; if \(R/I\) is a field then \(I\) is maximal. The stronger field conclusion therefore implies the domain conclusion.",
            ])
            payload["algorithms"] = [{
                "name": "Selecting a proof architecture",
                "steps": [
                    r"Name the ambient object and operation first. Record whether the hypotheses concern a finite group, a homomorphism, a normal subgroup, a ring, an ideal, or a Euclidean function; this prevents importing a theorem from the wrong category.",
                    r"For a finite group, factor \(|G|\) before guessing its structure. Apply Lagrange to element and subgroup orders, then apply the Sylow divisibility and congruence conditions to determine which Sylow subgroups must be unique and hence normal.",
                    r"When a map is present, verify preservation of the operation and compute its kernel and image explicitly. Use injectivity only when the kernel is trivial, surjectivity only when the image is the full codomain, and the first isomorphism theorem for the quotient that remains.",
                    r"Before multiplying cosets, prove the quotient operation is well defined. In the group case this means checking normality; in the ring case this means checking additive closure and absorption by arbitrary ring elements.",
                    r"For ideals, translate the desired property into a quotient test. Prove \(R/I\) has no zero divisors to establish primality, or prove every nonzero class is invertible to establish maximality.",
                    r"In a Euclidean domain, use division with remainder to force a strictly decreasing Euclidean value. Termination gives a greatest common divisor; back substitution gives a linear combination; the PID and UFD consequences may then be invoked in that order.",
                    r"For polynomials over a field, compare leading terms before subtracting. Degree descent proves termination of division, evaluation maps identify ideals such as \((x-a)\), and quotient tests convert those computations into structural statements.",
                    r"Finish with a boundary check. Identify the exact hypothesis used at each implication and test what fails without it: a nonnormal subgroup, a nonabsorbing additive subgroup, a reducible polynomial, or a quotient that is a domain but not a field.",
                ],
            }]
            payload.setdefault("examples", []).extend([
                {
                    "kind": "example",
                    "title": r"Evaluation, kernel, and quotient type",
                    "setup": r"Let \(\operatorname{ev}_0:\mathbb{Z}[x]\to\mathbb{Z}\) send a polynomial to its constant term. Determine the kernel and decide whether it is prime or maximal.",
                    "calculation": r"Evaluation preserves addition and multiplication, and its image is all of \(\mathbb{Z}\). A polynomial evaluates to zero exactly when its constant term vanishes, so \(\ker(\operatorname{ev}_0)=(x)\). The first isomorphism theorem gives \(\mathbb{Z}[x]/(x)\cong\mathbb{Z}\). Since \(\mathbb{Z}\) is an integral domain, \((x)\) is prime. Since \(\mathbb{Z}\) is not a field, \((x)\) is not maximal.",
                    "takeaway": r"One explicit homomorphism connects kernel computation, quotient construction, and the distinction between prime and maximal ideals.",
                    "trusted_tex": True,
                },
                {
                    "kind": "counterexample",
                    "title": r"Why normality cannot be skipped",
                    "setup": r"In \(S_3\), let \(H=\langle(12)\rangle\). The left cosets still partition the group, but test whether multiplying those left cosets gives a quotient group.",
                    "calculation": r"Conjugating \((12)\) by \((123)\) gives \((23)\notin H\), so \(H\) is not normal. Consequently a product written using one pair of representatives can land in a different left coset when the representatives are changed.",
                    "takeaway": r"Equal-sized coset blocks are enough for Lagrange counting, but normality is the additional condition that makes coset multiplication independent of representatives.",
                    "trusted_tex": True,
                },
            ])
        if lecture_number in MIT_18_703_LECTURE_EXTENSIONS:
            payload["extensions"] = MIT_18_703_LECTURE_EXTENSIONS[lecture_number]
        short["note_depth"] = payload
        shorts.append(short)
    semantic_ids = [
        str(result.get("id"))
        for short in shorts
        for result in short.get("note_depth", {}).get("results", [])
        if isinstance(result, dict)
    ]
    if len(semantic_ids) != len(set(semantic_ids)):
        duplicates = sorted({result_id for result_id in semantic_ids if semantic_ids.count(result_id) > 1})
        raise RuntimeError(f"MIT 18.703 semantic result IDs must be globally unique: {duplicates}")
    prerequisite_report = mit_18_703_validate_concept_prerequisites(shorts)
    for short in shorts:
        payload = short.get("note_depth") if isinstance(short.get("note_depth"), dict) else {}
        payload["prerequisite_contract_status"] = prerequisite_report["status"]
    for index, short in enumerate(shorts):
        enrich_short(short, shorts, index)
    return shorts


def note_concept_with_name(concept: Concept, name: str) -> Concept:
    """Keep an authoritative outline label without changing its resolved model."""
    return Concept(
        name,
        concept.hook,
        concept.intuition,
        concept.formula,
        list(concept.prerequisites),
        concept.misconception,
        concept.example_setup,
        concept.example_calc,
        concept.example_takeaway,
        concept.application_question,
        concept.application_answer,
        concept.visual_type,
    )


def note_term_signature(value: str) -> set[str]:
    return {
        word[:-1] if word.endswith("s") and len(word) > 4 else word
        for word in re.findall(r"[a-z0-9]+", value.lower())
        if word not in SOURCE_TERM_CONNECTORS | {"part", "lecture", "unit"}
    }


def planned_note_concept(item: dict[str, object], name: str | None = None) -> Concept | None:
    worked = item.get("worked_example") if isinstance(item.get("worked_example"), dict) else {}
    question = item.get("question_prompt") if isinstance(item.get("question_prompt"), dict) else {}
    text = " ".join(
        str(value).lower()
        for value in (
            item.get("hook", ""),
            item.get("intuition", ""),
            worked.get("setup", ""),
            worked.get("calculation", ""),
            worked.get("takeaway", ""),
        )
    )
    if any(
        marker in text
        for marker in (
            "is a core idea in this course",
            "by connecting definition, formula, and example",
            "as an input-output test",
            "making the definition testable on concrete inputs",
        )
    ):
        return None
    concept_name = str(name or item.get("concept", "")).strip()
    if not concept_name:
        return None
    return Concept(
        concept_name,
        str(item.get("hook", "")).strip(),
        str(item.get("intuition", "")).strip(),
        str(item.get("formula", item.get("plain_formula", ""))).strip(),
        [str(value) for value in item.get("prerequisites", []) if str(value).strip()],
        str(item.get("misconception", "")).strip(),
        str(worked.get("setup", "")).strip(),
        str(worked.get("calculation", "")).strip(),
        str(worked.get("takeaway", "")).strip(),
        str(question.get("question", "")).strip(),
        str(question.get("answer", "")).strip(),
        str(item.get("visual_type", "numeric_rule")).strip() or "numeric_rule",
    )


def resolve_authoritative_note_concept(
    topic: str,
    domain: str | None,
    planned_items: list[dict[str, object]],
) -> tuple[Concept, str | None]:
    """Resolve an outline unit for notes without depending on video-route support."""
    topic_signature = note_term_signature(topic)
    if domain in {"physics", "economics"}:
        try:
            return note_concept_with_name(source_term_concept(topic, domain), topic), None
        except (KeyError, ValueError) as exc:
            model_resolution_error = str(exc)
    else:
        model_resolution_error = ""
    for item in planned_items:
        item_signature = note_term_signature(str(item.get("concept", "")))
        if topic_signature and topic_signature == item_signature:
            concept = planned_note_concept(item, topic)
            if concept is not None:
                return concept, None

    library_matches: list[tuple[float, Concept]] = []
    for concept in DOMAIN_LIBRARY.get(domain or "", []):
        candidate_signature = note_term_signature(concept.name)
        if not topic_signature or not candidate_signature:
            continue
        score = len(topic_signature & candidate_signature) / len(topic_signature | candidate_signature)
        library_matches.append((score, concept))
    if library_matches:
        score, concept = max(library_matches, key=lambda row: row[0])
        if score >= 0.8:
            return note_concept_with_name(concept, topic), None

    try:
        resolved = source_term_concept(topic, domain)
    except (KeyError, ValueError) as exc:
        resolved = None
        resolution_error = str(exc)
    else:
        resolution_error = ""
    if resolved is not None and (
        resolved.visual_type != "numeric_rule"
        or domain in {"algorithms", "group_theory", "calculus", "probability"}
    ):
        return note_concept_with_name(resolved, topic), None

    placeholder = Concept(
        topic,
        f"{topic} appears in the authoritative course outline but has no registered notes model.",
        "The source material must supply a definition, governing relation, worked case, and figure before publication.",
        "",
        [],
        "Do not invent a generic formula or silently omit an authoritative course unit.",
        "Locate the course's own definition and example for this unit.",
        "Bind every numerical or symbolic claim to that source evidence.",
        "Publication remains blocked until the topic-specific development is registered.",
        f"What exact model or theorem governs {topic}?",
        "The authoritative materials must answer this before the notes can be generated.",
        "numeric_rule",
    )
    detail = (
        model_resolution_error
        or resolution_error
        or "no topic-specific notes model, plan payload, or domain-library entry matched"
    )
    return placeholder, f"Unsupported authoritative notes topic {topic!r} for domain {domain or 'unknown'!r}: {detail}."


def full_note_shorts(pack: dict[str, object], plan: dict[str, object]) -> list[dict[str, object]]:
    if is_mit_18_703_pack(pack):
        return mit_18_703_note_shorts(pack)
    domain = detected_domain(pack, plan)
    person_names, person_tokens = source_person_name_data(source_text(pack))
    planned_items = [
        item for item in plan.get("shorts", [])
        if isinstance(item, dict)
        and is_course_vocabulary_term(str(item.get("concept", "")))
        and not is_person_name_term(str(item.get("concept", "")), person_names, person_tokens)
    ]
    planned_names = {re.sub(r"\s+", " ", str(item.get("concept", "")).lower()).strip() for item in planned_items}
    prerequisite_names = {
        re.sub(r"\s+", " ", str(prerequisite).lower()).strip()
        for item in planned_items
        for prerequisite in item.get("prerequisites", [])
        if str(prerequisite).strip()
    }

    def planned_or_prerequisite(name: str) -> bool:
        normalized = re.sub(r"\s+", " ", name.lower()).strip()
        if any(normalized in planned or planned in normalized for planned in planned_names):
            return True
        meaningful = {word for word in normalized.split() if word not in SOURCE_TERM_CONNECTORS}
        return any(
            prerequisite in normalized
            or normalized in prerequisite
            or bool(meaningful & set(prerequisite.split())) and len(meaningful) == 1
            for prerequisite in prerequisite_names
        )

    concepts: list[Concept] = []
    existing: set[str] = set()

    def add_note_concept(concept: Concept) -> None:
        normalized = re.sub(r"[^a-z0-9]+", " ", concept.name.lower()).strip()
        signature = {
            word[:-1] if word.endswith("s") and len(word) > 4 else word
            for word in normalized.split()
            if word not in SOURCE_TERM_CONNECTORS
        }
        for existing_name in existing:
            existing_signature = {
                word[:-1] if word.endswith("s") and len(word) > 4 else word
                for word in re.sub(r"[^a-z0-9]+", " ", existing_name).split()
                if word not in SOURCE_TERM_CONNECTORS
            }
            if signature and signature == existing_signature:
                return
        concepts.append(concept)
        existing.add(normalized)

    outline_topics = source_outline_topics(pack)
    authoritative_outline = len(outline_topics) >= 8
    if authoritative_outline:
        source_materials = normalized_source_materials(pack)
        shorts: list[dict[str, object]] = []
        for index, outline_topic in enumerate(outline_topics, start=1):
            concept, resolution_error = resolve_authoritative_note_concept(
                outline_topic,
                domain,
                planned_items,
            )
            short = concept_to_short(concept, index)
            short["concept"] = outline_topic
            short["authoritative_outline_topic"] = outline_topic
            short["notes_resolution_status"] = "failed" if resolution_error else "ok"
            if resolution_error:
                short["notes_resolution_error"] = resolution_error
            evidence = source_evidence_for_term(
                pack,
                outline_topic,
                materials=source_materials,
                person_names=person_names,
            )
            if evidence:
                short["source_evidence"] = evidence
            shorts.append(short)
        for index, short in enumerate(shorts):
            enrich_short(short, shorts, index)
        return shorts

    for outline_topic in outline_topics:
        try:
            add_note_concept(source_term_concept(outline_topic, domain))
        except ValueError:
            continue
    for concept in (() if authoritative_outline else DOMAIN_LIBRARY.get(domain or "", [])):
        if planned_or_prerequisite(concept.name) or source_evidences_term(pack, concept.name):
            add_note_concept(concept)
    for item in ([] if authoritative_outline else planned_items):
        name = str(item.get("concept", "")).strip()
        normalized_name = re.sub(r"[^a-z0-9]+", " ", name.lower()).strip()
        if not name or normalized_name in existing:
            continue
        worked_example = item.get("worked_example", {}) if isinstance(item.get("worked_example"), dict) else {}
        question_prompt = item.get("question_prompt", {}) if isinstance(item.get("question_prompt"), dict) else {}
        generated_text = " ".join(
            str(value).lower()
            for value in (
                item.get("hook", ""), item.get("intuition", ""), worked_example.get("setup", ""),
                worked_example.get("calculation", ""), worked_example.get("takeaway", ""),
            )
        )
        template_generated = any(
            marker in generated_text
            for marker in (
                "is a core idea in this course", "by connecting definition, formula, and example",
                "as an input-output test", "making the definition testable on concrete inputs",
            )
        )
        if template_generated:
            continue
        add_note_concept(Concept(
            name,
            str(item.get("hook", "This is a core course idea.")),
            str(item.get("intuition", "Connect the definition, formula, and worked example.")),
            str(item.get("formula", item.get("plain_formula", ""))),
            [str(x) for x in item.get("prerequisites", [])],
            str(item.get("misconception", "Do not memorize without checking a concrete example.")),
            str(worked_example.get("setup", "Choose a small representative example.")),
            str(worked_example.get("calculation", "Work through the definition step by step.")),
            str(worked_example.get("takeaway", "The calculation should reveal the structure.")),
            str(question_prompt.get("question", "Where does this appear in the course?")),
            str(question_prompt.get("answer", "Identify the inputs, rule, and output.")),
            str(item.get("visual_type", "numeric_rule")),
        ))
    if not concepts:
        concepts = [
            concept for concept in choose_concepts(pack, max(1, len(planned_items)))
            if source_evidences_term(pack, concept.name) or planned_or_prerequisite(concept.name)
        ]
    shorts = [concept_to_short(concept, i) for i, concept in enumerate(concepts, start=1)]
    source_materials = normalized_source_materials(pack)
    for i, short in enumerate(shorts):
        enrich_short(short, shorts, i)
        evidence = source_evidence_for_term(
            pack, str(short["concept"]), materials=source_materials, person_names=person_names,
        )
        if evidence:
            short["source_evidence"] = evidence
    return shorts


NOTES_UNICODE_INLINE_MATH = {
    "φ": r"\varphi",
    "ψ": r"\psi",
    "α": r"\alpha",
    "β": r"\beta",
    "γ": r"\gamma",
    "λ": r"\lambda",
    "σ": r"\sigma",
    "Σ": r"\Sigma",
    "∈": r"\in",
    "∉": r"\notin",
    "⊂": r"\subset",
    "⊆": r"\subseteq",
    "≤": r"\leq",
    "≥": r"\geq",
    "≠": r"\neq",
    "→": r"\to",
    "←": r"\leftarrow",
    "↦": r"\mapsto",
    "⇒": r"\Rightarrow",
    "≅": r"\cong",
    "≃": r"\simeq",
    "∼": r"\sim",
    "×": r"\times",
    "·": r"\cdot",
    "\u03b4": r"\delta",
    "\u0394": r"\Delta",
    "\u03b8": r"\theta",
    "\u03bc": r"\mu",
    "\u03c0": r"\pi",
    "\u03c1": r"\rho",
    "\u03c4": r"\tau",
    "\u03c9": r"\omega",
    "\u03a9": r"\Omega",
    "\u0398": r"\Theta",
    "\u03b5": r"\varepsilon",
    "\u221e": r"\infty",
    "\u2211": r"\sum",
    "\u220f": r"\prod",
    "\u2202": r"\partial",
    "\u00b1": r"\pm",
    "\u2248": r"\approx",
    "\u2200": r"\forall",
    "\u2203": r"\exists",
    "\u226a": r"\ll",
    "\u226b": r"\gg",
}


def notes_restore_unicode_scripts(text: str) -> str:
    work = str(text)
    for mapping, marker in (
        (FORMULA_UNICODE_SUBSCRIPT, "_"),
        (FORMULA_UNICODE_SUPERSCRIPT, "^"),
    ):
        reverse = {rendered: source for source, rendered in mapping.items()}
        pattern = re.compile("[" + re.escape("".join(reverse)) + "]+")
        work = pattern.sub(
            lambda match: marker + "{" + "".join(reverse[character] for character in match.group(0)) + "}",
            work,
        )
    return work


def notes_clean_source_prose(text: str) -> str:
    work = notes_restore_unicode_scripts(str(text))
    for source, replacement in {
        "ﬁ": "fi", "ﬂ": "fl", "ﬀ": "ff", "ﬃ": "ffi", "ﬄ": "ffl",
        "−": "-", "–": "-", "—": "-", "≤": "<=", "≥": ">=", "‘": "'", "’": "'",
        "“": '"', "”": '"', "…": "...", " ": " ", "\u00ad": "", "\u2022": ". ",
    }.items():
        work = work.replace(source, replacement)
    work = "".join(
        character
        for character in work
        if character in "\n\t" or unicodedata.category(character)[0] != "C"
    )
    kept: list[str] = []
    for line in work.splitlines():
        stripped = re.sub(r"\s+", " ", line).strip()
        if not stripped or re.fullmatch(r"\d+", stripped):
            continue
        lowered = stripped.lower()
        if any(marker in lowered for marker in (
            "mit ocw:", "prof. james", "massachusetts institute", "open courseware",
            "browse course material", "download course", "give now", "terms and conditions",
        )):
            continue
        kept.append(stripped)
    work = " ".join(kept)
    work = re.sub(r"https?://\S+", " ", work)
    work = re.sub(r"([,;:])(?=\S)", r"\1 ", work)
    work = re.sub(r"\s*\+\s*", " + ", work)
    work = re.sub(r"(?<![<>=!])\s*=\s*(?![=>])", " = ", work)
    work = re.sub(r"\b(?:Definition|Theorem|Lemma|Proposition)\s+(\d+(?:\.\d+)*)\.?", lambda m: m.group(0), work)
    return re.sub(r"\s+", " ", work).strip()


def notes_scaffold_prose(value: object) -> str:
    """Clean note prose without applying narration-only, lossy math rewrites."""
    return notes_clean_source_prose(str(value))


NOTES_GROWTH_OPERATOR_RE = re.compile(
    r"(?<![A-Za-z])(?P<operator>\\Theta|\\Omega|Theta|Omega|O|\u0398|\u03a9)\s*"
    r"\((?P<body>[^()]*(?:\([^()]*\)[^()]*)*)\)"
)


def notes_growth_latex(operator: str, body: str) -> str:
    rendered_operator = {
        "Theta": r"\Theta", "\u0398": r"\Theta", r"\Theta": r"\Theta",
        "Omega": r"\Omega", "\u03a9": r"\Omega", r"\Omega": r"\Omega",
        "O": "O",
    }[operator]
    normalized_body = re.sub(r"\blog_?2\b", lambda _match: r"\log_2", body)
    normalized_body = re.sub(r"(?<!\\)\blog\b", lambda _match: r"\log", normalized_body)
    if "\\" in normalized_body:
        rendered_body = normalized_body.strip()
    else:
        rendered_body = latex_math_expr(normalized_body)
    return rendered_operator + "(" + rendered_body + ")"


def notes_stash_source_inline_math(
    text: str,
    store: Callable[[str], str],
    *,
    normalize_plain: bool = True,
) -> str:
    """Collapse source LaTeX delimiters and stash each expression exactly once."""
    work = str(text)
    fragmented_growth = re.compile(
        r"\\\(\s*(\\Theta|\\Omega|Theta|Omega|O|\u0398|\u03a9)\s*\\\)\s*(?=\()"
    )
    while fragmented_growth.search(work):
        work = fragmented_growth.sub(lambda match: match.group(1), work)

    rendered: list[str] = []
    cursor = 0
    while True:
        start = work.find(r"\(", cursor)
        if start < 0:
            rendered.append(work[cursor:])
            break
        rendered.append(work[cursor:start])
        depth = 1
        scan = start + 2
        core_parts: list[str] = []
        while scan < len(work) and depth:
            marker = work[scan:scan + 2]
            if marker == r"\(":
                depth += 1
                scan += 2
            elif marker == r"\)":
                depth -= 1
                scan += 2
            else:
                core_parts.append(work[scan])
                scan += 1
        if depth:
            rendered.append(work[start:])
            break
        core = "".join(core_parts).strip()
        growth = NOTES_GROWTH_OPERATOR_RE.fullmatch(core)
        if growth:
            normalized = notes_growth_latex(growth.group("operator"), growth.group("body"))
        elif "\\" in core:
            normalized = core
        else:
            normalized = latex_math_expr(core) if normalize_plain else core
        rendered.append(store(normalized))
        cursor = scan
    return "".join(rendered)


def notes_math_core_latex(core: str) -> str:
    """Normalize a delimited math body without sending it through text escaping."""
    normalized = notes_restore_unicode_scripts(str(core).strip())
    for symbol, latex in NOTES_UNICODE_INLINE_MATH.items():
        normalized = normalized.replace(symbol, latex)
    normalized = notes_collapse_nested_inline_math(normalized)
    normalized = normalized.replace(r"\(", "").replace(r"\)", "")
    return normalized if "\\" in normalized else latex_math_expr(normalized)


def notes_trusted_math_core(core: str) -> str:
    """Preserve curated TeX math while normalizing only extracted Unicode glyphs."""
    normalized = notes_restore_unicode_scripts(str(core).strip())
    for symbol, latex in NOTES_UNICODE_INLINE_MATH.items():
        normalized = normalized.replace(symbol, latex)
    normalized = notes_collapse_nested_inline_math(normalized)
    return normalized.replace(r"\(", "").replace(r"\)", "")


def notes_stash_source_math(
    text: str,
    store_inline: Callable[[str], str],
    store_display: Callable[[str], str],
    *,
    normalize_core: Callable[[str], str] = notes_math_core_latex,
    normalize_plain: bool = True,
) -> str:
    """Stash TeX and dollar-delimited math before prose and list processing."""
    work = str(text)
    display_pattern = re.compile(r"\\\[(.*?)\\\]", re.S)
    dollar_display_pattern = re.compile(r"(?<!\\)\$\$(.*?)(?<!\\)\$\$", re.S)
    dollar_inline_pattern = re.compile(r"(?<![\\$])\$(?!\$)(.*?)(?<!\\)\$(?!\$)", re.S)
    work = display_pattern.sub(
        lambda match: store_display(normalize_core(match.group(1))),
        work,
    )
    work = dollar_display_pattern.sub(
        lambda match: store_display(normalize_core(match.group(1))),
        work,
    )
    work = dollar_inline_pattern.sub(
        lambda match: store_inline(normalize_core(match.group(1))),
        work,
    )
    return notes_stash_source_inline_math(
        work,
        lambda core: store_inline(normalize_core(core)),
        normalize_plain=normalize_plain,
    )


def notes_structured_list_latex(source: str) -> str | None:
    """Render a Python-style nested list as one mathematical matrix value."""
    try:
        value = ast.literal_eval(source)
    except (SyntaxError, ValueError):
        return None
    if not isinstance(value, list) or not value or not any(isinstance(item, list) for item in value):
        return None
    nested = [item for item in value if isinstance(item, list)]
    rectangular = (
        len(nested) == len(value)
        and bool(nested[0])
        and all(len(row) == len(nested[0]) for row in nested)
    )
    if rectangular:
        rows = [[str(cell) for cell in row] for row in nested]
    else:
        cells: list[str] = []
        for item in value:
            if not isinstance(item, list):
                cells.append(str(item))
            elif not item:
                cells.append(r"\varnothing")
            else:
                rendered = ", ".join(latex_math_expr(str(cell)) for cell in item)
                cells.append(r"\{" + rendered + r"\}")
        rows = [cells]
    rendered_rows = [
        " & ".join(
            cell if cell.startswith((r"\varnothing", r"\{")) else latex_math_expr(cell)
            for cell in row
        )
        for row in rows
    ]
    return r"\begin{bmatrix}" + r" \\ ".join(rendered_rows) + r"\end{bmatrix}"


def notes_stash_structured_lists(text: str, store: Callable[[str], str]) -> str:
    """Replace matrix and bucket literals before any brackets can be escaped."""
    structured_list_pattern = r"\[(?:[^\[\]]|\[[^\[\]]*\])*\]"

    def structured_assignment_repl(match: re.Match[str]) -> str:
        matrix = notes_structured_list_latex(match.group(2))
        if matrix is None:
            return match.group(0)
        return store(latex_math_expr(match.group(1)) + " = " + matrix)

    def structured_list_repl(match: re.Match[str]) -> str:
        matrix = notes_structured_list_latex(match.group(0))
        return store(matrix) if matrix is not None else match.group(0)

    work = re.sub(
        rf"\b([A-Za-z][A-Za-z0-9_]*)\s*=\s*({structured_list_pattern})",
        structured_assignment_repl,
        text,
    )
    return re.sub(structured_list_pattern, structured_list_repl, work)


def notes_collapse_nested_inline_math(text: str) -> str:
    """Remove delimiters nested inside an inline span without rewriting its math."""
    work = str(text)
    rendered: list[str] = []
    cursor = 0
    while True:
        start = work.find(r"\(", cursor)
        if start < 0:
            rendered.append(work[cursor:])
            break
        rendered.append(work[cursor:start])
        depth = 1
        scan = start + 2
        core_parts: list[str] = []
        while scan < len(work) and depth:
            marker = work[scan:scan + 2]
            if marker == r"\(":
                depth += 1
                scan += 2
            elif marker == r"\)":
                depth -= 1
                scan += 2
            else:
                core_parts.append(work[scan])
                scan += 1
        if depth:
            rendered.append(work[start:])
            break
        rendered.append(r"\(" + "".join(core_parts) + r"\)")
        cursor = scan
    return "".join(rendered)


def notes_latex_prose(text: str) -> str:
    work = notes_clean_source_prose(text)
    placeholders: dict[str, str] = {}

    def store(latex: str) -> str:
        token = f"NOTESMATH{len(placeholders)}TOKEN"
        placeholders[token] = rf"\({latex}\)"
        return token

    def store_display(latex: str) -> str:
        token = f"NOTESMATH{len(placeholders)}TOKEN"
        placeholders[token] = rf"\[{latex}\]"
        return token

    work = notes_stash_source_math(work, store, store_display)
    work = notes_stash_structured_lists(work, store)

    def indexed_note_math(name: str, indices: str) -> str:
        body = re.sub(r"\s+", "", indices)
        body = re.sub(
            r"\b([A-Za-z]{2,})_([A-Za-z0-9]+)\b",
            lambda match: r"\mathrm{" + match.group(1) + "}_{" + match.group(2) + "}",
            body,
        )
        body = re.sub(r"\b([A-Za-z])_([A-Za-z0-9]+)\b", r"\1_{\2}", body)
        rendered_name = name if len(name) == 1 else r"\mathrm{" + name + "}"
        return rendered_name + "[" + body + "]"

    def complexity_repl(match: re.Match[str]) -> str:
        return store(notes_growth_latex(match.group("operator"), match.group("body")))

    work = replace_inline_math_relations(work, store)
    work = NOTES_GROWTH_OPERATOR_RE.sub(complexity_repl, work)
    for symbol, latex in NOTES_UNICODE_INLINE_MATH.items():
        if symbol not in work:
            continue
        work = work.replace(symbol, store(latex))
    work = "".join(
        character if ord(character) < 128 else unicodedata.normalize("NFKD", character).encode("ascii", "ignore").decode("ascii")
        for character in work
    )
    work = re.sub(
        r"\b([A-Za-z][A-Za-z0-9]*)\[([A-Za-z0-9_+\-,: ]{1,80})\]",
        lambda match: store(indexed_note_math(match.group(1), match.group(2))),
        work,
    )
    work = re.sub(
        r"\b([A-Za-z]{2,})_([A-Za-z0-9]+)\b",
        lambda match: store(r"\mathrm{" + match.group(1) + "}_{" + match.group(2) + "}"),
        work,
    )
    work = re.sub(
        r"\b([A-Za-z])_([A-Za-z0-9]+)\b",
        lambda match: store(rf"{match.group(1)}_{{{match.group(2)}}}"),
        work,
    )
    work = re.sub(
        r"\bZ/([A-Za-z0-9]+)Z\s+x\s+Z/([A-Za-z0-9]+)Z\b",
        lambda match: store(
            rf"\mathbb{{Z}}/{match.group(1)}\mathbb{{Z}}\times\mathbb{{Z}}/{match.group(2)}\mathbb{{Z}}"
        ),
        work,
    )
    work = re.sub(
        r"\bZ/([A-Za-z0-9]+)Z\b",
        lambda match: store(rf"\mathbb{{Z}}/{match.group(1)}\mathbb{{Z}}"),
        work,
    )
    work = re.sub(
        r"\b([A-Z])/\[\1,\1\]",
        lambda match: store(rf"{match.group(1)}/[{match.group(1)},{match.group(1)}]"),
        work,
    )
    work = re.sub(
        r"\b([SAD])_([0-9]+|n)\b",
        lambda match: store(rf"{match.group(1)}_{{{match.group(2)}}}"),
        work,
    )
    work = re.sub(
        r"\b([SAD])([0-9]+)\b",
        lambda match: store(rf"{match.group(1)}_{{{match.group(2)}}}"),
        work,
    )
    work = re.sub(
        r"\bZ([0-9]+)\b",
        lambda match: store(rf"\mathbb{{Z}}/{match.group(1)}\mathbb{{Z}}"),
        work,
    )
    work = work.replace("Z/even integers", store(r"\mathbb{Z}/2\mathbb{Z}"))
    work = re.sub(
        r"\b([A-Z])\[([a-zA-Z])\]",
        lambda match: store(rf"{match.group(1)}[{match.group(2)}]"),
        work,
    )
    work = re.sub(
        r"\b(\d+)\s+inverse\s+is\s+(\d+)\s+modulo\s+(\d+)\b",
        lambda match: store(rf"{match.group(1)}^{{-1}}\equiv {match.group(2)}\pmod{{{match.group(3)}}}"),
        work,
        flags=re.I,
    )
    function_atom = r"(?:phi|varphi|psi)\s*\([^()]{1,80}\)"
    function_sum = rf"{function_atom}(?:\s*\+\s*{function_atom})?"
    function_equation = re.compile(
        rf"({function_sum}\s*=\s*(?:{function_atom}|[0-9A-Za-z+\-*/ ]+?)"
        rf"(?:\s*=\s*(?:{function_atom}|[0-9A-Za-z+\-*/ ]+?))*)"
        rf"(?=\s+(?:is|matches|mod|and|but|so|while)\b|[,.;]|$)",
        flags=re.I,
    )
    work = function_equation.sub(
        lambda match: store(sanitize_formula_latex(match.group(1)).replace(r"\phi", r"\varphi")),
        work,
    )
    operator_atom = r"(?:det|ord|rank|dim|nullity|span|proj)\s*\([^()]{1,80}\)"
    operator_equation = re.compile(
        rf"({operator_atom}(?:\s*{operator_atom})?\s*=\s*"
        rf"(?:{operator_atom}(?:\s*{operator_atom})?|[0-9A-Za-z+\-*/ ]+?))"
        rf"(?=\s+(?:is|matches|mod|and|but|so|while)\b|[,.;]|$)",
        flags=re.I,
    )

    def operator_equation_repl(match: re.Match[str]) -> str:
        latex = latex_math_expr(match.group(1))
        latex = re.sub(r"(?<!\\)\bord\(", lambda _match: r"\operatorname{ord}(", latex)
        return store(latex)

    work = operator_equation.sub(operator_equation_repl, work)
    work = re.sub(
        r"\b([A-Za-z][A-Za-z0-9]*)\^\{(-?[A-Za-z0-9]+)\}",
        lambda match: store(rf"{match.group(1)}^{{{match.group(2)}}}"),
        work,
    )
    work = re.sub(
        r"\b([A-Za-z][A-Za-z0-9]*)\^(-?\d+)\b",
        lambda match: store(rf"{match.group(1)}^{{{match.group(2)}}}"),
        work,
    )
    work = re.sub(
        r"\b(phi|varphi|psi)\s*\(([^()]{1,80})\)",
        lambda match: store(
            (r"\varphi" if match.group(1).lower() in {"phi", "varphi"} else r"\psi")
            + "(" + latex_math_expr(match.group(2)) + ")"
        ),
        work,
        flags=re.I,
    )
    work = re.sub(
        r"(?<![A-Za-z0-9])(-?\d+[a-zA-Z])\b",
        lambda match: store(latex_math_expr(match.group(1))),
        work,
    )
    work = re.sub(
        r"(?<![A-Za-z0-9_])([A-Za-z][A-Za-z0-9_]*(?:\([^()]*\))?)\s*->\s*([A-Za-z0-9_+\-*/()]+)",
        lambda match: store(
            sanitize_formula_latex(match.group(1)) + r"\to " + sanitize_formula_latex(match.group(2))
        ),
        work,
    )
    work = work.replace(" -> ", " " + store(r"\longrightarrow") + " ")
    work = re.sub(
        r"\b([a-z])\s+in\s+([FGHKRSVW])\b",
        lambda match: store(rf"{match.group(1)}\in {match.group(2)}"),
        work,
    )
    work = re.sub(
        r"\b(over|inside|from|to)\s+([FGHKRSVW])\b",
        lambda match: match.group(1) + " " + store(match.group(2)),
        work,
        flags=re.I,
    )
    work = re.sub(
        r"\b(for every|for all)\s+([a-z])\b",
        lambda match: match.group(1) + " " + store(match.group(2)),
        work,
        flags=re.I,
    )
    work = re.sub(
        r"(?<![\\_^])\{\s*([A-Za-z0-9,\s\-]+)\s*\}",
        lambda match: store(r"\{" + sanitize_formula_latex(match.group(1).strip()) + r"\}"),
        work,
    )
    rendered = latex_text_with_inline_math(work)
    for token, latex in placeholders.items():
        rendered = rendered.replace(latex_escape(token), latex).replace(token, latex)
    return notes_collapse_nested_inline_math(rendered)


