def bounded_semantic_display_label(
    role: object,
    object_id: object = "",
    *,
    max_line_chars: int = 15,
    max_lines: int = 2,
) -> tuple[str, ...]:
    """Return readable display copy without changing semantic identity metadata."""
    if max_line_chars < 4 or max_lines not in {1, 2}:
        raise ValueError("Semantic display labels require one or two bounded readable lines")

    canonical_role = re.sub(r"\s+", " ", str(role or "object").replace("_", " ")).strip()
    identifier_leaf = str(object_id or "").rsplit(":", 1)[-1].replace("_", " ").strip()
    presentation_words = {
        "and", "arrow", "arrows", "being", "blocks", "comparison", "marker",
        "persistent", "values", "verdict", "witness",
    }
    presentation_terms = {
        "associativity": "grouping law",
        "automorphism": "self-map",
        "divisibility": "divides",
        "equivalence": "same class",
        "factorization": "factors",
        "isomorphism": "same structure",
        "multiplication": "product",
        "representative": "chosen element",
    }
    presentation_phrases = {
        "angular momentum": "L vector",
    }

    def presentation_candidate(value: str) -> str:
        candidate = str(value)
        for phrase, replacement in presentation_phrases.items():
            candidate = re.sub(r"\b" + re.escape(phrase) + r"\b", replacement, candidate, flags=re.I)
        return " ".join(
            presentation_terms.get(word.lower().strip("-.,:;()"), word)
            for word in candidate.split()
        )

    compact_role = " ".join(
        word for word in canonical_role.split() if word.lower().strip("-.,:;()") not in presentation_words
    )
    candidates = [presentation_candidate(compact_role)] if compact_role else []
    canonical_presentation = presentation_candidate(canonical_role)
    if canonical_presentation not in candidates:
        candidates.append(canonical_presentation)
    identifier_presentation = presentation_candidate(identifier_leaf)
    if identifier_presentation and identifier_presentation not in candidates:
        candidates.append(identifier_presentation)

    def balanced_lines(candidate: str) -> tuple[str, ...] | None:
        words = candidate.split()
        if not words or any(len(word) > max_line_chars for word in words):
            return None
        preferred_line_chars = min(max_line_chars, 10)
        if len(candidate) <= preferred_line_chars:
            return (candidate,)
        options = []
        if len(candidate) <= max_line_chars:
            options.append((len(candidate), 0, 1, (candidate,)))
        if max_lines == 1:
            return min(options)[-1] if options else None
        for split_at in range(1, len(words)):
            first = " ".join(words[:split_at])
            second = " ".join(words[split_at:])
            if len(first) <= max_line_chars and len(second) <= max_line_chars:
                options.append(
                    (
                        max(len(first), len(second)),
                        abs(len(first) - len(second)),
                        2,
                        (first, second),
                    )
                )
        if not options:
            return None
        return min(options)[-1]

    presentations = []
    for priority, candidate in enumerate(candidates):
        lines = balanced_lines(candidate)
        if lines:
            presentations.append(
                (
                    max(len(line) for line in lines),
                    sum(len(line) for line in lines),
                    len(lines),
                    priority,
                    lines,
                )
            )
    if presentations:
        return min(presentations)[-1]
    raise ValueError("Semantic role has no readable bounded display label: " + canonical_role)


def proof_surface_layout(
    surface_width: float,
    surface_height: float,
    route: str = "core_proof",
    *,
    occupied_row_ratio: float | None = None,
    occupied_column_ratio: float | None = None,
) -> dict[str, object]:
    """Solve uniform core scaling without counting labels or evidence.

    ``requires_reflow`` is true when no uniform scale can satisfy both axis
    ranges (or the supplied occupied-row/column evidence). Callers can then
    recompose the core instead of shrinking its attached annotations.
    """
    if route not in PROOF_SURFACE_LAYOUT_CONTRACT:
        raise ValueError(f"unknown proof-surface route: {route}")
    width = float(surface_width)
    height = float(surface_height)
    if not math.isfinite(width) or not math.isfinite(height) or width <= 0.0 or height <= 0.0:
        raise ValueError("proof-surface dimensions must be positive finite numbers")
    contract = dict(PROOF_SURFACE_LAYOUT_CONTRACT[route])
    lane_width = float(contract["lane_width"])
    lane_height = float(contract["lane_height"])
    area_scale = math.sqrt(
        float(contract["min_area_occupancy"]) * lane_width * lane_height / (width * height)
    )
    minimum_scale = max(
        float(contract["min_width_occupancy"]) * lane_width / width,
        float(contract["min_height_occupancy"]) * lane_height / height,
        area_scale,
    )
    maximum_scale = min(
        float(contract["max_width_occupancy"]) * lane_width / width,
        float(contract["max_height_occupancy"]) * lane_height / height,
    )
    if maximum_scale <= 0.0:
        raise ValueError("proof-surface maximum scale must be positive")
    current_width_occupancy = width / lane_width
    current_height_occupancy = height / lane_height
    below_minimum = (
        current_width_occupancy < float(contract["min_width_occupancy"])
        or current_height_occupancy < float(contract["min_height_occupancy"])
    )
    above_maximum = (
        current_width_occupancy > float(contract["max_width_occupancy"])
        or current_height_occupancy > float(contract["max_height_occupancy"])
    )
    uniform_scale_feasible = minimum_scale <= maximum_scale + 1e-9
    if not uniform_scale_feasible:
        scale = maximum_scale
    elif above_maximum:
        scale = maximum_scale
    elif below_minimum:
        scale = min(minimum_scale, maximum_scale)
    else:
        scale = 1.0
    width_occupancy = width * scale / lane_width
    height_occupancy = height * scale / lane_height
    area_occupancy = width_occupancy * height_occupancy
    row_coverage = height_occupancy if occupied_row_ratio is None else float(occupied_row_ratio)
    column_coverage = width_occupancy if occupied_column_ratio is None else float(occupied_column_ratio)
    minimum_satisfied = (
        width_occupancy + 1e-9 >= float(contract["min_width_occupancy"])
        and height_occupancy + 1e-9 >= float(contract["min_height_occupancy"])
        and area_occupancy + 1e-9 >= float(contract["min_area_occupancy"])
        and row_coverage + 1e-9 >= float(contract["min_occupied_row_ratio"])
        and column_coverage + 1e-9 >= float(contract["min_occupied_column_ratio"])
    )
    maximum_satisfied = (
        width_occupancy <= float(contract["max_width_occupancy"]) + 1e-9
        and height_occupancy <= float(contract["max_height_occupancy"]) + 1e-9
    )
    return {
        "route": route,
        "scale": scale,
        "width_occupancy": width_occupancy,
        "height_occupancy": height_occupancy,
        "minimum_satisfied": minimum_satisfied,
        "maximum_satisfied": maximum_satisfied,
        "area_occupancy": area_occupancy,
        "occupied_row_ratio": row_coverage,
        "occupied_column_ratio": column_coverage,
        "requires_reflow": not (uniform_scale_feasible and minimum_satisfied and maximum_satisfied),
        "labels_included_in_bounds": False,
        "measured_region": "core_proof",
        "contract": contract,
    }


def geometry_intrusion_pairs(
    regions: dict[str, tuple[float, float, float, float]],
    *,
    pad: float = 0.0,
) -> list[tuple[str, str]]:
    """Return pairs of axis-aligned layout regions whose interiors intrude."""
    names = list(regions)
    intrusions: list[tuple[str, str]] = []
    padding = max(0.0, float(pad))
    for left_index, left_name in enumerate(names):
        left, bottom, right, top = (float(value) for value in regions[left_name])
        if left >= right or bottom >= top:
            raise ValueError(f"invalid geometry region: {left_name}")
        for right_name in names[left_index + 1 :]:
            other_left, other_bottom, other_right, other_top = (
                float(value) for value in regions[right_name]
            )
            if other_left >= other_right or other_bottom >= other_top:
                raise ValueError(f"invalid geometry region: {right_name}")
            separated = (
                right + padding <= other_left
                or other_right + padding <= left
                or top + padding <= other_bottom
                or other_top + padding <= bottom
            )
            if not separated:
                intrusions.append((left_name, right_name))
    return intrusions


def spoken_word_count(text: object) -> int:
    return len(re.findall(r"[A-Za-z0-9]+(?:'[A-Za-z0-9]+)?", screen_prose(text)))


def estimate_spoken_seconds(text: object) -> float:
    return spoken_word_count(text) / WORDS_PER_SECOND


def duration_for_texts(texts: list[object], minimum: float, animation_budget: float) -> float:
    speech = sum(estimate_spoken_seconds(text) for text in texts)
    return max(minimum, speech + animation_budget + 1.2)


def duration_for_beat(text: object, *, minimum: float, animation_budget: float) -> float:
    return max(minimum, estimate_spoken_seconds(text) + animation_budget)


def semantic_animation_factor(short: dict[str, object], visual_kind: str) -> float:
    """Estimate how much screen time the actual worked visual needs to read."""
    ex = short.get("worked_example") if isinstance(short.get("worked_example"), dict) else {}
    semantic_text = " ".join(
        str(value)
        for value in (
            short.get("formula", short.get("plain_formula", "")),
            ex.get("setup", ""),
            ex.get("calculation", ""),
        )
    )
    operators = len(re.findall(r"(?:->|=>|=|\+|-|\*|/|\\(?:sum|prod|frac|int)|\bmod\b)", semantic_text))
    values = len(extract_numbers(semantic_text))
    structural_kinds = {
        "matrix_vector", "linear_combination", "systems", "elimination", "transform_grid",
        "group_cosets", "group_homomorphism", "group_action", "algebra_galois",
        "cs_graph", "state_machine", "markov", "chemistry_reaction", "game_payoff",
    }
    structural_bonus = 0.18 if visual_kind in structural_kinds else 0.0
    semantic_steps = max(1, operators + math.ceil(values / 3))
    return 1.0 + structural_bonus + math.sqrt(semantic_steps - 1) * 0.12


def fit_beat_schedule_duration(beats: list[dict[str, object]]) -> list[dict[str, object]]:
    """Retain content-derived beat durations without manufacturing a clip minimum."""
    return beats


def strip_redundant_title_prefix(text: object, title: object) -> str:
    """Remove a repeated ``Title:`` prefix before screen-text staging."""
    normalized = re.sub(r"\s+", " ", screen_prose(text)).strip()
    title_words = re.findall(r"[A-Za-z0-9]+", screen_prose(title))
    if not normalized or not title_words:
        return normalized
    flexible_title = r"[\W_]*".join(re.escape(word) for word in title_words)
    prefix = re.compile(rf"^\s*{flexible_title}\s*[:\-\u2013\u2014]\s*", re.IGNORECASE)
    stripped = prefix.sub("", normalized, count=1).strip()
    return stripped or normalized


def readable_text_stages(text: object, width: int = 32, lines_per_stage: int = 3) -> list[list[str]]:
    """Stage complete sentences without exposing partial clauses on screen."""
    normalized = re.sub(r"\s+", " ", screen_prose(text)).strip()
    if not normalized:
        return [[""]]
    line_limit = max(1, lines_per_stage)
    clauses = []
    for raw_clause in re.split(r"(?<=[.!?;])\s+", normalized):
        clause = raw_clause.strip()
        if not clause:
            continue
        if clause.endswith(";"):
            clause = clause[:-1].rstrip() + "."
        clause = re.sub(
            r"^(?:and|but|or)\s+",
            lambda match: "",
            clause,
            count=1,
            flags=re.IGNORECASE,
        )
        clause = clause[:1].upper() + clause[1:]
        clauses.append(clause)
    groups: list[list[str]] = []
    for clause in clauses:
        adaptive_width = width
        while True:
            lines = textwrap.wrap(
                clause,
                width=adaptive_width,
                break_long_words=False,
                break_on_hyphens=False,
            ) or [clause]
            if len(lines) <= line_limit:
                break
            adaptive_width += 2
        groups.append(lines)

    stages: list[list[str]] = []
    for group in groups:
        if stages and len(stages[-1]) + len(group) <= line_limit:
            stages[-1].extend(group)
        else:
            stages.append(list(group))

    return stages


def complete_visible_prose_stage(value: object) -> bool:
    """Reject screen stages that are only the beginning or end of a sentence."""
    text = re.sub(r"\s+", " ", str(value)).strip()
    if not text:
        return False
    if re.search(r"(?:=|<=|>=|->|→|⇔|∈|⊆|\|)", text):
        return True
    causal_sentence = bool(
        re.match(r"^because\b", text, re.IGNORECASE)
        and re.search(r",\s*[^,]+[.!?]$", text)
    )
    if (
        re.match(r"^(?:and|but|or|which|while|where|when|because|so|yet)\b", text, re.IGNORECASE)
        and not causal_sentence
    ):
        return False
    if re.search(r"(?:[,;:]|\b(?:and|at|by|for|from|in|of|on|or|the|to|with))\s*$", text, re.IGNORECASE):
        return False
    return bool(re.search(r"[.!?]$", text))


def concise_screen_clause(value: object, *, max_words: int) -> str:
    """Select one complete semantic clause without cutting formulas or tokens."""
    raw = re.sub(r"\s+", " ", learner_identifier_display_name(value)).strip()
    formula_atomic = bool(re.search(r"\\[A-Za-z]+|[^A-Za-z0-9\s]\^[A-Za-z0-9{]|[{}]|(?:<=|>=|->|→|=)", raw))
    text = (
        re.sub(r"\s+", " ", formula_unicode_text(raw)).strip()
        if formula_atomic
        else re.sub(r"\s+", " ", screen_prose(raw)).strip()
    )
    if not text:
        return ""
    if formula_atomic:
        return text
    sentences = [part.strip() for part in re.split(r"(?<=[.!?])\s+", text) if part.strip()]
    first_sentence = sentences[0] if sentences else text
    clauses = [
        part.strip(" ,;:")
        for part in re.split(
            r"\s*;\s*|,\s+(?=(?:while|where|when|because|so that|but|then|which|and then)\b)|\s+(?=(?:while|because|so that)\b)",
            first_sentence,
            flags=re.IGNORECASE,
        )
        if part.strip(" ,;:")
    ]
    bounded = [clause for clause in clauses if len(clause.split()) <= max_words]
    candidate = bounded[0] if bounded else (clauses[0] if clauses else first_sentence)
    # A formula is an atomic visual token.  Keep the entire equality or
    # recurrence even when prose around it must be omitted.
    formula = re.search(
        r"(?:[A-Za-z][A-Za-z0-9_()\[\],{}\\^+*/. -]*\s*(?:=|<=|>=|->|→|≅|∈|⊆|\|)\s*[^.;!?]+)",
        candidate,
    )
    if formula and len(candidate.split()) > max_words:
        candidate = formula.group(0).strip(" ,;:")
    return candidate.rstrip()


STORYBOARD_SCREEN_VERBS = (
    "animate", "color", "construct", "display", "draw", "fade", "highlight",
    "mark", "move", "place", "reveal", "shift", "show", "trace", "transform",
    "write", "zoom",
)
STORYBOARD_SCREEN_VERB_RE = re.compile(
    r"(?:^|(?<=[.!?;])\s+)(?:please\s+)?(?:"
    + "|".join(STORYBOARD_SCREEN_VERBS)
    + r")\b",
    re.IGNORECASE,
)


def storyboard_instruction_leak(value: object) -> bool:
    """Return whether learner copy still contains a staging instruction."""
    return bool(STORYBOARD_SCREEN_VERB_RE.search(re.sub(r"\s+", " ", str(value)).strip()))


def learner_facing_screen_copy(value: object, *, max_words: int) -> str:
    """Produce one complete learner-facing claim, never a storyboard command."""
    text = re.sub(
        r"\s+",
        " ",
        screen_prose(learner_identifier_display_name(value)),
    ).strip()
    text = re.sub(r"(?:\.{3,}|\u2026)\s*$", "", text).rstrip(" ,;:")
    if not text:
        return ""
    study_template = re.fullmatch(
        r"Study (.+?) by naming the objects, the operation, and the property being preserved or tested\.?",
        text,
        flags=re.IGNORECASE,
    )
    if study_template:
        topic = study_template.group(1).strip()
        return f"{topic} names its objects, operation, and preserved property."
    word_count = len(re.findall(r"[A-Za-z0-9]+(?:'[A-Za-z0-9]+)?", text))
    if not storyboard_instruction_leak(text) and word_count <= max_words:
        return text

    sentences = [part.strip() for part in re.split(r"(?<=[.!?])\s+", text) if part.strip()]
    declarative = next((part for part in sentences if not storyboard_instruction_leak(part)), None)
    candidate = concise_screen_clause(declarative or text, max_words=max_words)
    if not storyboard_instruction_leak(candidate):
        return candidate.rstrip(" ,;:")

    command = re.match(
        r"^(?:please\s+)?(?P<verb>" + "|".join(STORYBOARD_SCREEN_VERBS) + r")\s+(?P<object>.+)$",
        candidate,
        flags=re.IGNORECASE,
    )
    if command is None:
        raise ValueError("Visible copy contains a storyboard instruction: " + candidate)
    verb = command.group("verb").casefold()
    object_text = re.split(
        r"\s*(?:,|;)\s*(?:then\s+)?|\s+and\s+then\s+",
        command.group("object").rstrip(".!?"),
        maxsplit=1,
        flags=re.IGNORECASE,
    )[0].strip(" ,;:")
    object_text = re.sub(r"\bby pass\b", "in each pass", object_text, flags=re.IGNORECASE)
    if not object_text:
        raise ValueError("Storyboard instruction has no learner-facing semantic object")
    subject = object_text[:1].upper() + object_text[1:]
    if verb in {"show", "display", "reveal", "highlight", "mark", "color"}:
        claim = f"{subject} is explicit in the model"
    elif verb in {"draw", "construct", "place"}:
        claim = f"{subject} defines the model state"
    elif verb in {"move", "shift", "animate", "transform"}:
        claim = f"{subject} changes while the governing invariant remains fixed"
    elif verb == "trace":
        claim = f"{subject} determines the next state"
    elif verb == "write":
        claim = f"{subject} states the governing relation"
    else:
        raise ValueError(f"Storyboard verb {verb!r} has no semantic copy rule")
    if storyboard_instruction_leak(claim):
        raise ValueError("Storyboard instruction survived learner-copy normalization")
    return claim + "."


def screen_cue_lines(text: object, *, width: int = 38, max_lines: int = 2) -> list[str]:
    """Wrap one bounded cue; callers must stage copy that needs more lines."""
    normalized = re.sub(r"\s+", " ", str(text)).strip()
    if max_lines < 1:
        raise ValueError("max_lines must be positive")
    lines = textwrap.wrap(normalized, width=width, break_long_words=False, break_on_hyphens=False) or [""]
    if len(lines) > max_lines:
        raise ValueError("screen cue exceeds its line budget; stage the copy instead")
    return lines


def simplified_scene_cue_lines(
    lines: list[object],
    *,
    width: int = 32,
    max_lines: int = 2,
    max_words: int = 14,
) -> list[str]:
    """Reflow a cue, then simplify its clause before the renderer may shrink it."""
    text = re.sub(r"\s+", " ", " ".join(str(line).strip() for line in lines)).strip()
    wrapped = textwrap.wrap(text, width=width, break_long_words=False, break_on_hyphens=False) or [""]
    if len(wrapped) <= max_lines:
        return wrapped
    simplified = concise_screen_clause(text, max_words=max_words)
    wrapped = textwrap.wrap(simplified, width=width, break_long_words=False, break_on_hyphens=False) or [""]
    if len(wrapped) > max_lines:
        formula_atomic = bool(re.search(r"\\[A-Za-z]+|[_^{}]|(?:<=|>=|->|→|=)", simplified))
        if formula_atomic:
            # Equations may reflow, but every term and relation survives.
            formula_width = max(width, math.ceil(len(simplified) / max_lines))
            while formula_width <= len(simplified):
                wrapped = textwrap.wrap(
                    simplified,
                    width=formula_width,
                    break_long_words=False,
                    break_on_hyphens=False,
                )
                if len(wrapped) <= max_lines:
                    break
                formula_width += 1
        else:
            words = simplified.split()
            if len(words) < 2:
                raise ValueError("screen cue cannot be balanced without truncation")
            best_lines = None
            best_score = None
            for split in range(1, len(words)):
                candidate = [" ".join(words[:split]), " ".join(words[split:])]
                score = (max(len(line) for line in candidate), abs(len(candidate[0]) - len(candidate[1])))
                if best_score is None or score < best_score:
                    best_lines = candidate
                    best_score = score
            wrapped = best_lines or [simplified]
    if any("..." in line or "…" in line for line in wrapped):
        raise ValueError("screen cue contains a truncation ellipsis")
    return wrapped


def algebra_phone_cue_reflow_enabled(visual_kind: object) -> bool:
    """Keep every algebra route within the shared two-line phone cue contract."""
    return str(visual_kind).startswith("algebra_")


def concise_result_claim(value: object, *, max_words: int = 16) -> str:
    """Turn generator boilerplate into a compact result/mechanism claim."""
    del max_words
    text = re.sub(r"\s+", " ", screen_prose(value)).strip()
    match = re.match(r"^This teaches\s+.+?\s+(?:by|with)\s+(.+)$", text, re.IGNORECASE)
    if match:
        mechanism = match.group(1).strip().rstrip(".")
        claim_ready = False
        replacements = (
            (r"^turning\s+(.+?)\s+into\s+(.+)$", r"\1 becomes \2"),
            (r"^keeping\s+(.+?)\s+fixed\s+while\s+(.+)$", r"\1 stays fixed while \2"),
            (r"^separating\s+(.+?)\s+from\s+(.+)$", r"\1 differs from \2"),
            (r"^showing\s+", ""),
            (r"^making\s+", ""),
        )
        for replacement_index, (pattern, replacement) in enumerate(replacements):
            updated = re.sub(pattern, replacement, mechanism, count=1, flags=re.IGNORECASE)
            if updated != mechanism:
                mechanism = updated
                claim_ready = replacement_index < 3
                break
        text = mechanism if claim_ready else "Result - " + mechanism
        text = text[:1].upper() + text[1:]
    return text.rstrip(".") + "." if text else ""


def silent_semantic_cue(
    short: dict[str, object],
    visual_kind: str,
    state_name: str,
    fallback: object,
) -> str:
    """Use the renderer's data to write complete setup and mechanism cues."""
    try:
        state = animation_renderer_state(short, visual_kind)
    except (TypeError, ValueError):
        state = {}
    payload_type = str(state.get("payload_type", "")) if isinstance(state, dict) else ""
    family = str(state.get("family", "")) if isinstance(state, dict) else ""
    mode = str(state.get("mode", "")) if isinstance(state, dict) else ""
    if payload_type == "physics":
        cue = physics_visible_cue(state, state_name)
        if cue is not None:
            return cue
        if state_name == "core_idea":
            return concise_screen_clause(
                state.get("invariant", fallback),
                max_words=ANIMATION_PLAN_MAX_CUE_WORDS,
            )
    if payload_type == "economics":
        if state_name == "core_idea":
            return concise_screen_clause(
                state.get("invariant", fallback),
                max_words=ANIMATION_PLAN_MAX_CUE_WORDS,
            )
        if state_name in {"example_setup", "example_calculation"}:
            return concise_screen_clause(fallback, max_words=ANIMATION_PLAN_MAX_CUE_WORDS)
    if payload_type == "cs":
        if family == "graph":
            start = str(state.get("start") or (state.get("nodes") or ["start"])[0])
            if state_name == "example_setup":
                return f"Start at {start} on the shown directed graph."
            graph_actions = {
                "bfs": "Dequeue one vertex; enqueue each undiscovered neighbor once.",
                "dfs": "Push on discovery; pop only after every outgoing edge finishes.",
                "topological": "Remove a zero-indegree vertex, then release its outgoing neighbors.",
                "bellman_ford": "Scan every edge; keep only strict distance improvements.",
                "dijkstra": "Settle the minimum label, then relax its outgoing edges.",
                "johnson_reweight": "Add h(u)-h(v) to each edge; path order stays unchanged.",
            }
            graph_ideas = {
                "bfs": "Distance layers grow in FIFO order from the source.",
                "dfs": "One active path stays visible; finished vertices turn green.",
                "topological": "Every output vertex has no remaining prerequisite.",
                "bellman_ford": "Each full pass can extend shortest paths by one edge.",
                "dijkstra": "Nonnegative weights make the smallest tentative label final.",
                "johnson_reweight": "Potentials change edge weights but preserve every path comparison.",
            }
            if state_name == "core_idea":
                return graph_ideas.get(mode, "Keep the graph fixed while its algorithmic state changes.")
            if state_name == "example_calculation":
                return graph_actions.get(mode, "Move the frontier and update the visible graph state.")
        if family == "sort":
            initial = list(state.get("initial", []))
            if state_name == "example_setup":
                return f"Sort {len(initial)} keys while every key remains visible."
            if state_name == "core_idea":
                sort_ideas = {
                    "counting": "Bucket counts replace comparisons over a bounded key universe.",
                    "merge": "Split into ordered runs, then merge the same keys without losing identity.",
                    "selection": "Select the smallest remaining key and extend the sorted prefix.",
                    "insertion": "Shift the larger prefix keys, then insert the next key in its slot.",
                }
                return sort_ideas.get(mode, "Move the same keys while the sorted region grows.")
            if state_name == "example_calculation":
                sort_actions = {
                    "counting": "Count each key, accumulate positions, then place keys stably.",
                    "merge": "Expose singleton runs, then compare their heads and merge level by level.",
                    "selection": "Find the suffix minimum, swap it forward, and preserve the finished prefix.",
                    "insertion": "Shift each larger prefix key right, then place the active key once.",
                }
                return sort_actions.get(mode, "Move one key at a time while growing the sorted invariant.")
        if family == "divide":
            if state_name == "example_setup":
                return f"Expand the size-{state.get('n', 8)} problem into a persistent binary recursion tree."
            if state_name == "core_idea":
                return "Each recursion level retains its subproblems and contributes the same linear work."
            if state_name == "example_calculation":
                return "Accumulate every visible level total, then combine logarithmically many n-work levels."
        if family == "dp":
            if mode == "fibonacci_memo":
                if state_name == "example_setup":
                    return f"Call F({state.get('target', 5)}) with an empty persistent cache."
                if state_name == "core_idea":
                    return "A completed cache miss stores one value; repeated calls become cache hits."
                if state_name == "example_calculation":
                    return "Follow every call, miss, store, return, and cache hit in order."
            row_count = len(state.get("row_labels", []))
            column_count = len(state.get("column_labels", []))
            if state_name == "example_setup":
                return f"Fill the {row_count} by {column_count} table from its base cases."
            if state_name == "core_idea":
                dp_ideas = {
                    "grid_paths": "Every cell depends only on its top and left neighbors.",
                    "matrix_chain": "Each interval chooses the cheapest split among smaller intervals.",
                    "knapsack": "Each cell compares excluding the item with including it once.",
                }
                return dp_ideas.get(mode, "Solved subproblems stay fixed while later cells reuse them.")
            if state_name == "example_calculation":
                dp_actions = {
                    "grid_paths": "Follow top and left contributions into each new path count.",
                    "matrix_chain": "Compare A(BC)=27000 with (AB)C=4500, then trace the winning split.",
                    "knapsack": "At each capacity, compare exclude with including the item exactly once.",
                }
                return dp_actions.get(mode, "Reveal dependencies, combine their values, then write one cell.")
        if family == "array":
            initial = list(state.get("initial", []))
            if state_name == "example_setup":
                return f"Track {len(initial)} indexed cells and the one requested operation."
        if state_name == "example_calculation":
            return silent_calculation_cue(short, visual_kind, fallback)
    if state_name == "example_calculation":
        return silent_calculation_cue(short, visual_kind, fallback)
    return concise_screen_clause(fallback, max_words=ANIMATION_PLAN_MAX_CUE_WORDS)


def silent_calculation_cue(short: dict[str, object], visual_kind: str, fallback: object) -> str:
    """Describe the visible mechanism instead of repeating a prose calculation."""
    try:
        route = animation_route_descriptor(short, visual_kind)
        blueprint = route.get("blueprint") if isinstance(route, dict) else None
        mechanism = blueprint.get("mechanism") if isinstance(blueprint, dict) else None
    except (TypeError, ValueError):
        mechanism = None
    return concise_screen_clause(mechanism or fallback, max_words=ANIMATION_PLAN_MAX_CUE_WORDS)


def semantic_visual_step_count(short: dict[str, object], visual_kind: str) -> int:
    """Count concrete state changes so silent timing follows the animation."""
    counts: list[int] = []
    try:
        state = animation_renderer_state(short, visual_kind)
    except (TypeError, ValueError):
        state = {}
    for key in (
        "steps", "states", "state_sequence", "swaps", "snapshots", "fill_order",
        "operations", "updates", "levels", "merge_levels", "split_levels", "visual_state_sequence",
    ):
        value = state.get(key) if isinstance(state, dict) else None
        if isinstance(value, (list, tuple)):
            counts.append(len(value))
    if isinstance(state, dict):
        dependencies = state.get("dependencies")
        if isinstance(dependencies, dict):
            counts.append(len(dependencies))
    if counts:
        return max(3, max(counts))
    factor = semantic_animation_factor(short, visual_kind)
    return max(3, int(round(3 + (factor - 1.0) * 8)))


def _formula_timing_evidence(formula: object) -> dict[str, float | int]:
    """Measure the visible work needed to parse a formula, not its topic label."""
    source = re.sub(r"\s+", " ", str(formula)).strip()
    relation_count = len(re.findall(
        r"(?:\\(?:leq?|geq?|neq|approx|sim|equiv|cong|in|subseteq)|<=|>=|!=|=|<|>|≤|≥|≠|≈|∼|≅|∈|⊆)",
        source,
    ))
    operator_count = len(re.findall(
        r"(?:\\(?:cdot|times|pm|mp)|(?<![<>=!])[+*/-])",
        source,
    ))
    structure_count = len(re.findall(
        r"\\(?:frac|sum|prod|int|lim|sqrt|begin\{(?:[bBpPvV]?matrix|cases)\})",
        source,
    ))
    symbol_count = len(re.findall(r"(?<!\\)\b[A-Za-z](?:_[A-Za-z0-9{}]+|\^[A-Za-z0-9{}+-]+)?\b", source))
    seconds = (
        0.65
        + FORMULA_RELATION_SECONDS * relation_count
        + FORMULA_OPERATOR_SECONDS * operator_count
        + FORMULA_STRUCTURE_SECONDS * structure_count
        + FORMULA_SYMBOL_SECONDS * max(0, symbol_count - 2)
    )
    return {
        "relation_count": relation_count,
        "operator_count": operator_count,
        "structure_count": structure_count,
        "symbol_count": symbol_count,
        "seconds": round(seconds, 3),
    }


def _transition_timing_evidence(
    transition: dict[str, object],
    *,
    action_detail_scale: float = 1.0,
) -> dict[str, float | int | bool]:
    """Price one renderer transition from its state delta and visual obligations."""
    before = transition.get("before") if isinstance(transition.get("before"), dict) else {}
    after = transition.get("after") if isinstance(transition.get("after"), dict) else {}
    changed_object_count = sum(
        1 for object_id in set(before) | set(after)
        if before.get(object_id) != after.get(object_id)
    )
    evidence = transition.get("evidence_tokens")
    evidence_token_count = len(evidence) if isinstance(evidence, (list, tuple)) else 0
    searchable = " ".join(
        str(transition.get(key, "")) for key in ("id", "kind", "claim", "action")
    ).casefold()
    action_text = re.split(
        r",\s*before state=",
        str(transition.get("action", "")),
        maxsplit=1,
        flags=re.IGNORECASE,
    )[0]
    learner_action = " ".join((str(transition.get("claim", "")), action_text))
    action_formula = _formula_timing_evidence(learner_action)
    action_clause_count = 1 + len(re.findall(
        r"(?:;|\b(?:then|while|whereas|followed by|and then)\b)",
        learner_action,
        flags=re.IGNORECASE,
    ))
    action_number_count = len(extract_numbers(learner_action))
    comparison_step = bool(re.search(
        r"\b(?:compare|comparison|versus|alternative|either|minimum|maximum|winner|lower|higher|"
        r"before|after|dominates?|cheaper|costlier|surplus|welfare|trade-?off)\b",
        searchable,
    ))
    boundary_step = bool(re.search(
        r"\b(?:boundary|constraint|threshold|limit|capacity|endpoint|feasible|infeasible|"
        r"saturat(?:e|ed|ion)|cycle|cutoff|equilibrium|corner|interior)\b",
        searchable,
    ))
    duration_weight = max(1.0, float(transition.get("duration_weight", 1.0) or 1.0))
    action_detail_seconds = (
        ACTION_RELATION_SECONDS * int(action_formula["relation_count"])
        + ACTION_OPERATOR_SECONDS * int(action_formula["operator_count"])
        + ACTION_CLAUSE_SECONDS * max(0, action_clause_count - 1)
        + ACTION_NUMBER_SECONDS * math.sqrt(action_number_count)
    ) * max(0.0, action_detail_scale)
    seconds = (
        MIN_SEMANTIC_ACTION_SECONDS * duration_weight
        + CHANGED_OBJECT_SECONDS * max(0, changed_object_count - 1)
        + EVIDENCE_TOKEN_SECONDS * math.sqrt(evidence_token_count)
        + (COMPARISON_STEP_SECONDS if comparison_step else 0.0)
        + (BOUNDARY_STEP_SECONDS if boundary_step else 0.0)
        + action_detail_seconds
    )
    return {
        "changed_object_count": changed_object_count,
        "evidence_token_count": evidence_token_count,
        "comparison_step": comparison_step,
        "boundary_step": boundary_step,
        "action_relation_count": int(action_formula["relation_count"]),
        "action_operator_count": int(action_formula["operator_count"]),
        "action_clause_count": action_clause_count,
        "action_number_count": action_number_count,
        "action_detail_scale": round(max(0.0, action_detail_scale), 3),
        "action_detail_seconds": round(action_detail_seconds, 3),
        "duration_weight": duration_weight,
        "seconds": round(seconds, 3),
    }


def _structured_evidence_leaf_count(value: object) -> int:
    """Count atomic scenario values that must become legible visual evidence."""
    if isinstance(value, dict):
        return sum(_structured_evidence_leaf_count(item) for item in value.values())
    if isinstance(value, (list, tuple)):
        return sum(_structured_evidence_leaf_count(item) for item in value)
    return int(value is not None and str(value).strip() != "")


def semantic_duration_profile(
    short: dict[str, object],
    visual_kind: str | None = None,
) -> dict[str, object]:
    """Return topic-agnostic timing evidence used to synthesize the visual plan."""
    kind = visual_kind or infer_visual_kind(short)
    renderer_state: dict[str, object] = {}
    contract: dict[str, object] = {}
    try:
        route = animation_route_descriptor(short, kind)
        renderer_state = route.get("renderer_state") if isinstance(route.get("renderer_state"), dict) else {}
        contract = semantic_plan_contract(renderer_state) or {}
    except (TypeError, ValueError):
        contract = {}
    objects = [row for row in contract.get("objects", []) if isinstance(row, dict)]
    transitions = [row for row in contract.get("transitions", []) if isinstance(row, dict)]
    object_count = len(objects)
    object_construction_seconds = (
        OBJECT_CONSTRUCTION_BASE_SECONDS
        + OBJECT_CONSTRUCTION_SCALE_SECONDS * (object_count ** 0.72)
        if object_count else 0.0
    )
    formula = str(renderer_state.get("canonical_formula") or video_formula_text(short, kind))
    formula_evidence = _formula_timing_evidence(formula)
    action_detail_scale = min(1.0, 4.0 / max(1, len(transitions)))
    transition_evidence = {
        str(transition.get("id", f"transition:{index}")): _transition_timing_evidence(
            transition,
            action_detail_scale=action_detail_scale,
        )
        for index, transition in enumerate(transitions, start=1)
    }
    comparison_step_count = sum(bool(row["comparison_step"]) for row in transition_evidence.values())
    boundary_step_count = sum(bool(row["boundary_step"]) for row in transition_evidence.values())
    visual_action_seconds = sum(float(row["seconds"]) for row in transition_evidence.values())
    scenario = renderer_state.get("scenario")
    if not isinstance(scenario, dict):
        scenario = renderer_state.get("model_scenario")
    if isinstance(scenario, dict):
        result_key = "result" if "result" in scenario else "results"
        scenario_evidence = {
            key: scenario[key]
            for key in ("setup", "calculation", result_key)
            if key in scenario
        }
    else:
        scenario_evidence = scenario
    required_evidence_count = _structured_evidence_leaf_count(scenario_evidence)
    required_evidence_seconds = STRUCTURED_EVIDENCE_SECONDS * required_evidence_count
    resolution_seconds = 0.65 + 0.18 * math.sqrt(object_count + len(transitions))
    return {
        "visual_kind": kind,
        "object_count": object_count,
        "object_construction_seconds": round(object_construction_seconds, 3),
        "formula": formula_evidence,
        "transition_count": len(transitions),
        "transition_evidence": transition_evidence,
        "comparison_step_count": comparison_step_count,
        "boundary_step_count": boundary_step_count,
        "required_evidence_count": required_evidence_count,
        "required_evidence_seconds": round(required_evidence_seconds, 3),
        "visual_action_seconds": round(visual_action_seconds, 3),
        "resolution_seconds": round(resolution_seconds, 3),
    }


def assigned_semantic_transition_groups(
    short: dict[str, object],
    visual_kind: str | None = None,
) -> dict[str, list[dict[str, object]]]:
    """Assign causal transitions before any beat duration is calculated."""
    kind = visual_kind or infer_visual_kind(short)
    try:
        route = animation_route_descriptor(short, kind)
    except (TypeError, ValueError):
        return {}
    renderer_state = route.get("renderer_state") if isinstance(route, dict) else None
    if not isinstance(renderer_state, dict):
        return {}
    contract = semantic_plan_contract(renderer_state)
    if not isinstance(contract, dict):
        return {}
    transitions = [
        transition
        for transition in contract.get("transitions", [])
        if isinstance(transition, dict)
    ]
    if str(renderer_state.get("payload_type", "")) == "physics" and transitions:
        by_phase: dict[str, list[dict[str, object]]] = {
            "example_setup": [],
            "example_calculation": [],
            "example_takeaway": [],
        }
        for index, transition in enumerate(transitions):
            after_state = str(transition.get("after_state_id", ""))
            target = {
                "setup": "example_setup",
                "calculation": "example_calculation",
                "result": "example_takeaway",
            }.get(after_state)
            if target is None:
                target = (
                    "example_setup" if index == 0
                    else "example_takeaway" if index == len(transitions) - 1
                    else "example_calculation"
                )
            by_phase[target].append(transition)
        return by_phase
    if len(transitions) < len(SEMANTIC_TRANSITION_STATES):
        return {}
    groups = semantic_transition_groups(
        transitions,
        slots=len(SEMANTIC_TRANSITION_STATES),
    )
    return {
        state: group
        for state, group in zip(SEMANTIC_TRANSITION_STATES, groups)
    }


