def group_runtime_visual_kind(title: str) -> str:
    route = resolve_group_video_model(title, fail_closed=True)
    assert route is not None
    return {
        "group_laws": "group_structure",
        "finite_group_structure": "group_structure",
        "subgroup_cosets": "group_cosets",
        "homomorphism_quotient": "group_homomorphism",
        "permutation_cycles": "group_action",
        "group_action_automorphism": "group_action",
        "ring_laws_ideals": "algebra_ring_structure",
        "domain_factorization": "algebra_factorization",
        "algorithmic_algebra": "algebra_factorization",
    }[route.visual_family]


def video_renderer_implementation(visual_kind: str, dispatcher: str) -> dict[str, str]:
    return {"visual_kind": visual_kind, "dispatcher": dispatcher}


