def canonical_json_hash(payload: object) -> str:
    encoded = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def renderer_frame_seconds(value: float, *, rounding: str = "nearest") -> float:
    scaled = float(value) * RENDER_TIMELINE_FPS
    if rounding == "ceil":
        frames = math.ceil(scaled - 1e-9)
    elif rounding == "floor":
        frames = math.floor(scaled + 1e-9)
    else:
        frames = round(scaled)
    return round(frames / RENDER_TIMELINE_FPS, 6)


def animation_short_source_payload(short: dict[str, object]) -> dict[str, object]:
    payload = {field: short.get(field) for field in ANIMATION_SOURCE_FIELDS}
    if isinstance(short.get("piper_voice_timing"), dict):
        payload["piper_voice_timing"] = short["piper_voice_timing"]
    return payload


def animation_short_source_fingerprint(short: dict[str, object]) -> str:
    return canonical_json_hash(animation_short_source_payload(short))


def animation_short_plan_fingerprint(plan: dict[str, object]) -> str:
    shorts = plan.get("shorts") if isinstance(plan.get("shorts"), list) else []
    payload = {
        "course_title": plan.get("course_title"),
        "shorts": [animation_short_source_payload(short) for short in shorts if isinstance(short, dict)],
    }
    return canonical_json_hash(payload)


def animation_plan_fingerprint(plan: dict[str, object]) -> str:
    return canonical_json_hash(plan)


def render_runtime_transition_contracts(animation_plan: dict[str, object]) -> list[dict[str, object]]:
    """Return the exact transition rows the strict runtime-trace consumer expects."""
    semantic_contract = (
        animation_plan.get("semantic_transition_contract")
        if isinstance(animation_plan.get("semantic_transition_contract"), dict)
        else {}
    )
    semantic_rows = semantic_contract.get("transitions") if isinstance(semantic_contract.get("transitions"), list) else []
    semantic_by_id = {
        str(row.get("id")): row
        for row in semantic_rows
        if isinstance(row, dict) and str(row.get("id", "")).strip()
    }
    contracts: list[dict[str, object]] = []
    seen: set[tuple[str, str]] = set()
    beats = animation_plan.get("beats") if isinstance(animation_plan.get("beats"), list) else []
    for beat in beats:
        if not isinstance(beat, dict):
            continue
        beat_id = str(beat.get("id", "")).strip()
        arc_phase = str(beat.get("arc_phase", "")).strip()
        beat_duration = max(0.0, float(beat.get("duration", 0.0) or 0.0))
        motion_evidence_required = beat_duration >= 5.0 or arc_phase == "resolve"
        evidence = beat.get("evidence") if isinstance(beat.get("evidence"), dict) else {}
        before_seconds = evidence.get("before_seconds")
        after_seconds = evidence.get("after_seconds")
        transition_windows = {
            str(window.get("planned_transition_id")): window
            for window in evidence.get("transition_windows", [])
            if isinstance(window, dict) and str(window.get("planned_transition_id", "")).strip()
        }
        transition_ids = beat.get("semantic_transition_ids")
        if not isinstance(transition_ids, list):
            transition_ids = evidence.get("semantic_transition_ids")
        transition_ids = [str(value) for value in transition_ids] if isinstance(transition_ids, list) else []
        state_delta = beat.get("state_delta") if isinstance(beat.get("state_delta"), dict) else {}
        delta_before = state_delta.get("before") if isinstance(state_delta.get("before"), dict) else {}
        delta_after = state_delta.get("after") if isinstance(state_delta.get("after"), dict) else {}
        changed_ids = (
            [str(value) for value in state_delta.get("changed_object_ids", [])]
            if isinstance(state_delta.get("changed_object_ids"), list)
            else []
        )
        use_transition_subwindows = (
            bool(transition_ids)
            and semantic_contract.get("family") == "geometry"
        )
        if arc_phase == "transform" and beat_id and changed_ids and not use_transition_subwindows:
            key = (beat_id, beat_id)
            if (
                key not in seen
                and len(changed_ids) == len(set(changed_ids))
                and set(changed_ids).issubset(delta_before)
                and set(changed_ids).issubset(delta_after)
                and all(delta_before[object_id] != delta_after[object_id] for object_id in changed_ids)
            ):
                seen.add(key)
                contracts.append(
                    {
                        "beat_id": beat_id,
                        "planned_transition_id": beat_id,
                        "before_seconds": before_seconds,
                        "after_seconds": after_seconds,
                        "persistent_object_ids": changed_ids,
                        "changed_attribute": "state",
                        "observed_before": {object_id: delta_before[object_id] for object_id in changed_ids},
                        "observed_after": {object_id: delta_after[object_id] for object_id in changed_ids},
                        "arc_phase": arc_phase,
                        "motion_evidence_required": motion_evidence_required,
                    }
                )
                continue

        for transition_id in transition_ids:
            transition = semantic_by_id.get(transition_id)
            if not isinstance(transition, dict):
                continue
            observed_before = transition.get("before") if isinstance(transition.get("before"), dict) else {}
            observed_after = transition.get("after") if isinstance(transition.get("after"), dict) else {}
            persistent_ids = (
                [str(value) for value in transition.get("persistent_object_ids", [])]
                if isinstance(transition.get("persistent_object_ids"), list)
                else []
            )
            key = (beat_id, transition_id)
            if (
                key in seen
                or not observed_before
                or set(observed_before) != set(observed_after)
                or observed_before == observed_after
                or not set(observed_before).issubset(set(persistent_ids))
            ):
                continue
            seen.add(key)
            transition_window = transition_windows.get(transition_id, {})
            contract = {
                    "beat_id": beat_id,
                    "planned_transition_id": transition_id,
                    "before_seconds": transition_window.get("before_seconds", before_seconds),
                    "after_seconds": transition_window.get("after_seconds", after_seconds),
                    "persistent_object_ids": persistent_ids,
                    "changed_attribute": "state",
                    "observed_before": observed_before,
                    "observed_after": observed_after,
                    "arc_phase": arc_phase,
                    "motion_evidence_required": motion_evidence_required,
                }
            if transition_window:
                contract["transition_subwindow"] = True
            contracts.append(contract)

        if transition_ids:
            continue
        persistent_ids = (
            [str(value) for value in evidence.get("persistent_object_ids", [])]
            if isinstance(evidence.get("persistent_object_ids"), list)
            else []
        )
        start_state = beat.get("start_state") if isinstance(beat.get("start_state"), dict) else {}
        end_state = beat.get("end_state") if isinstance(beat.get("end_state"), dict) else {}
        changed_ids = [
            object_id
            for object_id in persistent_ids
            if object_id in start_state and object_id in end_state and start_state[object_id] != end_state[object_id]
        ]
        if arc_phase == "resolve" and not changed_ids and persistent_ids:
            resolution_id = persistent_ids[-1]
            resolution_before = str(start_state.get(resolution_id, "resolved result"))
            resolution_after = resolution_before + "; visual resolution complete"
            changed_ids = [resolution_id]
            start_state = {**start_state, resolution_id: resolution_before}
            end_state = {**end_state, resolution_id: resolution_after}
        if not beat_id or not changed_ids:
            continue
        key = (beat_id, beat_id)
        if key in seen:
            continue
        seen.add(key)
        contracts.append(
            {
                "beat_id": beat_id,
                "planned_transition_id": beat_id,
                "before_seconds": before_seconds,
                "after_seconds": after_seconds,
                "persistent_object_ids": persistent_ids,
                "changed_attribute": "state",
                "observed_before": {object_id: start_state[object_id] for object_id in changed_ids},
                "observed_after": {object_id: end_state[object_id] for object_id in changed_ids},
                "arc_phase": arc_phase,
                "motion_evidence_required": motion_evidence_required,
            }
        )
    return contracts


def render_runtime_semantic_transition_bindings(animation_plan: dict[str, object]) -> list[dict[str, str]]:
    """List every semantic transition ID that must be bound to renderer callbacks."""
    bindings: list[dict[str, str]] = []
    seen: set[tuple[str, str]] = set()
    beats = animation_plan.get("beats") if isinstance(animation_plan.get("beats"), list) else []
    for beat in beats:
        if not isinstance(beat, dict):
            continue
        beat_id = str(beat.get("id", "")).strip()
        evidence = beat.get("evidence") if isinstance(beat.get("evidence"), dict) else {}
        transition_ids = beat.get("semantic_transition_ids")
        if not isinstance(transition_ids, list):
            transition_ids = evidence.get("semantic_transition_ids")
        for value in transition_ids if isinstance(transition_ids, list) else []:
            transition_id = str(value).strip()
            key = (beat_id, transition_id)
            if not beat_id or not transition_id or key in seen:
                continue
            seen.add(key)
            bindings.append({"beat_id": beat_id, "planned_transition_id": transition_id})
    return bindings


def render_runtime_semantic_event_contracts(animation_plan: dict[str, object]) -> list[dict[str, object]]:
    """Return per-semantic-ID contracts retained beside the validator's beat rows."""
    semantic_contract = (
        animation_plan.get("semantic_transition_contract")
        if isinstance(animation_plan.get("semantic_transition_contract"), dict)
        else {}
    )
    semantic_rows = semantic_contract.get("transitions") if isinstance(semantic_contract.get("transitions"), list) else []
    semantic_by_id = {
        str(row.get("id")): row
        for row in semantic_rows
        if isinstance(row, dict) and str(row.get("id", "")).strip()
    }
    beat_by_id = {
        str(beat.get("id")): beat
        for beat in animation_plan.get("beats", [])
        if isinstance(beat, dict) and str(beat.get("id", "")).strip()
    }
    contracts: list[dict[str, object]] = []
    for binding in render_runtime_semantic_transition_bindings(animation_plan):
        beat = beat_by_id.get(binding["beat_id"])
        transition = semantic_by_id.get(binding["planned_transition_id"])
        if not isinstance(beat, dict) or not isinstance(transition, dict):
            continue
        evidence = beat.get("evidence") if isinstance(beat.get("evidence"), dict) else {}
        transition_window = next(
            (
                window for window in evidence.get("transition_windows", [])
                if isinstance(window, dict)
                and str(window.get("planned_transition_id", "")) == binding["planned_transition_id"]
            ),
            {},
        )
        before = transition.get("before") if isinstance(transition.get("before"), dict) else {}
        after = transition.get("after") if isinstance(transition.get("after"), dict) else {}
        persistent_ids = (
            [str(value) for value in transition.get("persistent_object_ids", [])]
            if isinstance(transition.get("persistent_object_ids"), list)
            else []
        )
        if (
            not before
            or set(before) != set(after)
            or before == after
            or not set(before).issubset(set(persistent_ids))
        ):
            continue
        contracts.append(
            {
                **binding,
                "before_seconds": transition_window.get("before_seconds", evidence.get("before_seconds")),
                "after_seconds": transition_window.get("after_seconds", evidence.get("after_seconds")),
                "persistent_object_ids": persistent_ids,
                "changed_attribute": "state",
                "observed_before": before,
                "observed_after": after,
                "motion_evidence_required": (
                    float(beat.get("duration", 0.0) or 0.0) >= 5.0
                    or str(beat.get("arc_phase", "")) == "resolve"
                ),
            }
        )
    return contracts


def render_execution_marker_errors(
    marker_payload: object,
    animation_plan: dict[str, object],
    *,
    short_index: int,
    require_transform_callbacks: bool = True,
) -> list[str]:
    """Validate renderer-emitted evidence before it can be bound to a video."""
    if not isinstance(marker_payload, dict):
        return ["renderer execution marker payload must be an object"]
    errors: list[str] = []
    plan_fingerprint = animation_plan_fingerprint(animation_plan)
    if marker_payload.get("schema_version") != RENDER_EXECUTION_MARKER_SCHEMA_VERSION:
        errors.append(f"marker schema_version must be {RENDER_EXECUTION_MARKER_SCHEMA_VERSION!r}")
    if marker_payload.get("short_index") != short_index:
        errors.append("marker short_index does not match the rendered short")
    if marker_payload.get("animation_plan_fingerprint") != plan_fingerprint:
        errors.append("marker animation_plan_fingerprint is missing or stale")
    if marker_payload.get("status") != "complete":
        errors.append("renderer did not complete its runtime marker stream")
    marker_errors = marker_payload.get("errors")
    if not isinstance(marker_errors, list):
        errors.append("marker errors must be an array")
    elif marker_errors:
        errors.extend(f"renderer marker: {str(message)}" for message in marker_errors[:4])

    expected_contracts = render_runtime_transition_contracts(animation_plan)
    authored_transition_beats = {
        str(binding.get("beat_id", ""))
        for binding in render_runtime_semantic_transition_bindings(animation_plan)
    }
    expected_by_key = {
        (str(contract["beat_id"]), str(contract["planned_transition_id"])): contract
        for contract in expected_contracts
    }
    raw_events = marker_payload.get("transitions")
    if not isinstance(raw_events, list):
        errors.append("marker transitions must be an array")
        raw_events = []
    events_by_key: dict[tuple[str, str], dict[str, object]] = {}
    event_fields = (
        "beat_id",
        "planned_transition_id",
        "persistent_object_ids",
        "changed_attribute",
        "observed_before",
        "observed_after",
    )
    for position, event in enumerate(raw_events, start=1):
        if not isinstance(event, dict):
            errors.append(f"marker event {position} is not an object")
            continue
        key = (str(event.get("beat_id", "")), str(event.get("planned_transition_id", "")))
        expected = expected_by_key.get(key)
        if expected is None:
            errors.append(f"marker event {position} is not a planned transition")
            continue
        if key in events_by_key:
            errors.append(f"marker event {position} duplicates transition {key[1]!r}")
            continue
        events_by_key[key] = event
        for field in event_fields:
            if canonical_json_hash(event.get(field)) != canonical_json_hash(expected.get(field)):
                errors.append(f"marker event {position} has stale {field}")
                break
        try:
            before_seconds = float(event.get("before_seconds"))
            after_seconds = float(event.get("after_seconds"))
            expected_before = float(expected.get("before_seconds"))
            expected_after = float(expected.get("after_seconds"))
        except (TypeError, ValueError):
            errors.append(f"marker event {position} has invalid renderer timing")
            continue
        if not math.isfinite(before_seconds) or not math.isfinite(after_seconds):
            errors.append(f"marker event {position} has non-finite renderer timing")
            continue
        if round(before_seconds * RENDER_TIMELINE_FPS) != round(expected_before * RENDER_TIMELINE_FPS):
            errors.append(f"marker event {position} before_seconds does not match the renderer evidence marker")
        after_frame_delta = abs(
            round(after_seconds * RENDER_TIMELINE_FPS)
            - round(expected_after * RENDER_TIMELINE_FPS)
        )
        after_frame_allowance = 1 if key[0] in authored_transition_beats else 0
        if after_frame_delta > after_frame_allowance:
            errors.append(f"marker event {position} after_seconds does not match the renderer evidence marker")

        renderer_markers = event.get("renderer_markers")
        if not isinstance(renderer_markers, list):
            errors.append(f"marker event {position} lacks renderer_markers")
        else:
            marker_times = {
                str(marker.get("phase")): marker.get("renderer_seconds")
                for marker in renderer_markers
                if isinstance(marker, dict)
            }
            for phase, expected_time in (("before", expected_before), ("after", expected_after)):
                try:
                    marker_time = float(marker_times[phase])
                except (KeyError, TypeError, ValueError):
                    errors.append(f"marker event {position} lacks its {phase} renderer marker")
                    continue
                marker_frame_delta = abs(
                    round(marker_time * RENDER_TIMELINE_FPS)
                    - round(expected_time * RENDER_TIMELINE_FPS)
                )
                marker_frame_allowance = (
                    1 if phase == "after" and key[0] in authored_transition_beats else 0
                )
                if marker_frame_delta > marker_frame_allowance:
                    errors.append(f"marker event {position} has stale {phase} renderer marker timing")

        execution_records = event.get("execution_records")
        if not isinstance(execution_records, list):
            errors.append(f"marker event {position} execution_records must be an array")
            execution_records = []
        valid_callbacks = []
        for record in execution_records:
            if not isinstance(record, dict) or record.get("kind") != "callback" or record.get("status") != "ok":
                continue
            try:
                started = float(record.get("started_seconds"))
                finished = float(record.get("finished_seconds"))
            except (TypeError, ValueError):
                continue
            if (
                math.isfinite(started)
                and math.isfinite(finished)
                and round(expected_before * RENDER_TIMELINE_FPS)
                <= round(started * RENDER_TIMELINE_FPS)
                <= round(finished * RENDER_TIMELINE_FPS)
                <= round(expected_after * RENDER_TIMELINE_FPS)
            ):
                valid_callbacks.append(record)
        if require_transform_callbacks and expected.get("arc_phase") == "transform" and not valid_callbacks:
            errors.append(f"marker event {position} has no successful renderer callback for a required transform")
        qualifying_intervals = [
            interval
            for record in valid_callbacks
            for interval in record.get("choreography_intervals", [])
            if isinstance(interval, dict) and interval.get("qualifying_motion")
        ]
        if expected.get("motion_evidence_required") and not qualifying_intervals:
            errors.append(
                f"marker event {position} has no qualifying motion evidence for a long/resolve beat"
            )

    missing = set(expected_by_key) - set(events_by_key)
    if missing:
        labels = ", ".join(sorted(transition_id for _beat_id, transition_id in missing)[:4])
        errors.append(f"renderer marker stream omits {len(missing)} planned transitions ({labels})")

    expected_bindings = {
        (binding["beat_id"], binding["planned_transition_id"])
        for binding in render_runtime_semantic_transition_bindings(animation_plan)
    }
    raw_bindings = marker_payload.get("semantic_transition_bindings")
    if not isinstance(raw_bindings, list):
        errors.append("semantic_transition_bindings must be an array")
        raw_bindings = []
    actual_bindings: set[tuple[str, str]] = set()
    successful_records_by_id: collections.Counter[str] = collections.Counter()
    for event in raw_events:
        if not isinstance(event, dict):
            continue
        for record in event.get("execution_records", []):
            if (
                isinstance(record, dict)
                and record.get("kind") == "callback"
                and record.get("status") == "ok"
                and str(record.get("declared_transition_id", "")).strip()
            ):
                successful_records_by_id[str(record["declared_transition_id"])] += 1
    for position, binding in enumerate(raw_bindings, start=1):
        if not isinstance(binding, dict):
            errors.append(f"semantic binding {position} is not an object")
            continue
        key = (str(binding.get("beat_id", "")), str(binding.get("planned_transition_id", "")))
        if key not in expected_bindings:
            errors.append(f"semantic binding {position} is not planned")
            continue
        if key in actual_bindings:
            errors.append(f"semantic binding {position} duplicates transition {key[1]!r}")
            continue
        actual_bindings.add(key)
        registered_count = binding.get("registered_callback_count")
        executed_count = binding.get("executed_callback_count")
        if (
            not isinstance(registered_count, int)
            or registered_count <= 0
            or executed_count != registered_count
            or binding.get("status") != "ok"
            or successful_records_by_id[key[1]] != registered_count
        ):
            errors.append(f"semantic binding {position} is not backed by exactly one execution of every registered callback")
    missing_bindings = expected_bindings - actual_bindings
    if missing_bindings:
        labels = ", ".join(sorted(transition_id for _beat_id, transition_id in missing_bindings)[:4])
        errors.append(f"renderer marker stream omits {len(missing_bindings)} semantic callback bindings ({labels})")
    return list(dict.fromkeys(errors))


def build_render_runtime_trace_row(
    *,
    short_index: int,
    video_file: str,
    video_path: Path,
    animation_plan: dict[str, object],
    marker_payload: object,
) -> dict[str, object]:
    """Hash-bind a validated Manim marker stream to the finalized video."""
    errors = render_execution_marker_errors(
        marker_payload,
        animation_plan,
        short_index=short_index,
        require_transform_callbacks=True,
    )
    if errors:
        raise ValueError("Invalid renderer execution markers: " + "; ".join(errors))
    if not isinstance(marker_payload, dict):
        raise ValueError("Invalid renderer execution marker payload")
    if marker_payload.get("render_mode") != "production":
        raise ValueError("Only production renderer markers may be bound to a final video")
    if not video_path.exists() or not video_path.is_file():
        raise ValueError(f"Final video is missing: {video_path}")

    actual_events = {
        (str(event.get("beat_id")), str(event.get("planned_transition_id"))): event
        for event in marker_payload.get("transitions", [])
        if isinstance(event, dict)
    }
    transitions: list[dict[str, object]] = []
    public_fields = (
        "beat_id",
        "planned_transition_id",
        "before_seconds",
        "after_seconds",
        "persistent_object_ids",
        "changed_attribute",
        "observed_before",
        "observed_after",
        "renderer_markers",
        "execution_records",
        "timing_source",
    )
    for contract in render_runtime_transition_contracts(animation_plan):
        key = (str(contract["beat_id"]), str(contract["planned_transition_id"]))
        event = actual_events[key]
        transitions.append({field: event.get(field) for field in public_fields if field in event})
    semantic_transition_events = []
    for contract in render_runtime_semantic_event_contracts(animation_plan):
        beat_id = str(contract["beat_id"])
        transition_id = str(contract["planned_transition_id"])
        source_event = actual_events.get((beat_id, transition_id)) or actual_events.get((beat_id, beat_id))
        if source_event is None:
            source_event = next(
                (event for key, event in actual_events.items() if key[0] == beat_id),
                None,
            )
        if not isinstance(source_event, dict):
            raise ValueError(f"Renderer markers omit semantic transition {transition_id!r}")
        callback_records = [
            record
            for record in source_event.get("execution_records", [])
            if isinstance(record, dict) and str(record.get("declared_transition_id", "")) == transition_id
        ]
        semantic_transition_events.append(
            {
                **contract,
                "before_seconds": source_event.get("before_seconds"),
                "after_seconds": source_event.get("after_seconds"),
                "renderer_markers": list(source_event.get("renderer_markers", [])),
                "execution_records": callback_records,
                "timing_source": source_event.get("timing_source"),
            }
        )
    return {
        "short_index": short_index,
        "video_file": video_file,
        "video_sha256": file_sha256(video_path),
        "animation_plan_fingerprint": animation_plan_fingerprint(animation_plan),
        "transitions": transitions,
        "semantic_transition_events": semantic_transition_events,
        "semantic_transition_bindings": list(marker_payload.get("semantic_transition_bindings", [])),
        "proof_surface_holds": list(marker_payload.get("proof_surface_holds", [])),
    }


def render_runtime_trace_payload(
    animation_plan_index: dict[str, object],
    render_rows: list[dict[str, object]],
) -> dict[str, object]:
    return {
        "schema_version": RENDER_RUNTIME_TRACE_SCHEMA_VERSION,
        "animation_plan_index_fingerprint": canonical_json_hash(animation_plan_index),
        "renders": render_rows,
    }


def animation_plan_relative_path(index: int) -> str:
    return f"{ANIMATION_PLAN_DIRECTORY}/short_{index:02d}.json"


def animation_family_for_kind(visual_kind: str) -> str:
    if visual_kind in ANIMATION_LINEAR_KINDS:
        return "linear-algebra"
    if visual_kind in ANIMATION_GROUP_KINDS:
        return "algebra-and-groups"
    if visual_kind in ANIMATION_CS_KINDS or visual_kind in ANIMATION_STATE_MACHINE_KINDS:
        return "algorithms-and-cs"
    if visual_kind in ANIMATION_PHYSICS_KINDS:
        return "physics"
    if visual_kind in ANIMATION_ECON_KINDS:
        return "economics"
    if visual_kind in ANIMATION_CALCULUS_KINDS:
        return "calculus"
    if visual_kind in ANIMATION_PROBABILITY_KINDS:
        return "probability"
    if visual_kind in ANIMATION_CHEMISTRY_KINDS:
        return "chemistry"
    if visual_kind in ANIMATION_GEOMETRY_KINDS:
        return "geometry"
    return "symbolic-relation"


def animation_cue(value: object, width: int = 104) -> str:
    text = re.sub(r"\s+", " ", screen_prose(value)).strip()
    if not text:
        return "The state change is explicit."
    return learner_facing_screen_copy(text, max_words=max(8, width // 6)).rstrip(" ,;:")


def animation_plan_visible_cue(value: object) -> tuple[str, list[str]]:
    raw = re.sub(r"\s+", " ", str(value)).strip()
    formula_atomic = bool(
        re.search(r"(?:\\[A-Za-z]+|[_^{}]|<=|>=|->|→|=)", raw)
        and not storyboard_instruction_leak(raw)
    )
    text = (
        formula_unicode_text(raw)
        if formula_atomic
        else learner_facing_screen_copy(
            raw,
            max_words=min(10, ANIMATION_PLAN_MAX_CUE_WORDS),
        )
    ).rstrip(" ,;:")
    if text and not re.search(r"[.!?]$", text):
        text += "."
    cue_width = max(42, math.ceil(len(text) / ANIMATION_PLAN_MAX_CUE_LINES))
    lines = textwrap.wrap(text, width=cue_width, break_long_words=False, break_on_hyphens=False) or [""]
    while len(lines) > ANIMATION_PLAN_MAX_CUE_LINES:
        cue_width += 4
        lines = textwrap.wrap(text, width=cue_width, break_long_words=False, break_on_hyphens=False) or [""]
    stranded_words = {"and", "at", "by", "for", "from", "in", "of", "on", "or", "the", "to", "with"}
    for index in range(len(lines) - 1):
        words = lines[index].split()
        if words and words[-1].rstrip(".,;:").casefold() in stranded_words:
            lines[index] = " ".join(words[:-1])
            lines[index + 1] = words[-1] + " " + lines[index + 1]
    return text, lines


def animation_state_delta(
    start_state: dict[str, str],
    end_state: dict[str, str],
) -> dict[str, object]:
    object_ids = list(dict.fromkeys([*start_state, *end_state]))
    changed = [
        object_id
        for object_id in object_ids
        if start_state.get(object_id) != end_state.get(object_id)
    ]
    return {
        "before": dict(start_state),
        "after": dict(end_state),
        "changed_object_ids": changed,
    }


UNSUPPORTED_ROUTE_BLUEPRINT = animation_route_blueprint(
    "unclassified relation frame",
    "unclassified input object",
    "unclassified operation",
    "unclassified result",
    "No publishable mechanism exists until a semantic renderer is selected.",
    "Do not substitute a generic input-output animation for a missing domain model.",
    "No invariant has been established for this unsupported route.",
)


def concrete_state_machine_route(short: dict[str, object]) -> bool:
    text = short_text(short).lower()
    worked = short.get("worked_example") if isinstance(short.get("worked_example"), dict) else {}
    example = f"{worked.get('setup', '')} {worked.get('calculation', '')}".lower()
    automaton_marker = any(
        marker in text
        for marker in ("automaton", "state machine", "finite state", "dfa", "nfa", "transition table")
    )
    transition_marker = bool(re.search(r"(?:->|→|\btransition\b|\bon input\b|\bmoves? from\b)", example))
    named_states = set(re.findall(r"\bq\d+\b", example))
    named_states.update(
        token
        for token in ("start", "accept", "reject", "idle", "running", "locked", "unlocked", "open", "closed")
        if re.search(rf"\b{token}\b", example)
    )
    explicit_state_set = re.search(r"(?:states?|q)\s*(?:=|:)\s*\{?\s*([a-z0-9_]+(?:\s*,\s*[a-z0-9_]+)+)", example)
    if explicit_state_set:
        named_states.update(re.findall(r"[a-z0-9_]+", explicit_state_set.group(1)))
    return automaton_marker and transition_marker and len(named_states) >= 2


def animation_route_descriptor(short: dict[str, object], visual_kind: str | None = None) -> dict[str, object]:
    kind = visual_kind or infer_visual_kind(short)
    renderer_state = None
    renderer_error = None
    exact_group_route = resolve_group_video_model(str(short.get("concept", "")), fail_closed=False)
    if exact_group_route is not None:
        try:
            renderer_state = animation_renderer_state(short, kind)
        except (TypeError, ValueError) as exc:
            renderer_error = str(exc)
        semantic_mode = exact_group_route.visual_family
        route_key = exact_group_route.route_key
    elif kind in ALGEBRA_VISUAL_KINDS:
        try:
            renderer_state = animation_renderer_state(short, kind)
        except (TypeError, ValueError) as exc:
            renderer_error = str(exc)
        semantic_mode = str(renderer_state.get("mode", "")) if isinstance(renderer_state, dict) else ""
        route_key = str(renderer_state.get("route_key", "algebra:unsupported")) if isinstance(renderer_state, dict) else "algebra:unsupported"
    elif kind in ANIMATION_CS_KINDS:
        try:
            renderer_state = animation_renderer_state(short, kind)
        except (TypeError, ValueError) as exc:
            renderer_error = str(exc)
        semantic_family = str(renderer_state.get("family", "")) if isinstance(renderer_state, dict) else ""
        semantic_mode = str(renderer_state.get("mode", "")) if isinstance(renderer_state, dict) else ""
        explicit_route_key = str(renderer_state.get("route_key", "")) if isinstance(renderer_state, dict) else ""
        if explicit_route_key:
            route_key = explicit_route_key
        elif semantic_family in {"graph", "dp"} and semantic_mode:
            public_mode = semantic_mode
            if semantic_family == "graph" and renderer_state.get("trace_mode") == "johnson":
                public_mode = "johnson"
            elif semantic_family == "dp" and renderer_state.get("trace_mode") == "fibonacci_memo":
                public_mode = "fibonacci_table"
            route_key = f"cs:{semantic_family}:{public_mode}"
        else:
            route_key = f"cs:{semantic_family}" if semantic_family else "cs:unsupported"
    elif kind in ANIMATION_PHYSICS_KINDS:
        try:
            renderer_state = animation_renderer_state(short, kind)
        except (TypeError, ValueError) as exc:
            renderer_error = str(exc)
        semantic_mode = str(renderer_state.get("mode", "")) if isinstance(renderer_state, dict) else ""
        route_key = str(renderer_state.get("route_key", kind)) if isinstance(renderer_state, dict) else kind
        exact_title_route = MIT_8_01_VIDEO_ROUTES.get(str(short.get("concept", "")).strip())
        renderer_model_id = str(renderer_state.get("model_id", "")) if isinstance(renderer_state, dict) else ""
        if exact_title_route is not None and renderer_model_id != exact_title_route.model_id:
            exact_title_route = None
        if exact_title_route is not None:
            route_key = exact_title_route.route_key
            if isinstance(renderer_state, dict):
                renderer_state["route_key"] = route_key
                renderer_state["exact_route_key"] = route_key
                semantic_mode = str(renderer_state.get("scenario_mode", exact_title_route.scenario_mode))
        # Older non-exact inputs retain their public renderer aliases.
        public_legacy_plan = bool(short.get("key_concept"))
        model_id = str(renderer_state.get("model_id", "")) if isinstance(renderer_state, dict) else ""
        if exact_title_route is None and public_legacy_plan and model_id == "work_energy_multidimensional":
            route_key = "physics_work"
        elif exact_title_route is None and public_legacy_plan and model_id == "vectors":
            route_key = "physics_vectors"
        elif exact_title_route is None and public_legacy_plan and model_id == "uniform_circular_motion":
            route_key = "physics_circular_motion"
    elif kind in ANIMATION_ECON_KINDS:
        try:
            renderer_state = animation_renderer_state(short, kind)
        except (TypeError, ValueError) as exc:
            renderer_error = str(exc)
        semantic_mode = str(renderer_state.get("family", "")) if isinstance(renderer_state, dict) else ""
        route_key = str(renderer_state.get("route_key", kind)) if isinstance(renderer_state, dict) else kind
    elif kind == "state_machine":
        semantic_mode = "automaton" if concrete_state_machine_route(short) else "generic"
        route_key = "state_machine:automaton" if concrete_state_machine_route(short) else "state_machine:generic"
    else:
        semantic_mode = ""
        route_key = kind
    blueprint = ANIMATION_ROUTE_BLUEPRINTS.get(route_key)
    implementation = VIDEO_RENDERER_IMPLEMENTATIONS.get(route_key)
    registered_kind = str(implementation.get("visual_kind", "")) if implementation else ""
    supported = implementation is not None and registered_kind == kind and blueprint is not None
    if kind == "state_machine" and route_key != "state_machine:automaton":
        supported = False
    if supported and renderer_state is None:
        try:
            renderer_state = animation_renderer_state(short, kind)
        except (TypeError, ValueError) as exc:
            supported = False
            renderer_error = str(exc)
    if kind == "numeric_rule":
        reason = "numeric_rule is a diagnostic fallback, not a publishable semantic renderer"
    elif kind == "state_machine" and not supported:
        reason = "state_machine requires a concrete automaton with named states and explicit transitions"
    elif blueprint is None:
        reason = f"no animation route blueprint exists for {route_key}"
    elif implementation is None:
        reason = f"no video renderer implementation is registered for {route_key}"
    elif registered_kind != kind:
        reason = f"video route {route_key} is registered for {registered_kind}, not {kind}"
    elif renderer_error:
        reason = f"worked example cannot produce route-specific renderer state: {renderer_error}"
    else:
        reason = None
    return {
        "visual_kind": kind,
        "route_key": route_key,
        "semantic_mode": semantic_mode,
        "supported": supported,
        "reason": reason,
        "blueprint": blueprint or UNSUPPORTED_ROUTE_BLUEPRINT,
        "renderer_state": renderer_state,
        "renderer_implementation": implementation,
    }


def animation_renderer_state(short: dict[str, object], visual_kind: str) -> dict[str, object]:
    data = visual_data_for(short, visual_kind)
    economics = data.get("economics")
    if isinstance(economics, dict) and isinstance(economics.get("video_payload"), dict):
        return dict(economics["video_payload"])
    for key in ("group", "cs", "physics", "algebra", "matrix_vector", "vector", "linear_combo", "geometry"):
        value = data.get(key)
        if isinstance(value, dict):
            if key == "cs" and value.get("trace_mode") == "fibonacci_memo" and isinstance(value.get("memo_trace"), dict):
                memo_trace = dict(value["memo_trace"])
                memo_trace.update({
                    "mode": "fibonacci_memo",
                    "trace_mode": "fibonacci_memo",
                    "route_key": str(value.get("route_key", "cs:dp:fibonacci_table")),
                    "legacy_renderer_payload": value,
                    "formula_latex": value.get("formula_latex", memo_trace.get("formula_latex")),
                    "formula_text": value.get("formula_text", memo_trace.get("formula_text")),
                })
                return {"payload_type": key, **memo_trace}
            renderer_state = {"payload_type": key, **value}
            if key == "physics" and not renderer_state.get("exact_title"):
                validate_physics_renderer_values(visual_kind, renderer_state)
            return renderer_state
    worked = data.get("worked_example") if isinstance(data.get("worked_example"), dict) else {}
    return {
        "payload_type": visual_kind,
        "values": data.get("numbers", []),
        "setup": worked.get("setup", ""),
        "calculation": worked.get("calculation", ""),
        "takeaway": worked.get("takeaway", ""),
    }


def semantic_plan_contract(renderer_state: dict[str, object]) -> dict[str, object] | None:
    """Translate renderer state into exact persistent objects and transitions."""
    if renderer_state.get("payload_type") == "group_theory":
        errors = validate_group_video_payload(renderer_state)
        if errors:
            raise ValueError("Invalid group semantic renderer state: " + "; ".join(errors))
        physics_colors = ("#58A6FF", "#EAF2FF", "#F7C948", "#A371F7", "#7EE787", "#FF8C69")
        objects = [
            {**dict(row), "color": str(row.get("color") or physics_colors[index % len(physics_colors)])}
            for index, row in enumerate(renderer_state["objects"])
            if isinstance(row, dict)
        ]
        transitions = [dict(row) for row in renderer_state["transitions"] if isinstance(row, dict)]
        return {
            "family": "group_theory",
            "mode": str(renderer_state.get("family", "")),
            "route_key": str(renderer_state.get("route_key", "")),
            "mechanism": str(renderer_state.get("topic_domain", "")),
            "numeric_evidence_fingerprint": canonical_json_hash({
                "worked_example": renderer_state.get("worked_example"),
                "final_state": renderer_state.get("reveal_contract", {}).get("final_state", {}),
            }),
            "anchor_id": str(objects[0]["id"]),
            "subject_id": str(renderer_state.get("subject_id") or objects[0]["id"]),
            "invariant": str(renderer_state.get("invariant", "")),
            "objects": objects,
            "transitions": transitions,
        }
    if renderer_state.get("payload_type") == "geometry" and renderer_state.get("family") == "sphere_surface_area":
        objects = [dict(row) for row in renderer_state.get("objects", []) if isinstance(row, dict)]
        transitions = [dict(row) for row in renderer_state.get("transitions", []) if isinstance(row, dict)]
        if not objects or len(transitions) != 10:
            raise ValueError("Sphere geometry requires a persistent object roster and exactly ten transitions.")
        expected_before: dict[str, str] = {
            str(row["id"]): str(row.get("initial_state", "")) for row in objects
        }
        for transition in transitions:
            before = transition.get("before") if isinstance(transition.get("before"), dict) else {}
            after = transition.get("after") if isinstance(transition.get("after"), dict) else {}
            if not before or set(before) != set(after):
                raise ValueError(f"Sphere transition {transition.get('id')} must have matching before/after objects.")
            for object_id, before_state in before.items():
                if expected_before.get(str(object_id)) != str(before_state):
                    raise ValueError(f"Sphere transition {transition.get('id')} does not chain from the prior state of {object_id}.")
            expected_before.update({str(key): str(value) for key, value in after.items()})
        return {
            "family": "geometry",
            "mode": str(renderer_state.get("mode", "latitude_band_projection")),
            "anchor_id": "sphere:proof-surface",
            "subject_id": "sphere:latitude-bands",
            "invariant": str(renderer_state.get("invariant", "")),
            "objects": objects,
            "transitions": transitions,
        }
    if renderer_state.get("payload_type") == "economics":
        errors = validate_economics_video_payload(renderer_state)
        if errors:
            raise ValueError("Invalid economics semantic renderer state: " + "; ".join(errors))
        physics_colors = ("#58A6FF", "#EAF2FF", "#F7C948", "#A371F7", "#7EE787", "#FF8C69")
        objects = [
            {**dict(row), "color": str(row.get("color") or physics_colors[index % len(physics_colors)])}
            for index, row in enumerate(renderer_state["objects"])
            if isinstance(row, dict)
        ]
        transitions = [dict(row) for row in renderer_state["transitions"] if isinstance(row, dict)]
        return {
            "family": str(renderer_state.get("family", "economics")),
            "mode": str(renderer_state.get("family", "")),
            "anchor_id": str(objects[0]["id"]),
            "subject_id": str(objects[-1]["id"]),
            "invariant": str(renderer_state.get("invariant", "")),
            "objects": objects,
            "transitions": transitions,
        }
    if renderer_state.get("payload_type") == "physics" and isinstance(renderer_state.get("objects"), list):
        typed_payload = (
            renderer_state.get("exact_semantic_payload")
            if isinstance(renderer_state.get("exact_semantic_payload"), dict)
            else renderer_state
        )
        errors = validate_physics_video_payload(typed_payload)
        if errors:
            raise ValueError("Invalid physics semantic renderer state: " + "; ".join(errors))
        physics_colors = ("#58A6FF", "#EAF2FF", "#F7C948", "#A371F7", "#7EE787", "#FF8C69")
        objects = [
            {**dict(row), "color": str(row.get("color") or physics_colors[index % len(physics_colors)])}
            for index, row in enumerate(renderer_state["objects"])
            if isinstance(row, dict)
        ]
        subject_id = str(renderer_state.get("subject_id") or objects[0]["id"])
        transitions = [dict(row) for row in renderer_state["transitions"] if isinstance(row, dict)]
        if len(transitions) == 3:
            prior = transitions[-1]
            before = dict(prior["after"])
            after = dict(before)
            after[subject_id] = f"{after[subject_id]}; invariant verified"
            transitions.append({
                "id": f"{renderer_state.get('family', 'physics')}:verify_invariant",
                "kind": "verify_invariant",
                "claim": str(renderer_state.get("invariant", "Verify the physical invariant.")),
                "action": "Keep the same physical objects visible and verify the scenario invariant.",
                "persistent_object_ids": list(before),
                "before": before,
                "after": after,
                "evidence_tokens": [str(renderer_state.get("canonical_formula", ""))],
            })
        return {
            "family": str(renderer_state.get("family", "physics")),
            "mode": str(renderer_state.get("family", "")),
            "route_key": str(renderer_state.get("route_key", "")),
            "mechanism": ", ".join(str(value) for value in renderer_state.get("mechanisms", [])),
            "numeric_evidence_fingerprint": str(renderer_state.get("numeric_evidence_fingerprint", "")),
            "anchor_id": subject_id,
            "subject_id": subject_id,
            "invariant": str(renderer_state.get("invariant", "")),
            "objects": objects,
            "transitions": transitions,
        }
    if renderer_state.get("payload_type") == "algebra":
        errors = validate_algebra_video_payload(renderer_state)
        if errors:
            raise ValueError("Invalid algebra semantic renderer state: " + "; ".join(errors))
        objects = [dict(row) for row in renderer_state.get("objects", []) if isinstance(row, dict)]
        transitions = [dict(row) for row in renderer_state.get("transitions", []) if isinstance(row, dict)]
        return {
            "family": str(renderer_state.get("family", "algebra")),
            "mode": str(renderer_state.get("mode", "")),
            "anchor_id": str(objects[0]["id"]),
            "subject_id": str(renderer_state.get("subject_id") or objects[1]["id"]),
            "invariant": str(renderer_state.get("invariant", "")),
            "objects": objects,
            "transitions": transitions,
        }
    if renderer_state.get("payload_type") != "cs":
        return None
    family = str(renderer_state.get("family", ""))
    mode = str(renderer_state.get("mode", ""))
    invariant = str(renderer_state.get("invariant", "")).strip()
    transitions: list[dict[str, object]] = []
    objects: dict[str, dict[str, object]] = {}

    def remember(object_id: str, role: str, color: str = "#EAF2FF") -> None:
        if object_id and object_id not in objects:
            objects[object_id] = {
                "id": object_id,
                "role": role,
                "color": color,
                "initial_state": "visible in the renderer's persistent semantic state",
                "persistent": True,
            }

    if family == "divide" and mode == "recursion_tree":
        anchor_id = "cs:divide:recursion-tree"
        total_id = "cs:divide:level-total"
        remember(anchor_id, "persistent recursion tree", "#58A6FF")
        remember(total_id, "accumulated work across recursion levels", "#F7C948")
        for node in renderer_state.get("nodes", []):
            if isinstance(node, dict):
                remember(str(node.get("id", "")), f"size-{node.get('size')} subproblem", "#8FD3FF")
        for level in renderer_state.get("levels", []):
            if not isinstance(level, dict):
                continue
            level_number = int(level.get("level", 0))
            node_ids = [str(value) for value in level.get("node_ids", [])]
            transitions.append({
                "id": f"divide:level:{level_number}",
                "kind": "accumulate_recursion_level",
                "claim": f"Level {level_number} contributes {level.get('level_work')} work.",
                "action": f"Reveal and retain its {level.get('subproblem_count')} subproblems, then add the level total.",
                "persistent_object_ids": [anchor_id, total_id, *node_ids],
                "before": {total_id: f"{max(0, level_number) * int(renderer_state.get('n', 0))} accumulated work"},
                "after": {total_id: f"{level.get('accumulated_work')} accumulated work"},
                "evidence_tokens": [str(level.get("subproblem_count")), str(level.get("subproblem_size")), str(level.get("level_work"))],
            })
        transitions.append({
            "id": "divide:resolve",
            "kind": "resolve_recurrence",
            "claim": "Equal linear work across logarithmically many levels resolves the recurrence.",
            "action": "Combine the persistent level totals into T(n)=Theta(n log n).",
            "persistent_object_ids": [anchor_id, total_id],
            "before": {total_id: f"{renderer_state.get('total_work')} concrete work at n={renderer_state.get('n')}"},
            "after": {total_id: str(renderer_state.get("resolution", "Theta(n log n)"))},
            "evidence_tokens": [str(renderer_state.get("recurrence")), str(renderer_state.get("resolution"))],
        })
    elif family == "sort" and mode == "counting":
        anchor_id = "cs:counting:buckets"
        output_id = "cs:counting:output"
        remember(anchor_id, "persistent counting buckets", "#F7C948")
        remember(output_id, "stable counting-sort output slots", "#7EE787")
        for bucket in renderer_state.get("buckets", []):
            if not isinstance(bucket, dict):
                continue
            bucket_id = str(bucket.get("bucket_id", ""))
            remember(bucket_id, f"count bucket for key {bucket.get('key')}", "#F7C948")
        for item in renderer_state.get("items", []):
            if not isinstance(item, dict):
                continue
            item_id = str(item.get("item_id", ""))
            remember(item_id, f"input item {item.get('input_index')} with key {item.get('value')}", "#58A6FF")
        for index, step in enumerate(renderer_state.get("operations", []), start=1):
            if not isinstance(step, dict):
                continue
            item_id = str(step.get("item_id", ""))
            bucket_id = str(step.get("bucket_id", ""))
            input_index = int(step.get("input_index", index - 1))
            key = int(step.get("key", 0))
            count = list(step.get("counts", []))[key]
            transitions.append({
                "id": str(step.get("transition_id") or f"counting:count:{input_index}"),
                "kind": "count_item",
                "claim": f"Count input item {item_id} in key-{key} bucket without replacing its identity.",
                "action": f"Trace {item_id} from input index {input_index} to {bucket_id}; update its visible count to {count}.",
                "persistent_object_ids": [anchor_id, bucket_id, item_id],
                "before": {item_id: f"input index {input_index}, uncounted"},
                "after": {item_id: f"counted in {bucket_id}"},
                "evidence_tokens": [item_id, bucket_id, str(count)],
            })
        for step in renderer_state.get("prefix_steps", []):
            if not isinstance(step, dict):
                continue
            key = int(step.get("key", 0))
            bucket_id = str(step.get("bucket_id", ""))
            start = int(step.get("start", 0))
            transitions.append({
                "id": str(step.get("transition_id") or f"counting:prefix:{key}"),
                "kind": "prefix_output_start",
                "claim": f"The exclusive prefix before key {key} reserves output slot {start} for its first item.",
                "action": f"Accumulate earlier bucket counts and replace {bucket_id}'s count view with start[{key}]={start}.",
                "persistent_object_ids": [anchor_id, bucket_id, output_id],
                "before": {bucket_id: f"count={step.get('count')}"},
                "after": {bucket_id: f"stable output start={start}"},
                "evidence_tokens": [str(step.get("formula", "")), str(start)],
            })
        for index, placement in enumerate(renderer_state.get("placements", []), start=1):
            if not isinstance(placement, dict):
                continue
            item_id = str(placement.get("item_id", ""))
            bucket_id = str(placement.get("bucket_id", ""))
            input_index = int(placement.get("input_index", index - 1))
            output_index = int(placement.get("output_index", index - 1))
            transitions.append({
                "id": str(placement.get("transition_id") or f"counting:place:{input_index}"),
                "kind": "stable_output_placement",
                "claim": f"Place {item_id} in unique output slot {output_index} while preserving duplicate order.",
                "action": f"Move the same persistent item {item_id} from {bucket_id} into output slot {output_index}.",
                "persistent_object_ids": [output_id, bucket_id, item_id],
                "before": {item_id: f"counted in {bucket_id}"},
                "after": {item_id: f"stable output index {output_index}"},
                "evidence_tokens": [item_id, bucket_id, str(output_index)],
            })
    elif family == "sort" and mode == "merge":
        anchor_id = "cs:merge:proof-surface"
        partition_id = "cs:merge:run-partition"
        identity_check_id = "cs:merge:identity-check"
        order_check_id = "cs:merge:order-check"
        remember(anchor_id, "persistent split-and-merge proof surface", "#58A6FF")
        remember(partition_id, "persistent partition of the same item identities into sorted runs", "#F7C948")
        remember(identity_check_id, "identity-preservation check across every merge level", "#8FD3FF")
        remember(order_check_id, "final nondecreasing-order check", "#7EE787")
        items = [item for item in renderer_state.get("items", []) if isinstance(item, dict)]
        item_ids = []
        for item in items:
            item_id = f"cs:merge:item:{int(item.get('id', len(item_ids)))}"
            item_ids.append(item_id)
            remember(item_id, f"input item {item.get('id')} with value {item.get('value')}", "#EAF2FF")

        def merge_partition_label(runs: object) -> str:
            normalized = [
                "[" + ",".join(str(value) for value in run) + "]"
                for run in runs
                if isinstance(run, list)
            ] if isinstance(runs, list) else []
            return " | ".join(normalized) or "no visible runs"

        split_levels = [level for level in renderer_state.get("split_levels", []) if isinstance(level, dict)]
        merge_levels = [level for level in renderer_state.get("merge_levels", []) if isinstance(level, dict)]
        current_partition = merge_partition_label(split_levels[0].get("runs", [])) if split_levels else "one source run"
        transitions.append({
            "id": "merge:orient-source",
            "kind": "orient_source_run",
            "claim": "All source items begin in one persistent left-to-right run.",
            "action": "Attach stable identity colors to the source cells before changing any run boundary.",
            "persistent_object_ids": [anchor_id, partition_id, *item_ids],
            "before": {partition_id: "unoriented source"},
            "after": {partition_id: current_partition},
            "evidence_tokens": item_ids,
        })
        for position, level in enumerate(split_levels[1:], start=1):
            level_number = int(level.get("level", position))
            next_partition = merge_partition_label(level.get("runs", []))
            transitions.append({
                "id": f"merge:split:{level_number}",
                "kind": "split_runs",
                "claim": f"Split level {level_number} changes run boundaries without changing any item identity.",
                "action": f"Move the same colored items from {current_partition} into {next_partition}.",
                "persistent_object_ids": [anchor_id, partition_id, *item_ids],
                "before": {partition_id: current_partition},
                "after": {partition_id: next_partition},
                "evidence_tokens": [str(level_number), next_partition],
            })
            current_partition = next_partition
        if merge_levels:
            current_partition = merge_partition_label(merge_levels[0].get("runs", []))
        for position, level in enumerate(merge_levels[1:], start=1):
            level_number = int(level.get("level", position))
            next_partition = merge_partition_label(level.get("runs", []))
            transitions.append({
                "id": f"merge:combine:{level_number}",
                "kind": "merge_runs",
                "claim": f"Merge level {level_number} emits the least remaining head from each adjacent run.",
                "action": f"Compare visible run heads and move every persistent item into {next_partition}.",
                "persistent_object_ids": [anchor_id, partition_id, *item_ids],
                "before": {partition_id: current_partition},
                "after": {partition_id: next_partition},
                "evidence_tokens": [str(level_number), next_partition],
            })
            current_partition = next_partition
        result_ids = [f"cs:merge:item:{int(value)}" for value in renderer_state.get("result_ids", [])]
        transitions.extend((
            {
                "id": "merge:verify:identity",
                "kind": "verify_identity",
                "claim": "Every input identity appears exactly once in the merged output.",
                "action": "Trace the persistent item colors from the source identities into their final slots.",
                "persistent_object_ids": [anchor_id, identity_check_id, *item_ids],
                "before": {identity_check_id: "unchecked"},
                "after": {identity_check_id: "all input identities retained exactly once"},
                "evidence_tokens": result_ids,
            },
            {
                "id": "merge:verify:order",
                "kind": "verify_order",
                "claim": "The final run is nondecreasing from left to right.",
                "action": "Sweep once across the completed run and compare each adjacent pair.",
                "persistent_object_ids": [anchor_id, order_check_id, *item_ids],
                "before": {order_check_id: "unchecked"},
                "after": {order_check_id: "nondecreasing order verified"},
                "evidence_tokens": [str(value) for value in renderer_state.get("result", [])],
            },
            {
                "id": "merge:verify:levels",
                "kind": "verify_merge_levels",
                "claim": "The number of completed merge levels matches balanced halving of the input.",
                "action": "Connect the final run to the displayed split depth and merge-level count.",
                "persistent_object_ids": [anchor_id, partition_id, order_check_id],
                "before": {order_check_id: "nondecreasing order verified"},
                "after": {order_check_id: f"order and {renderer_state.get('merge_level_count')} merge levels verified"},
                "evidence_tokens": [
                    str(renderer_state.get("merge_level_count")),
                    str(renderer_state.get("expected_merge_levels")),
                ],
            },
        ))
    elif family == "array" and mode == "stack_push_pop":
        anchor_id = "cs:stack:cells"
        top_id = "cs:stack:top-marker"
        pushed_id = "cs:stack:pushed-item"
        lifo_id = "cs:stack:lifo-check"
        remember(anchor_id, "persistent stack cells", "#58A6FF")
        remember(top_id, "persistent marker for the current stack top", "#F7C948")
        remember(pushed_id, f"item pushed and popped with value {renderer_state.get('popped')}", "#7EE787")
        remember(lifo_id, "visible LIFO operation check", "#8FD3FF")
        initial = list(renderer_state.get("initial", []))
        pushed = renderer_state.get("popped")
        old_top = initial[-1] if initial else "empty"
        transitions.extend((
            {
                "id": "stack:orient-top",
                "kind": "orient_stack_top",
                "claim": f"The current top is {old_top} before the update.",
                "action": f"Attach the top marker to the last occupied cell containing {old_top}.",
                "persistent_object_ids": [anchor_id, top_id],
                "before": {top_id: "not yet attached"},
                "after": {top_id: f"top={old_top}"},
                "evidence_tokens": [str(old_top)],
            },
            {
                "id": "stack:push",
                "kind": "push_item",
                "claim": f"Pushing {pushed} makes that same item the new top.",
                "action": f"Move item {pushed} into the next stack slot and move the top marker with it.",
                "persistent_object_ids": [anchor_id, top_id, pushed_id],
                "before": {top_id: f"top={old_top}", pushed_id: "outside the stack"},
                "after": {top_id: f"top={pushed}", pushed_id: "inside the top slot"},
                "evidence_tokens": [str(pushed)],
            },
            {
                "id": "stack:select-pop",
                "kind": "select_pop_item",
                "claim": "A pop selects the most recently pushed item, not an older cell.",
                "action": f"Highlight the top marker and select the persistent item {pushed} for removal.",
                "persistent_object_ids": [anchor_id, top_id, pushed_id],
                "before": {top_id: f"top={pushed}", pushed_id: "inside the top slot"},
                "after": {top_id: f"top={pushed}; selected for pop", pushed_id: "selected for removal"},
                "evidence_tokens": ["LIFO", str(pushed)],
            },
            {
                "id": "stack:pop",
                "kind": "pop_item",
                "claim": f"Pop removes {pushed} and restores {old_top} as the visible top.",
                "action": f"Move the same item {pushed} out of the top slot, then return the marker to {old_top}.",
                "persistent_object_ids": [anchor_id, top_id, pushed_id, lifo_id],
                "before": {top_id: f"top={pushed}; selected for pop", pushed_id: "selected for removal", lifo_id: "unchecked"},
                "after": {top_id: f"top={old_top}", pushed_id: "outside the stack after pop", lifo_id: "push value equals popped value"},
                "evidence_tokens": [str(pushed), str(old_top)],
            },
        ))
    elif family == "hash" and mode in {"hash_function_mapping", "separate_chaining"}:
        anchor_id = "cs:hash:table"
        rule_id = "cs:hash:rule"
        verification_id = "cs:hash:verification"
        bucket_count = int(renderer_state.get("bucket_count", 0))
        remember(anchor_id, "persistent hash table", "#58A6FF")
        remember(rule_id, "persistent deterministic hash rule", "#F7C948")
        remember(verification_id, "collision-retention verification", "#7EE787")
        for bucket_index in range(bucket_count):
            remember(f"cs:hash:bucket:{bucket_index}", f"bucket {bucket_index}", "#8FD3FF")
        transitions.append({
            "id": "hash:show-rule",
            "kind": "show_hash_rule",
            "claim": f"The rule maps every key into exactly one index from 0 through {max(0, bucket_count - 1)}.",
            "action": f"Expose h(k)=k mod {bucket_count} and align it with the {bucket_count} persistent buckets.",
            "persistent_object_ids": [anchor_id, rule_id],
            "before": {rule_id: "present but not connected to the bucket range"},
            "after": {rule_id: f"h(k)=k mod {bucket_count}; range 0..{max(0, bucket_count - 1)}"},
            "evidence_tokens": [str(bucket_count)],
        })
        previous_buckets = [[] for _ in range(bucket_count)]
        for position, step in enumerate(renderer_state.get("steps", []), start=1):
            if not isinstance(step, dict):
                continue
            key = int(step.get("key", 0))
            bucket_index = int(step.get("index", 0))
            key_id = f"cs:hash:key:{position - 1}:{key}"
            bucket_id = f"cs:hash:bucket:{bucket_index}"
            remember(key_id, f"key {key} routed through the hash rule", "#EAF2FF")
            next_buckets = [list(bucket) for bucket in step.get("buckets", previous_buckets)]
            transitions.append({
                "id": f"hash:route:{position}",
                "kind": "route_hash_key",
                "claim": f"Key {key} maps to bucket {bucket_index}" + (" and remains visible beside the existing collision." if step.get("collision") else "."),
                "action": f"Move persistent key {key} through the rule into bucket {bucket_index}; retain every prior key.",
                "persistent_object_ids": [anchor_id, rule_id, bucket_id, key_id],
                "before": {key_id: "unplaced", bucket_id: str(previous_buckets[bucket_index])},
                "after": {key_id: f"stored in bucket {bucket_index}", bucket_id: str(next_buckets[bucket_index])},
                "evidence_tokens": [str(key), str(bucket_index), "collision" if step.get("collision") else "direct placement"],
            })
            previous_buckets = next_buckets
        transitions.append({
            "id": "hash:verify-retention",
            "kind": "verify_hash_retention",
            "claim": "Every key remains in the collision structure selected by the same hash rule.",
            "action": "Sweep the occupied buckets and verify each visible key against h(k).",
            "persistent_object_ids": [anchor_id, rule_id, verification_id],
            "before": {verification_id: "unchecked"},
            "after": {verification_id: "all keys retained at their deterministic indices"},
            "evidence_tokens": [str(value) for value in renderer_state.get("keys", [])],
        })
    elif family == "tree" and mode == "bst_search":
        anchor_id = "cs:bst:tree"
        cursor_id = "cs:bst:search-cursor"
        order_id = "cs:bst:order-check"
        result_check_id = "cs:bst:result-check"
        remember(anchor_id, "persistent binary-search-tree topology", "#58A6FF")
        remember(cursor_id, "persistent search-path cursor", "#F7C948")
        remember(order_id, "left-root-right ordering check", "#7EE787")
        remember(result_check_id, "search-result verification", "#8FD3FF")
        snapshots = [snapshot for snapshot in renderer_state.get("snapshots", []) if isinstance(snapshot, dict)]
        insertions = [int(value) for value in renderer_state.get("insertions", [])]
        for key in insertions:
            remember(f"cs:bst:node:{key}", f"persistent BST node containing key {key}", "#EAF2FF")
        root = insertions[0] if insertions else "root"
        transitions.append({
            "id": "bst:orient-root",
            "kind": "orient_bst_root",
            "claim": f"Search and insertion begin at root {root}.",
            "action": f"Attach the search cursor to root {root} and expose the left-smaller/right-larger rule.",
            "persistent_object_ids": [anchor_id, cursor_id, f"cs:bst:node:{root}"],
            "before": {cursor_id: "not attached"},
            "after": {cursor_id: f"at root {root}"},
            "evidence_tokens": [str(root)],
        })
        visible_keys = [root]
        for position, snapshot in enumerate(snapshots[1:], start=1):
            key = int(snapshot.get("inserted", insertions[position] if position < len(insertions) else 0))
            prior = list(visible_keys)
            visible_keys.append(key)
            node_id = f"cs:bst:node:{key}"
            transitions.append({
                "id": f"bst:insert:{position}",
                "kind": "insert_bst_node",
                "claim": f"Insert {key} at the first empty child reached by comparisons.",
                "action": f"Transform the same tree from keys {prior} to keys {visible_keys}; reveal node {key} once.",
                "persistent_object_ids": [anchor_id, node_id],
                "before": {anchor_id: f"keys={prior}", node_id: "absent"},
                "after": {anchor_id: f"keys={visible_keys}", node_id: "visible in its ordered child slot"},
                "evidence_tokens": [str(key)],
            })
        previous_cursor = f"at root {root}"
        target = int(renderer_state.get("search_target", root if isinstance(root, int) else 0))
        path = [int(value) for value in renderer_state.get("search_path", [])]
        for position, key in enumerate(path, start=1):
            if key == target:
                decision = "match"
            elif target < key:
                decision = "take the left subtree"
            else:
                decision = "take the right subtree"
            next_cursor = f"at node {key}; {decision}"
            transitions.append({
                "id": f"bst:search:{position}",
                "kind": "compare_search_key",
                "claim": f"Compare target {target} with {key} and {decision}.",
                "action": f"Move the persistent search cursor to node {key}; keep only the subtree allowed by the comparison.",
                "persistent_object_ids": [anchor_id, cursor_id, f"cs:bst:node:{key}"],
                "before": {cursor_id: previous_cursor},
                "after": {cursor_id: next_cursor},
                "evidence_tokens": [str(target), str(key), decision],
            })
            previous_cursor = next_cursor
        transitions.extend((
            {
                "id": "bst:verify-result",
                "kind": "verify_search_result",
                "claim": f"The displayed path ends with {'the target' if renderer_state.get('found') else 'an empty child'}.",
                "action": "Resolve the cursor into the visible found/not-found result without rebuilding the tree.",
                "persistent_object_ids": [anchor_id, cursor_id, result_check_id],
                "before": {result_check_id: "unchecked"},
                "after": {result_check_id: "found" if renderer_state.get("found") else "not found"},
                "evidence_tokens": [str(value) for value in path],
            },
            {
                "id": "bst:verify-order",
                "kind": "verify_bst_order",
                "claim": "An in-order sweep is nondecreasing, so every search branch was legal.",
                "action": "Sweep the persistent nodes left-root-right and retain the completed search path.",
                "persistent_object_ids": [anchor_id, order_id],
                "before": {order_id: "unchecked"},
                "after": {order_id: "in-order sequence verified"},
                "evidence_tokens": [str(value) for value in sorted(insertions)],
            },
        ))
    elif family == "avl" and mode == "avl_rotation":
        anchor_id = "cs:avl:tree"
