        remember(array_id, "persistent array heap view", "#8FD3FF")
        remember(order_id, "parent-child heap-order check", "#7EE787")
        remember(sync_id, "tree-position to array-index identity check", "#F7C948")
        heap_items = list(renderer_state.get("initial_items", [])) + list(renderer_state.get("result_items", []))
        for event in renderer_state.get("events", []):
            if isinstance(event, dict):
                heap_items.extend(event.get("before_state", {}).get("items", []))
                heap_items.extend(event.get("after_state", {}).get("items", []))
        for item in heap_items:
            if not isinstance(item, dict):
                continue
            item_id = str(item.get("item_id", ""))
            if item_id:
                remember(item_id, f"persistent heap item with key {item.get('value')}", "#EAF2FF")
        grouped_events = collections.OrderedDict()
        for event in renderer_state.get("events", []):
            if isinstance(event, dict):
                grouped_events.setdefault(str(event.get("transition_id")), []).append(event)
        for transition_id, event_group in grouped_events.items():
            if not transition_id:
                continue
            event = event_group[-1]
            event_kind = str(event.get("kind", "heap_event"))
            active = [int(value) for value in event.get("active_indices", [])]
            changed_ids = [str(value) for value in event.get("changed_ids", [])]
