    fallback = re.sub(r"\s*,\s*", ", ", fallback)
    fallback = re.sub(r"\\b(log|ln|exp|sin|cos|tan|min|max)\\s+_", r"\\1_", fallback)
    fallback = re.sub(r"\\b(log|ln|exp|sin|cos|tan|min|max)\\s+([₀-₉₊₋₌₍₎]+)", r"\\1\\2", fallback)
    fallback = re.sub(r"\\b(log|ln|exp|sin|cos|tan|min|max)\\s+\\(", r"\\1(", fallback)
    fallback = re.sub(r"(?<=\\d),\\s+(?=\\d{3}(?:\\D|$))", ",", fallback)
