def linear_combo_objects(self, data):
    vectors = [[float(value) for value in vector] for vector in data["vectors"]]
    weights = [float(value) for value in data["weights"]]
    computed = [float(value) for value in data["computed"]]
    target_values = [float(value) for value in data["target"]] if data.get("target") else None
    cumulative = [[0.0, 0.0]]
    for vector, weight in zip(vectors, weights):
        cumulative.append([cumulative[-1][0] + weight * vector[0], cumulative[-1][1] + weight * vector[1]])
    points = [[0.0, 0.0], computed] + vectors + cumulative
    if target_values is not None:
        points.append(target_values)
    x_min = min(-1, math.floor(min(point[0] for point in points)) - 1)
    x_max = max(1, math.ceil(max(point[0] for point in points)) + 1)
    y_min = min(-1, math.floor(min(point[1] for point in points)) - 1)
    y_max = max(1, math.ceil(max(point[1] for point in points)) + 1)
    plane = NumberPlane(x_range=[x_min, x_max, 1], y_range=[y_min, y_max, 1], x_length=6.8, y_length=4.8, background_line_style={"stroke_color": "#1F3558", "stroke_width": 1, "stroke_opacity": 0.7})
    self.safe_place(plane, y=0.8, max_width=7.3, max_height=5.0, top=3.8, bottom=-2.1)
    origin = plane.c2p(0, 0)
    basis_arrows = VGroup(*[
        Arrow(origin, plane.c2p(vector[0], vector[1]), buff=0, color=self.palette(index), stroke_width=6)
        for index, vector in enumerate(vectors)
        if abs(vector[0]) + abs(vector[1]) > 1e-9
    ])
    contribution_arrows = VGroup()
    for index, (start, end) in enumerate(zip(cumulative, cumulative[1:])):
        start_point = plane.c2p(start[0], start[1])
        end_point = plane.c2p(end[0], end[1])
        if abs(end[0] - start[0]) + abs(end[1] - start[1]) < 1e-9:
            contribution_arrows.add(Dot(start_point, radius=0.06, color=self.palette(index)))
        else:
            contribution_arrows.add(Arrow(start_point, end_point, buff=0, color=self.palette(index), stroke_width=8))
    computed_dot = Dot(plane.c2p(computed[0], computed[1]), radius=0.09, color="#7EE787" if data.get("target_matches") is not False else "#F7C948")
    target_dot = VGroup()
    if target_values is not None and data.get("target_matches") is False:
        target_dot.add(Dot(plane.c2p(target_values[0], target_values[1]), radius=0.1, color="#FF7B72"))
    label_color = "#FF7B72" if data.get("target_matches") is False else "#7EE787"
    label = Text(str(data.get("exact_calculation", "computed combination")), font_size=23, color=label_color, disable_ligatures=True)
    self.add_readability_backplate(label, opacity=0.66, buff=0.06)
    self.safe_place(label, y=-3.35, max_width=7.4, max_height=0.55, top=-3.05, bottom=-3.8)
    return plane, basis_arrows, contribution_arrows, computed_dot, target_dot, label

