def visual_template(kind: str, phase: str = "intro") -> str:
    if phase == "example":
        return "self.play_example_visual(visual_kind, visual_data, setup_stages, calc_stages, takeaway_stages)"
    if phase == "recall":
        return "self.play_recall_visual(visual_kind, visual_data, question_lines, answer_lines)"
    return "self.play_intro_visual(visual_kind, visual_data)"


def prune_managed_short_artifacts(run: Path, plan: dict[str, object]) -> list[Path]:
    expected_stems = {
        f"short_{int(short['index']):02d}_{slugify(str(short['concept']))}"
        for short in plan.get("shorts", [])
        if isinstance(short, dict) and short.get("index") is not None
    }
    expected_indices = {stem.split("_", 2)[1] for stem in expected_stems}
    removed: list[Path] = []
    artifact_dirs = {
        "scenes": re.compile(r"^(short_\d{2}_.+)\.py$"),
        "scripts": re.compile(r"^(short_\d{2}_.+)\.md$"),
        "captions": re.compile(r"^(short_\d{2}_.+)\.srt$"),
        "audio": re.compile(r"^(short_\d{2}_.+)\.mp3$"),
        "videos": re.compile(r"^(short_\d{2}_.+?)(?:_(?:preview|preview_raw|raw|final))?\.mp4$"),
    }
    for directory_name, pattern in artifact_dirs.items():
        directory = run / directory_name
        if not directory.exists():
            continue
        for path in directory.iterdir():
            match = pattern.fullmatch(path.name)
            if path.is_file() and match and match.group(1) not in expected_stems:
                path.unlink()
                removed.append(path)
    logs = run / "logs"
    if logs.exists():
        for path in logs.iterdir():
            match = re.match(r"^short_(\d{2})(?:_|\.)", path.name)
            if path.is_file() and match and match.group(1) not in expected_indices:
                path.unlink()
                removed.append(path)
    return removed


def cmd_manim(args: argparse.Namespace) -> None:
    run = Path(args.run)
    plan = read_json(run / "short_plan.json")
    try:
        animation_plans = require_animation_plans(run, plan)
    except RuntimeError as exc:
        raise SystemExit(str(exc)) from exc
    scenes = run / "scenes"
    scripts = run / "scripts"
    captions = run / "captions"
    scenes.mkdir(exist_ok=True)
    scripts.mkdir(exist_ok=True)
    captions.mkdir(exist_ok=True)
    prune_managed_short_artifacts(run, plan)
    for short in plan["shorts"]:
        slug = slugify(short["concept"])
        class_name = scene_class_name(short["concept"])
        short["class_name"] = class_name
        short["scene_file"] = f"scenes/short_{short['index']:02d}_{slug}.py"
        short["srt_file"] = f"captions/short_{short['index']:02d}_{slug}.srt"
        animation_plan = animation_plans[int(short["index"])]
        planned_duration = animation_plan_duration(animation_plan) or short_video_pacing(short)["total"]
        short["planned_duration_seconds"] = planned_duration
        short["target_duration_seconds"] = planned_duration
        (run / short["scene_file"]).write_text(manim_scene(short, class_name, animation_plan), encoding="utf-8")
        (run / short["srt_file"]).write_text(make_srt(short), encoding="utf-8")
        (scripts / f"short_{short['index']:02d}_{slug}.md").write_text(script_markdown(short), encoding="utf-8")
    write_json(run / "short_plan.json", plan)
    print(scenes)


def make_srt(short: dict[str, object], target_duration: float | None = None) -> str:
    cues = caption_cues(short, target_duration=target_duration)
    return "\n\n".join(f"{i}\n{a} --> {b}\n{textwrap.fill(str(t), width=42)}" for i, (a, b, t) in enumerate(cues, start=1)) + "\n"


def script_clock(timestamp: str) -> str:
    head = timestamp.split(",", 1)[0]
    hours, minutes, seconds = head.split(":")
    if hours != "00":
        return f"{int(hours)}:{minutes}:{seconds}"
    return f"{int(minutes)}:{seconds}"


def script_markdown(short: dict[str, object]) -> str:
    target_seconds = short_video_pacing(short)["total"]
    rows = []
    for (start, end, cue_text), beat in zip(caption_cues(short), video_timed_beats(short)):
        cleaned = str(cue_text).replace("|", "-")
        rows.append(f"| {script_clock(start)}-{script_clock(end)} | {beat['label']} | {beat['read_seconds']}s | {cleaned} |")
    beat_rows = "\n".join(rows)
    return f"""# Short {short['index']:02d}: {short['concept']}

Target length: about {target_seconds:.0f} seconds from script-paced captions; keep going until the concept and worked example are clear.

## Beats

| Time | Beat | Read time | Text |
| --- | --- | ---: | --- |
{beat_rows}
"""


def audio_duration(path: Path) -> float:
    ffprobe = Path(FFMPEG).with_name("ffprobe") if FFMPEG else None
    if not ffprobe or not ffprobe.exists() or not path.exists():
        return 0.0
    result = subprocess.run([str(ffprobe), "-v", "error", "-show_entries", "format=duration", "-of", "default=noprint_wrappers=1:nokey=1", str(path)], text=True, capture_output=True)
    try:
        return float(result.stdout.strip())
    except Exception:
        return 0.0


def make_voiceover(text: str, out: Path, engine: str) -> dict[str, object]:
    out.parent.mkdir(exist_ok=True)
    if engine == "none":
        return {"status": "skipped", "engine": engine}
    if engine == "say":
        say = shutil.which("say")
        if not say:
            return {"status": "failed", "engine": engine, "message": "say not found"}
        aiff = out.with_suffix(".aiff")
        configured_voice = os.environ.get("COURSE_SHORTS_SAY_VOICE", "Samantha")
        voices = []
        for candidate in [configured_voice, "Samantha", "Daniel", "Karen", "Fred"]:
            if candidate and candidate not in voices:
                voices.append(candidate)
        attempts = []
        for voice in voices:
            result = subprocess.run([say, "-v", voice, "-o", str(aiff), text], text=True, capture_output=True)
            dur = audio_duration(aiff)
            attempts.append(f"{voice}:{dur:.3f}s")
            if result.returncode == 0 and dur >= 0.75:
                return {"status": "ok", "engine": engine, "voice": voice, "file": str(aiff), "duration": dur}
        return {"status": "failed", "engine": engine, "message": "say produced invalid audio (" + ", ".join(attempts) + ")"}
    if engine == "edge-tts":
        edge = shutil.which("edge-tts")
        if not edge:
            return {"status": "failed", "engine": engine, "message": "edge-tts not found; install requirements.txt"}
        subprocess.run([edge, "--text", text, "--write-media", str(out)], check=False)
        dur = audio_duration(out)
        return {"status": "ok" if dur > 0.75 else "failed", "engine": engine, "file": str(out), "duration": dur}
    if engine == "openai":
        token = os.environ.get("OPENAI_API_KEY")
        if not token:
            return {"status": "failed", "engine": engine, "message": "OPENAI_API_KEY is not set"}
        import requests
        response = requests.post(
            "https://api.openai.com/v1/audio/speech",
            headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"},
            json={"model": os.environ.get("OPENAI_TTS_MODEL", "gpt-4o-mini-tts"), "voice": os.environ.get("OPENAI_TTS_VOICE", "alloy"), "input": text},
            timeout=120,
        )
        if response.status_code >= 300:
            return {"status": "failed", "engine": engine, "message": response.text[:500]}
        out.write_bytes(response.content)
        dur = audio_duration(out)
        return {"status": "ok" if dur > 0.75 else "failed", "engine": engine, "file": str(out), "duration": dur}
    return {"status": "failed", "engine": engine, "message": "unknown voice engine"}



def narration_text(short: dict[str, object]) -> str:
    return " ".join(str(beat["text"]) for beat in canonical_beat_schedule(short) if str(beat["text"]).strip())


def piper_model_settings(args: argparse.Namespace) -> tuple[Path, Path, str | None]:
    model_dir = Path(
        str(
            getattr(args, "piper_model_dir", None)
            or os.environ.get("COURSE_SHORTS_PIPER_MODEL_DIR")
            or ROOT / "models" / "piper"
        )
    )
    manifest = Path(
        str(
            getattr(args, "piper_model_manifest", None)
            or os.environ.get("COURSE_SHORTS_PIPER_MODEL_MANIFEST")
            or piper_voiceover.DEFAULT_MANIFEST_PATH
        )
    )
    model_id = getattr(args, "piper_model_id", None) or os.environ.get("COURSE_SHORTS_PIPER_MODEL_ID")
    return model_dir, manifest, str(model_id) if model_id else None


def aggregate_piper_timing(
    report: dict[str, object], animation_plan: dict[str, object]
) -> dict[str, object]:
    canonical = report.get("beats") if isinstance(report.get("beats"), list) else []
    plan_beats = animation_plan.get("beats") if isinstance(animation_plan.get("beats"), list) else []
    grouped: list[dict[str, object]] = []
    consumed: list[str] = []
    for plan_beat in plan_beats:
        if not isinstance(plan_beat, dict):
            raise ValueError("Animation plan contains an invalid beat")
        state = str(plan_beat.get("scene_state", ""))
        rows = [row for row in canonical if isinstance(row, dict) and str(row.get("scene_state", "")) == state]
        if not rows:
            raise ValueError(f"Piper timing has no canonical audio for storyboard state {state}")
        consumed.extend(str(row.get("beat_id", "")) for row in rows)
        first, last = rows[0], rows[-1]
        grouped.append(
            {
                "beat_id": str(plan_beat.get("id", "")),
                "scene_state": state,
                "beat_start": first["beat_start"],
                "beat_end": last["beat_end"],
                "beat_start_frame": first["beat_start_frame"],
                "beat_end_frame": last["beat_end_frame"],
                "canonical_beat_ids": [str(row.get("beat_id", "")) for row in rows],
                "expanded": any(bool(row.get("expanded")) for row in rows),
            }
        )
    canonical_ids = [str(row.get("beat_id", "")) for row in canonical if isinstance(row, dict)]
    if consumed != canonical_ids:
        raise ValueError("Piper canonical beats do not map exactly once to storyboard states")
    return {**report, "canonical_beats": canonical, "beats": grouped}


def prepare_piper_workflow(
    run: Path, plan: dict[str, object], args: argparse.Namespace
) -> tuple[dict[str, object], dict[int, dict[str, object]], dict[int, dict[str, object]]]:
    ffmpeg = find_executable("ffmpeg")
    if not ffmpeg:
        raise piper_voiceover.AudioToolError("ffmpeg not found")
    model_dir, manifest_path, model_id = piper_model_settings(args)
    audio_dir = run / "audio"
    audio_dir.mkdir(exist_ok=True)
    reports: dict[int, dict[str, object]] = {}
    shorts = plan.get("shorts") if isinstance(plan.get("shorts"), list) else []
    for short in shorts:
        if not isinstance(short, dict):
            raise ValueError("short_plan.json contains a non-object short")
        index = int(short.get("index", 0) or 0)
        slug = slugify(str(short.get("concept", "")))
        audio_path = audio_dir / f"short_{index:02d}_{slug}_narration.wav"
        timing_path = audio_dir / f"short_{index:02d}_{slug}_narration_timing.json"
        canonical = canonical_beat_schedule(short, use_voice_timing=False)
        report = piper_voiceover.render_voiceover(
            canonical,
            audio_path,
            timing_path,
            model_dir=model_dir,
            manifest_path=manifest_path,
            model_id=model_id,
            ffmpeg=ffmpeg,
            boundary_fps=RENDER_TIMELINE_FPS,
        )
        short["piper_voice_timing"] = {
            "engine": "piper",
            "canonical_beats": report["beats"],
            "audio_file": str(audio_path.relative_to(run)),
            "timing_manifest": str(timing_path.relative_to(run)),
        }
        reports[index] = report

    write_json(run / "short_plan.json", plan)
    cmd_storyboard(argparse.Namespace(run=str(run)))
    cmd_manim(argparse.Namespace(run=str(run)))
    refreshed = read_json(run / "short_plan.json")
    animation_plans = require_animation_plans(run, refreshed)
    voices: dict[int, dict[str, object]] = {}
    for short in refreshed["shorts"]:
        index = int(short["index"])
        timing = short["piper_voice_timing"]
        audio_path = run / str(timing["audio_file"])
        timing_path = run / str(timing["timing_manifest"])
        report = aggregate_piper_timing(reports[index], animation_plans[index])
        plan_path = run / str(short["animation_plan_file"])
        report["plan_sha256"] = file_sha256(plan_path)
        report["audio_sha256"] = file_sha256(audio_path)
        write_json(timing_path, report)
        voices[index] = {
            "status": "ok",
            "engine": "piper",
            "file": str(audio_path),
            "audio_file": str(audio_path.relative_to(run)),
            "timing_manifest": str(timing_path.relative_to(run)),
            "duration": float(report["duration"]),
            "model_id": report["model_id"],
            "piper_tts_version": report["piper_tts_version"],
            "model_sha256": report["model_sha256"],
            "model_assets": report["model_assets"],
        }
    return refreshed, animation_plans, voices


def probe_media(path: Path) -> dict[str, object]:
    ffprobe = find_executable("ffprobe")
    if not ffprobe or not path.exists():
        return {}
    result = subprocess.run(
        [ffprobe, "-v", "error", "-show_streams", "-show_format", "-of", "json", str(path)],
        text=True,
        capture_output=True,
    )
    if result.returncode != 0:
        return {}
    try:
        payload = json.loads(result.stdout)
    except json.JSONDecodeError:
        return {}
    streams = payload.get("streams", []) if isinstance(payload, dict) else []
    video = next((stream for stream in streams if stream.get("codec_type") == "video"), {})
    audio = next((stream for stream in streams if stream.get("codec_type") == "audio"), {})
    format_data = payload.get("format", {}) if isinstance(payload, dict) else {}
    return {
        "duration_seconds": float_or_zero(format_data.get("duration")),
        "format_name": format_data.get("format_name"),
        "video": {
            key: video.get(key)
            for key in ("codec_name", "profile", "width", "height", "pix_fmt", "r_frame_rate", "avg_frame_rate")
        },
        "audio": {key: audio.get(key) for key in ("codec_name", "sample_rate", "channels")} if audio else None,
    }


def production_profile_ok(probe: dict[str, object]) -> bool:
    video = probe.get("video", {}) if isinstance(probe.get("video"), dict) else {}
    frame_rates = {str(video.get("r_frame_rate", "")), str(video.get("avg_frame_rate", ""))}
    return (
        video.get("codec_name") == "h264"
        and video.get("width") == 1080
        and video.get("height") == 1920
        and video.get("pix_fmt") == "yuv420p"
        and bool(frame_rates & {"30/1", "30"})
    )


def probe_av_durations(path: Path) -> tuple[float, float]:
    ffprobe = find_executable("ffprobe")
    if not ffprobe:
        return 0.0, 0.0
    result = subprocess.run(
        [ffprobe, "-v", "error", "-show_entries", "stream=codec_type,duration", "-of", "json", str(path)],
        text=True,
        capture_output=True,
    )
    try:
        streams = json.loads(result.stdout).get("streams", []) if result.returncode == 0 else []
    except json.JSONDecodeError:
        streams = []
    durations = {
        str(stream.get("codec_type")): float_or_zero(stream.get("duration"))
        for stream in streams
        if isinstance(stream, dict)
    }
    return durations.get("video", 0.0), durations.get("audio", 0.0)


def media_alignment_durations(raw_duration: float, voice_duration: float = 0.0) -> dict[str, float]:
    """Return lossless end-alignment durations for optional narration."""
    raw = max(0.0, float(raw_duration or 0.0))
    voice = max(0.0, float(voice_duration or 0.0))
    target = max(raw, voice)
    return {
        "target_duration": target,
        "video_pad_seconds": max(0.0, target - raw),
        "audio_pad_seconds": max(0.0, target - voice) if voice > 0 else 0.0,
    }


def finalize_video(
    raw: Path,
    final: Path,
    log_path: Path,
    *,
    voice_file: Path | None = None,
    provenance_id: str,
) -> dict[str, object]:
    """Create every final, including silent ones, through one production profile."""
    ffmpeg = find_executable("ffmpeg")
    raw_duration = audio_duration(raw)
    if not ffmpeg:
        return {"status": "failed", "message": "ffmpeg not found"}
    if raw_duration <= 0:
        return {"status": "failed", "message": "raw video has no measurable duration"}

    partial = final.with_name(final.stem + ".partial.mp4")
    partial.unlink(missing_ok=True)
    final.unlink(missing_ok=True)
    video_filter = (
        "scale=1080:1920:force_original_aspect_ratio=decrease,"
        "pad=1080:1920:(ow-iw)/2:(oh-ih)/2:color=0x0B1020,"
        "fps=30,setsar=1"
    )
    cmd = [ffmpeg, "-y", "-i", str(raw)]
    voice_duration = 0.0
    if voice_file is not None:
        voice_duration = audio_duration(voice_file)
        cmd.extend(["-i", str(voice_file)])
    alignment = media_alignment_durations(raw_duration, voice_duration)
    video_pad = alignment["video_pad_seconds"]
    audio_pad = alignment["audio_pad_seconds"]
    target_duration = alignment["target_duration"]
    if video_pad > 0.001:
        video_filter += f",tpad=stop_mode=clone:stop_duration={video_pad:.3f}"
    cmd.extend(["-map", "0:v:0", "-vf", video_filter])
    if voice_file is not None and voice_duration > 0:
        audio_filter = f"apad=pad_dur={audio_pad:.3f}" if audio_pad > 0.001 else "anull"
        cmd.extend(["-map", "1:a:0", "-af", audio_filter, "-c:a", "aac", "-b:a", "192k"])
    else:
        cmd.append("-an")
    cmd.extend(
        [
            "-t",
            f"{target_duration:.3f}",
            "-r",
            "30",
            "-fps_mode",
            "cfr",
            "-c:v",
            "libx264",
            "-preset",
            "medium",
            "-crf",
            str(FINAL_VIDEO_CRF),
            "-pix_fmt",
            "yuv420p",
            "-movflags",
            "+faststart",
            "-map_metadata",
            "-1",
            "-metadata",
            f"comment=generated_by=tools/stem_course.py;profile={FINAL_VIDEO_PROFILE};result={provenance_id}",
            str(partial),
        ]
    )
    result = subprocess.run(cmd, text=True, capture_output=True, timeout=1200)
    log_path.write_text("COMMAND\n" + json.dumps(cmd) + "\n\n" + result.stdout + "\n" + result.stderr, encoding="utf-8")
    if result.returncode != 0 or not partial.exists():
        partial.unlink(missing_ok=True)
        return {
            "status": "failed",
            "returncode": result.returncode,
            "message": result.stderr.strip()[-500:] or "ffmpeg did not create the partial output",
        }
    partial.replace(final)
    probe = probe_media(final)
    if not production_profile_ok(probe):
        final.unlink(missing_ok=True)
        return {"status": "failed", "returncode": result.returncode, "message": "final media failed production profile verification", "probe": probe}
    return {
        "status": "ok",
        "returncode": result.returncode,
        "profile": FINAL_VIDEO_PROFILE,
        "crf": FINAL_VIDEO_CRF,
        "target_duration": target_duration,
        "video_time_scale": 1.0,
        "video_pad_seconds": video_pad,
        "audio_pad_seconds": audio_pad,
        "audio_truncated_seconds": 0.0,
        "probe": probe,
        "command": cmd,
    }


def finalize_piper_video(
    raw: Path,
    voice_file: Path,
    final: Path,
    log_path: Path,
    *,
    provenance_id: str,
    preview: bool = False,
) -> dict[str, object]:
    """Mux pre-aligned Piper audio without extending or shortening either stream."""
    ffmpeg = find_executable("ffmpeg")
    raw_duration = audio_duration(raw)
    voice_duration = audio_duration(voice_file)
    frame_rate = 15.0 if preview else 30.0
    if not ffmpeg:
        return {"status": "failed", "message": "ffmpeg not found"}
    if raw_duration <= 0 or voice_duration <= 0:
        return {"status": "failed", "message": "Piper mux inputs have no measurable duration"}
    if abs(raw_duration - voice_duration) > 1.0 / frame_rate + 0.001:
        return {
            "status": "failed",
            "message": (
                f"Piper audio/video boundaries differ by {abs(raw_duration - voice_duration):.3f}s; "
                "regenerate storyboard and Manim from canonical Piper timing"
            ),
        }

    partial = final.with_name(final.stem + ".partial.mp4")
    partial.unlink(missing_ok=True)
    final.unlink(missing_ok=True)
    command = [ffmpeg, "-y", "-i", str(raw), "-i", str(voice_file), "-map", "0:v:0", "-map", "1:a:0"]
    if preview:
        command.extend(["-c:v", "copy"])
    else:
        command.extend(
            [
                "-vf",
                "scale=1080:1920:force_original_aspect_ratio=decrease,pad=1080:1920:(ow-iw)/2:(oh-ih)/2:color=0x0B1020,fps=30,setsar=1",
                "-r",
                "30",
                "-fps_mode",
                "cfr",
                "-c:v",
                "libx264",
                "-preset",
                "medium",
                "-crf",
                str(FINAL_VIDEO_CRF),
                "-pix_fmt",
                "yuv420p",
            ]
        )
    command.extend(
        [
            "-c:a",
            "aac",
            "-b:a",
            "192k" if not preview else "128k",
            "-ar",
            "48000",
            "-ac",
            "1",
            "-movflags",
            "+faststart",
            "-map_metadata",
            "-1",
            "-metadata",
            f"comment=generated_by=tools/stem_course.py;profile={'native-preview' if preview else FINAL_VIDEO_PROFILE};result={provenance_id}",
            str(partial),
        ]
    )
    forbidden = ("tpad", "apad", "atempo", "-shortest", "-t")
    command_text = " ".join(command)
    if any(token in command_text for token in forbidden):
        return {"status": "failed", "message": "Piper mux command contains a forbidden timing operation"}
    result = subprocess.run(command, text=True, capture_output=True, timeout=1200)
    log_path.write_text(
        "COMMAND\n" + json.dumps(command) + "\n\n" + result.stdout + "\n" + result.stderr,
        encoding="utf-8",
    )
    if result.returncode != 0 or not partial.exists():
        partial.unlink(missing_ok=True)
        return {
            "status": "failed",
            "returncode": result.returncode,
            "message": result.stderr.strip()[-500:] or "Piper mux did not create output",
            "command": command,
        }
    partial.replace(final)
    probe = probe_media(final)
    final_video_duration, final_audio_duration = probe_av_durations(final)
    av_delta = abs(final_video_duration - final_audio_duration)
    profile_ok = True if preview else production_profile_ok(probe)
    audio_ok = (
        str(probe.get("audio", {}).get("codec_name", "")).lower() == "aac"
        and int(float_or_zero(probe.get("audio", {}).get("sample_rate"))) == 48_000
        and int(float_or_zero(probe.get("audio", {}).get("channels"))) == 1
    ) if isinstance(probe.get("audio"), dict) else False
    if (
        not profile_ok
        or not audio_ok
        or final_video_duration <= 0
        or final_audio_duration <= 0
        or av_delta > 1.0 / frame_rate + 0.001
    ):
        final.unlink(missing_ok=True)
        return {
            "status": "failed",
            "message": "Piper final media failed profile or one-frame A/V alignment verification",
            "probe": probe,
            "command": command,
        }
    return {
        "status": "ok",
        "profile": "native-preview" if preview else FINAL_VIDEO_PROFILE,
        "target_duration": voice_duration,
        "video_time_scale": 1.0,
        "video_pad_seconds": 0.0,
        "audio_pad_seconds": 0.0,
        "audio_truncated_seconds": 0.0,
        "probe": probe,
        "command": command,
    }


def mux_voiceover(raw: Path, voice_file: Path, final: Path, raw_duration: float, voice_duration: float, log_path: Path) -> dict[str, object]:
    del raw_duration, voice_duration
    return finalize_video(raw, final, log_path, voice_file=voice_file, provenance_id=final.stem)


def manim_cli_prefix() -> list[str]:
    configured = os.environ.get("COURSE_SHORTS_MANIM")
    if configured:
        return [configured]
    local = ROOT / ".venv311" / "bin" / "manim"
    if local.exists() and os.access(local, os.X_OK):
        return [str(local)]
    return [sys.executable, "-m", "manim"]


def manim_render_command(qflag: str, media_dir: Path, scene: Path, class_name: str) -> list[str]:
    """Build a render command that cannot reuse source-dependent partial movies."""
    return manim_cli_prefix() + [
        qflag,
        "--disable_caching",
        "--media_dir",
        str(media_dir),
        str(scene),
        class_name,
    ]


def manim_cache_provenance(media_dir: Path) -> dict[str, object]:
    return {
        "mode": "disabled",
        "manim_option": "--disable_caching",
        "partial_movie_reuse": False,
        "media_dir": str(media_dir),
    }


def fresh_rendered_mp4(root: Path, class_name: str, not_before_ns: int) -> Path | None:
    if not root.exists():
        return None
    candidates: list[Path] = []
    for path in root.rglob(f"{class_name}.mp4"):
        lowered_parts = {part.lower() for part in path.parts}
        lowered_name = path.name.lower()
        if "partial_movie_files" in lowered_parts or "partial" in lowered_name:
            continue
        try:
            stat = path.stat()
        except OSError:
            continue
        if stat.st_size <= 0 or stat.st_mtime_ns < not_before_ns:
            continue
        candidates.append(path)
    if not candidates:
        return None
    return max(candidates, key=lambda path: (path.stat().st_mtime_ns, str(path.relative_to(root))))


def finalize_preview_video(
    raw: Path,
    preview_file: Path,
    log_path: Path,
    *,
    voice_file: Path | None,
    raw_duration: float,
    voice_duration: float,
) -> dict[str, object]:
    """Keep previews cheap and native-size while preserving optional audio timing."""
    preview_file.parent.mkdir(parents=True, exist_ok=True)
    preview_file.unlink(missing_ok=True)
    if voice_file is None:
        shutil.copy2(raw, preview_file)
        probe = probe_media(preview_file)
        return {
            "status": "ok",
            "profile": "native-preview",
            "target_duration": raw_duration,
            "video_pad_seconds": 0.0,
            "audio_pad_seconds": 0.0,
            "probe": probe,
            "command": ["copy", str(raw), str(preview_file)],
        }

    target_duration = max(raw_duration, voice_duration)
    video_pad = max(0.0, target_duration - raw_duration)
    audio_pad = max(0.0, target_duration - voice_duration)
    command = [str(FFMPEG), "-y", "-i", str(raw), "-i", str(voice_file)]
    if video_pad > 0.001:
        command.extend(["-vf", f"tpad=stop_mode=clone:stop_duration={video_pad:.3f}"])
    if audio_pad > 0.001:
        command.extend(["-af", f"apad=pad_dur={audio_pad:.3f}"])
    command.extend(
        [
            "-map", "0:v:0", "-map", "1:a:0", "-c:v", "libx264", "-preset", "veryfast",
            "-crf", "25", "-pix_fmt", "yuv420p", "-r", "15", "-c:a", "aac", "-b:a", "128k",
            "-t", f"{target_duration:.3f}", "-movflags", "+faststart", str(preview_file),
        ]
    )
    result = subprocess.run(command, text=True, capture_output=True, timeout=600)
    log_path.write_text(result.stdout + "\n" + result.stderr, encoding="utf-8")
    if result.returncode != 0 or not preview_file.exists() or preview_file.stat().st_size <= 0:
        preview_file.unlink(missing_ok=True)
        return {
            "status": "failed",
            "returncode": result.returncode,
            "message": result.stderr.strip()[-500:] or "preview mux did not create output",
            "command": command,
        }
    return {
        "status": "ok",
        "profile": "native-preview",
        "target_duration": target_duration,
        "video_pad_seconds": video_pad,
        "audio_pad_seconds": audio_pad,
        "probe": probe_media(preview_file),
        "command": command,
    }



def cmd_render(args: argparse.Namespace) -> None:
    run = Path(args.run)
    plan = read_json(run / "short_plan.json")
    voice_engine = str(getattr(args, "voice_engine", "none"))
    piper_voices: dict[int, dict[str, object]] = {}
    try:
        if voice_engine == "piper":
            plan, animation_plans, piper_voices = prepare_piper_workflow(run, plan, args)
        else:
            animation_plans = require_animation_plans(run, plan)
    except (RuntimeError, ValueError, piper_voiceover.PiperNarrationError) as exc:
        raise SystemExit(f"Piper narration failed closed: {exc}" if voice_engine == "piper" else str(exc)) from exc
    videos = run / "videos"
    audio = run / "audio"
    logs = run / "logs"
    scenes = run / "scenes"
    scripts = run / "scripts"
    captions = run / "captions"
    for directory in (videos, audio, logs, scenes, scripts, captions):
        directory.mkdir(exist_ok=True)
    prune_managed_short_artifacts(run, plan)
    quality = str(getattr(args, "quality", "production"))
    preview = quality in {"preview", "l"}
    animation_plan_index = read_json(run / ANIMATION_PLAN_INDEX_NAME)
    runtime_trace_path = run / RENDER_RUNTIME_TRACE_NAME
    runtime_trace_path.unlink(missing_ok=True)
    runtime_trace_rows: list[dict[str, object]] = []
    results = []
    requested_indices: set[int] = set()
    requested = str(getattr(args, "shorts", "") or "").strip()
    if requested:
        try:
            requested_indices = {int(value.strip()) for value in requested.split(",") if value.strip()}
        except ValueError as exc:
            raise SystemExit("--shorts must be a comma-separated list of positive indices") from exc
        available_indices = {int(short["index"]) for short in plan["shorts"]}
        unknown = sorted(requested_indices - available_indices)
        if not requested_indices or min(requested_indices) < 1 or unknown:
            raise SystemExit(f"--shorts contains unavailable indices: {unknown or sorted(requested_indices)}")
    render_shorts = [
        short for short in plan["shorts"]
        if not requested_indices or int(short["index"]) in requested_indices
    ]
    for short in render_shorts:
        slug = slugify(short["concept"])
        class_name = str(short.get("class_name") or scene_class_name(short["concept"]))
        short["class_name"] = class_name
        short["scene_file"] = f"scenes/short_{short['index']:02d}_{slug}.py"
        short["srt_file"] = f"captions/short_{short['index']:02d}_{slug}.srt"
        scene = run / short["scene_file"]
        raw_suffix = "_preview_raw.mp4" if preview else "_raw.mp4"
        output_suffix = "_preview.mp4" if preview else "_final.mp4"
        raw = videos / f"short_{short['index']:02d}_{slug}{raw_suffix}"
        final = videos / f"short_{short['index']:02d}_{slug}{output_suffix}"
        animation_plan = animation_plans[int(short["index"])]
        if not scene.exists():
            scene.write_text(manim_scene(short, class_name, animation_plan), encoding="utf-8")
        try:
            require_current_generated_scene(scene, animation_plan)
        except RuntimeError as exc:
            raise SystemExit(str(exc)) from exc

        voice = (
            piper_voices[int(short["index"])]
            if voice_engine == "piper"
            else make_voiceover(
                narration_text(short),
                audio / f"short_{short['index']:02d}_{slug}.mp3",
                voice_engine,
            )
        )
        voice_duration = float(voice.get("duration", 0) or 0)
        if voice.get("status") == "ok":
            short["voice_duration_seconds"] = round(voice_duration, 3)
            short["narration_duration_seconds"] = round(voice_duration, 3)
        else:
            short.pop("voice_duration_seconds", None)
            short.pop("narration_duration_seconds", None)

        planned_duration = animation_plan_duration(animation_plan) or short_video_pacing(short)["total"]
        short["planned_duration_seconds"] = planned_duration
        short["target_duration_seconds"] = planned_duration
        (run / str(short["srt_file"])).write_text(make_srt(short, target_duration=short["target_duration_seconds"]), encoding="utf-8")
        (scripts / f"short_{short['index']:02d}_{slug}.md").write_text(script_markdown(short), encoding="utf-8")

        qflag = "-ql" if preview else "-qh"
        media_dir = run / "manim_media"
        scene_media = media_dir / "videos" / scene.stem
        shutil.rmtree(scene_media, ignore_errors=True)
        if preview:
            (videos / f"short_{short['index']:02d}_{slug}_raw.mp4").unlink(missing_ok=True)
            (videos / f"short_{short['index']:02d}_{slug}_final.mp4").unlink(missing_ok=True)
            for field in ("video_file", "duration_seconds", "render_provenance"):
                short.pop(field, None)
        else:
            (videos / f"short_{short['index']:02d}_{slug}_preview_raw.mp4").unlink(missing_ok=True)
            (videos / f"short_{short['index']:02d}_{slug}_preview.mp4").unlink(missing_ok=True)
            for field in ("preview_file", "preview_duration_seconds", "preview_provenance"):
                short.pop(field, None)
        raw.unlink(missing_ok=True)
        final.unlink(missing_ok=True)
        final.with_name(final.stem + ".partial.mp4").unlink(missing_ok=True)
        cmd = manim_render_command(qflag, media_dir, scene, class_name)
        execution_marker_path = logs / f"short_{short['index']:02d}_render_execution.json"
        execution_marker_path.unlink(missing_ok=True)
        execution_marker_path.with_name(execution_marker_path.name + ".partial").unlink(missing_ok=True)
        render_env = {
            **os.environ,
            "COURSE_SHORTS_RENDER_MODE": "preview" if preview else "production",
            RENDER_EXECUTION_MARKER_ENV: str(execution_marker_path.resolve()),
        }
        render_started_ns = time.time_ns()
        render_timeout = 300 if preview else 1200
        log_file = logs / f"short_{short['index']:02d}_manim.log"
        log_file.write_text("COMMAND\n" + json.dumps(cmd) + "\n\nSTATUS\nrunning\n", encoding="utf-8")
        try:
            manim = subprocess.run(
                cmd,
                cwd=ROOT,
                env=render_env,
                text=True,
                capture_output=True,
                timeout=render_timeout,
            )
            log_text = "COMMAND\n" + json.dumps(cmd) + "\n\n" + manim.stdout + "\n" + manim.stderr
        except subprocess.TimeoutExpired as exc:
            stdout = exc.stdout.decode("utf-8", errors="replace") if isinstance(exc.stdout, bytes) else str(exc.stdout or "")
            stderr = exc.stderr.decode("utf-8", errors="replace") if isinstance(exc.stderr, bytes) else str(exc.stderr or "")
            log_text = (
                "COMMAND\n"
                + json.dumps(cmd)
                + f"\n\nSTATUS\ntimeout after {render_timeout} seconds\n\n"
                + stdout
                + "\n"
                + stderr
            )
            log_file.write_text(log_text, encoding="utf-8")
            results.append({"index": short["index"], "status": "failed", "stage": "manim_timeout", "voiceover": voice})
            continue
        log_file.write_text(log_text, encoding="utf-8")
        execution_markers: dict[str, object] | None = None
        marker_read_error = ""
        if execution_marker_path.exists():
            try:
                execution_markers = read_json(execution_marker_path)
            except (OSError, json.JSONDecodeError) as exc:
                marker_read_error = str(exc)
        if manim.returncode != 0:
            marker_messages = (
                [str(message) for message in execution_markers.get("errors", [])]
                if isinstance(execution_markers, dict) and isinstance(execution_markers.get("errors"), list)
                else []
            )
            results.append(
                {
                    "index": short["index"],
                    "status": "failed",
                    "stage": "runtime_trace" if marker_messages else "manim",
                    "message": "; ".join(marker_messages[:4]) if marker_messages else None,
                    "voiceover": voice,
                }
            )
            continue
        if not preview:
            if execution_markers is None:
                message = "Manim did not emit renderer execution markers"
                if marker_read_error:
                    message += ": " + marker_read_error
                results.append({"index": short["index"], "status": "failed", "stage": "runtime_trace", "message": message, "voiceover": voice})
                continue
            marker_errors = render_execution_marker_errors(
                execution_markers,
                animation_plan,
                short_index=int(short["index"]),
                require_transform_callbacks=True,
            )
            if marker_errors:
                results.append(
                    {
                        "index": short["index"],
                        "status": "failed",
                        "stage": "runtime_trace",
                        "message": "; ".join(marker_errors[:6]),
                        "voiceover": voice,
                    }
                )
                continue
        rendered = fresh_rendered_mp4(scene_media, class_name, render_started_ns)
        if not rendered:
            results.append({"index": short["index"], "status": "failed", "stage": "locate_fresh_render", "voiceover": voice})
            continue
        rendered_stat = rendered.stat()
        provenance = {
            "generator": "tools/stem_course.py",
            "scene_metadata_version": SCENE_METADATA_VERSION,
            "quality_mode": "preview" if preview else "production",
            "scene_file": str(short["scene_file"]),
            "class_name": class_name,
            "scene_source_sha256": file_sha256(scene),
            "animation_plan_fingerprint": animation_plan_fingerprint(animation_plan),
            "render_command": cmd,
            "effective_cache_policy": manim_cache_provenance(media_dir),
            "render_started_ns": render_started_ns,
            "selection_policy": "exact class filename, fresh mtime, non-partial, non-empty",
            "selected_render": str(rendered.relative_to(run)),
            "selected_mtime_ns": rendered_stat.st_mtime_ns,
            "selected_size_bytes": rendered_stat.st_size,
        }
        if not preview:
            provenance["final_profile"] = FINAL_VIDEO_PROFILE
        shutil.copy2(rendered, raw)

        raw_duration = audio_duration(raw)
        plan_sync = planned_duration_sync(planned_duration, raw_duration)
        voice_file = Path(str(voice["file"])) if voice.get("status") == "ok" and voice.get("file") else None
        provenance_id = f"short-{int(short['index']):02d}-{slug}"
        if preview:
            if voice_engine == "piper" and voice_file is not None:
                preview_result = finalize_piper_video(
                    raw,
                    voice_file,
                    final,
                    logs / f"short_{short['index']:02d}_preview_ffmpeg.log",
                    provenance_id=provenance_id,
                    preview=True,
                )
            else:
                preview_result = finalize_preview_video(
                    raw,
                    final,
                    logs / f"short_{short['index']:02d}_preview_ffmpeg.log",
                    voice_file=voice_file,
                    raw_duration=raw_duration,
                    voice_duration=voice_duration,
                )
            if preview_result.get("status") != "ok":
                results.append({"index": short["index"], "status": "failed", "stage": "preview_finalize", "voiceover": voice, "preview": preview_result, "provenance": provenance})
                continue
            duration = audio_duration(final)
            short["preview_file"] = str(final.relative_to(run))
            short["preview_duration_seconds"] = duration
            short["preview_provenance"] = provenance
            results.append({"index": short["index"], "status": "previewed", "duration_seconds": duration, "voiceover": voice, "preview": preview_result, "plan_sync": plan_sync, "provenance": provenance})
            continue
        if plan_sync["status"] != "ok":
            results.append(
                {
                    "index": short["index"],
                    "status": "failed",
                    "stage": "scene_duration_mismatch",
                    "message": "The Manim scene duration does not match its semantic beat plan; fix the scene choreography instead of redefining the target.",
                    "voiceover": voice,
                    "plan_sync": plan_sync,
                    "provenance": provenance,
                }
            )
            continue
        if voice_engine == "piper" and voice_file is not None:
            finalized = finalize_piper_video(
                raw,
                voice_file,
                final,
                logs / f"short_{short['index']:02d}_ffmpeg.log",
                provenance_id=provenance_id,
            )
        else:
            finalized = finalize_video(
                raw,
                final,
                logs / f"short_{short['index']:02d}_ffmpeg.log",
                voice_file=voice_file,
                provenance_id=provenance_id,
            )
        if finalized.get("status") != "ok":
            if voice_file is not None:
                voice = {**voice, "status": "failed", "message": f"production finalization failed: {finalized.get('message', 'unknown error')}"}
            results.append({"index": short["index"], "status": "failed", "stage": "finalize", "voiceover": voice, "finalization": finalized, "provenance": provenance})
            continue

        video_file = str(final.relative_to(run))
        if voice_engine == "piper":
            timing_path = run / str(voice["timing_manifest"])
            timing_manifest = read_json(timing_path)
            timing_manifest["video_sha256"] = file_sha256(final)
            write_json(timing_path, timing_manifest)
            voice["video_sha256"] = timing_manifest["video_sha256"]
        try:
            runtime_trace_row = build_render_runtime_trace_row(
                short_index=int(short["index"]),
                video_file=video_file,
                video_path=final,
                animation_plan=animation_plan,
                marker_payload=execution_markers,
            )
        except ValueError as exc:
            final.unlink(missing_ok=True)
            results.append(
                {
                    "index": short["index"],
                    "status": "failed",
                    "stage": "runtime_trace",
                    "message": str(exc),
                    "voiceover": voice,
                    "provenance": provenance,
                }
            )
            continue
        runtime_trace_rows.append(runtime_trace_row)

        duration = audio_duration(final)
        target_duration = duration or raw_duration or planned_duration
        if short.get("srt_file"):
            (run / str(short["srt_file"])).write_text(make_srt(short, target_duration=target_duration), encoding="utf-8")
        short["target_duration_seconds"] = round(target_duration, 3)
        short["video_file"] = video_file
        short["voiceover"] = voice
        short["duration_seconds"] = duration
        short["render_provenance"] = provenance
        finalized["raw_duration"] = raw_duration
        finalized["voice_duration"] = voice_duration
        finalized["final_duration"] = duration
        finalized["planned_duration"] = planned_duration
        results.append({"index": short["index"], "status": "rendered", "duration_seconds": duration, "voiceover": voice, "sync": finalized, "plan_sync": plan_sync, "provenance": provenance})
    write_json(run / "short_plan.json", plan)
    if not preview:
        write_json(runtime_trace_path, render_runtime_trace_payload(animation_plan_index, runtime_trace_rows))
    render_report_path = run / "render_report.json"
    write_json(render_report_path, {"results": results})
    print(render_report_path)
    failed_results = [
        result
        for result in results
        if isinstance(result, dict) and result.get("status") == "failed"
    ]
    if failed_results:
        raise SystemExit(
            f"{quality.capitalize()} render failed for {len(failed_results)} of {len(results)} requested short(s); "
            f"see {render_report_path}."
        )


def file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def visual_review_checkpoints(animation_plan: dict[str, object], video_file: str) -> list[dict[str, object]]:
    evidence = animation_plan.get("qa_evidence_timestamps") if isinstance(animation_plan.get("qa_evidence_timestamps"), list) else []
    rows = [row for row in evidence if isinstance(row, dict)]
    if len(rows) < ANIMATION_PLAN_MIN_TRANSFORMATIONS:
        raise ValueError("animation plan does not contain enough evidence windows for temporal review")
    selected = [
        ("opening", rows[0], "before_seconds"),
        ("pre_action", rows[1 if len(rows) > 1 else 0], "before_seconds"),
        ("post_action", rows[1 if len(rows) > 1 else 0], "after_seconds"),
        ("intermediate", rows[-2 if len(rows) > 1 else -1], "after_seconds"),
        ("final", rows[-1], "after_seconds"),
    ]
    checkpoints = []
    for role, row, timestamp_field in selected:
        timestamp = round(float_or_zero(row.get(timestamp_field)), 2)
        checkpoints.append(
            {
                "role": role,
                "beat_id": row.get("beat_id"),
                "timestamp_seconds": timestamp,
                "frame_reference": f"{video_file}#t={timestamp:.2f}s",
                "persistent_object_ids": list(row.get("persistent_object_ids", [])),
                "observation": "",
            }
        )
    return checkpoints


def cmd_visual_review(args: argparse.Namespace) -> None:
    run = Path(args.run)
    short_plan = read_json(run / "short_plan.json")
    try:
        animation_plans = require_animation_plans(run, short_plan)
    except RuntimeError as exc:
        raise SystemExit(str(exc)) from exc
    index_payload = read_json(run / ANIMATION_PLAN_INDEX_NAME)
    review_path = run / VISUAL_REVIEW_NAME
    previous_reviews: dict[int, dict[str, object]] = {}
    if review_path.exists():
        try:
            previous = read_json(review_path)
            raw_reviews = previous.get("reviews") if isinstance(previous.get("reviews"), list) else []
            previous_reviews = {
                int(review.get("short_index", 0) or 0): review
                for review in raw_reviews
                if isinstance(review, dict) and int(review.get("short_index", 0) or 0) > 0
            }
        except (OSError, json.JSONDecodeError):
            previous_reviews = {}

    reviews: list[dict[str, object]] = []
    shorts = short_plan.get("shorts") if isinstance(short_plan.get("shorts"), list) else []
    for short in shorts:
        if not isinstance(short, dict):
            continue
        index = int(short.get("index", 0) or 0)
        video_file = str(short.get("video_file", "")).strip()
        if not video_file:
            raise SystemExit(f"short {index:02d} has no final video_file; render before initializing visual review")
        relative_video = Path(video_file)
        if relative_video.is_absolute() or ".." in relative_video.parts:
            raise SystemExit(f"short {index:02d} has an unsafe final video path")
        video_path = run / relative_video
        if not video_path.exists() or not video_path.is_file():
            raise SystemExit(f"short {index:02d} final video is missing: {video_path}")
        animation_plan = animation_plans[index]
        plan_fingerprint = animation_plan_fingerprint(animation_plan)
        video_fingerprint = file_sha256(video_path)
        prior = previous_reviews.get(index)
        if (
            prior
            and prior.get("animation_plan_fingerprint") == plan_fingerprint
            and prior.get("video_sha256") == video_fingerprint
            and prior.get("video_file") == video_file
        ):
            reviews.append(prior)
            continue
        evidence_windows = [
            {
                "beat_id": row.get("beat_id"),
                "before_seconds": row.get("before_seconds"),
                "after_seconds": row.get("after_seconds"),
                "persistent_object_ids": row.get("persistent_object_ids", []),
                "expected_change": row.get("expected_change"),
            }
            for row in animation_plan.get("qa_evidence_timestamps", [])
            if isinstance(row, dict)
        ]
        reviews.append(
            {
                "short_index": index,
                "concept": short.get("concept"),
                "animation_plan_file": short.get("animation_plan_file"),
                "animation_plan_fingerprint": plan_fingerprint,
                "video_file": video_file,
                "video_sha256": video_fingerprint,
                "evidence_windows": evidence_windows,
                "checkpoints": visual_review_checkpoints(animation_plan, video_file),
                "persistent_object_ids": list(animation_plan["continuity_spine"]["object_ids"]),
                "observed_state_changes": [],
                "overlap_legibility": {"overlap": "pending", "legibility": "pending", "notes": ""},
                "dense_transition_review": {
                    "sample_interval_seconds": 0.25,
                    "covers_entire_video": False,
                    "labeled_object_collisions": "pending",
                    "persistent_text_integrity": "pending",
                    "notes": "",
                },
                "reviewer": {"kind": "", "name": ""},
                "reviewed_at": None,
                "verdict": "pending",
            }
        )
    payload = {
        "schema_version": VISUAL_REVIEW_SCHEMA_VERSION,
        "animation_plan_index_fingerprint": canonical_json_hash(index_payload),
        "instructions": (
            "Inspect every evidence window and sweep the complete video at intervals no larger than 0.25 seconds. "
            "Check moving text-bearing objects for collisions and persistent text for partial glyph loss; automated metrics do not complete this review."
        ),
        "reviews": reviews,
    }
    write_json(review_path, payload)
    print(review_path)

def public_video_url(base_url: str | None, video_file: str) -> str | None:
    base = base_url or os.environ.get("PUBLIC_VIDEO_BASE_URL")
    if not base:
        return None
    return urllib.parse.urljoin(base.rstrip("/") + "/", Path(video_file).name)


def require_strict_validation(run: Path, action: str) -> None:
    validation = subprocess.run(
        [sys.executable, str(ROOT / "tools" / "validate_course_run.py"), str(run)],
        cwd=ROOT,
        text=True,
        capture_output=True,
    )
    if validation.returncode != 0:
        details = "\n".join(part.strip() for part in (validation.stdout, validation.stderr) if part.strip())
        raise SystemExit(
            f"Refusing to {action} before strict course-run validation passes."
            + (f"\n{details}" if details else "")
        )


def cmd_queue(args: argparse.Namespace) -> None:
    run = Path(args.run)
    require_strict_validation(run, "create a publish queue")
    plan = read_json(run / "short_plan.json")
    items = []
    for short in plan["shorts"]:
        if "video_file" not in short:
            continue
        ex = short["worked_example"]
        caption = textwrap.shorten(
            f"{plan['course_title']} [{short['index']:02d}/{len(plan['shorts']):02d}] - {short['concept']}\n\n"
            f"{short['hook']}\n\nExample: {ex['setup']} {ex['calculation']} {ex['takeaway']}\n\n"
            f"Try this: {short['question_prompt']['question']}\nAnswer idea: {short['question_prompt']['answer']}\n\n"
            f"#stem #math #manim #education #reels",
            width=2200,
            placeholder="...",
        )
        video_file = short["video_file"]
        item = {"short_index": short["index"], "concept": short["concept"], "playlist": args.playlist or plan["course_title"], "video_file": video_file, "caption": caption, "worked_example": ex, "question_prompt": short["question_prompt"], "voiceover": short.get("voiceover"), "status": "ready", "platform": "instagram_reels"}
        video_url = public_video_url(args.public_base_url, video_file)
        if video_url:
            item["video_url"] = video_url
        items.append(item)
    queue = {"run": str(run), "playlist": args.playlist or plan["course_title"], "created_at": int(time.time()), "items": items}
    write_json(run / "instagram_publish_queue.json", queue)
    print(run / "instagram_publish_queue.json")


def graph_base_url() -> str:
    version = os.environ.get("META_GRAPH_VERSION", "v21.0").strip("/")
    return f"https://graph.facebook.com/{version}"


def graph_request(path: str, params: dict[str, str], method: str = "POST") -> dict[str, object]:
    encoded = urllib.parse.urlencode(params).encode("utf-8")
    if method == "GET":
        url = graph_base_url() + path + "?" + encoded.decode("utf-8")
        req = urllib.request.Request(url, headers={"User-Agent": "course-shorts-skills/0.1"})
    else:
        req = urllib.request.Request(graph_base_url() + path, data=encoded, headers={"User-Agent": "course-shorts-skills/0.1"}, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=120) as response:
            return json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        body = exc.read().decode("utf-8", errors="replace")
        return {"error": body, "http_status": exc.code}


def cmd_publish(args: argparse.Namespace) -> None:
    run = Path(args.run)
    require_strict_validation(run, "publish or dry-run the course queue")
    queue_path = run / "instagram_publish_queue.json"
    queue = read_json(queue_path)
    token = os.environ.get("META_ACCESS_TOKEN") or os.environ.get("IG_ACCESS_TOKEN")
    ig_user_id = os.environ.get("IG_USER_ID")
    results = []
    for item in queue.get("items", []):
        if not isinstance(item, dict):
            continue
        video_url = item.get("video_url")
        result = {"short_index": item.get("short_index"), "concept": item.get("concept"), "video_url": video_url}
        if args.dry_run:
            result.update({"status": "dry-run", "message": "Would create a Reel media container, poll processing, then publish."})
            results.append(result)
            continue
        if not token or not ig_user_id:
            result.update({"status": "skipped", "message": "Set IG_USER_ID and META_ACCESS_TOKEN or IG_ACCESS_TOKEN."})
            results.append(result)
            continue
        if not video_url:
            result.update({"status": "skipped", "message": "Queue item has no public video_url. Host videos and rerun queue with --public-base-url."})
            results.append(result)
            continue
        create = graph_request(f"/{ig_user_id}/media", {"media_type": "REELS", "video_url": str(video_url), "caption": str(item.get("caption", "")), "access_token": token})
        creation_id = create.get("id")
        if not creation_id:
            result.update({"status": "failed", "stage": "create", "response": create})
            results.append(result)
            continue
        status_payload = {}
        for _ in range(args.poll_attempts):
            time.sleep(args.poll_seconds)
            status_payload = graph_request(f"/{creation_id}", {"fields": "status_code,status", "access_token": token}, method="GET")
            if status_payload.get("status_code") == "FINISHED":
                break
            if status_payload.get("status_code") in {"ERROR", "EXPIRED"}:
                break
        if status_payload.get("status_code") != "FINISHED":
            result.update({"status": "failed", "stage": "process", "creation_id": creation_id, "response": status_payload})
            results.append(result)
            continue
        publish = graph_request(f"/{ig_user_id}/media_publish", {"creation_id": str(creation_id), "access_token": token})
        if publish.get("id"):
            result.update({"status": "published", "creation_id": creation_id, "media_id": publish.get("id")})
        else:
            result.update({"status": "failed", "stage": "publish", "creation_id": creation_id, "response": publish})
        results.append(result)
    write_json(run / "instagram_publish_results.json", {"created_at": int(time.time()), "results": results})
    print(run / "instagram_publish_results.json")


def cmd_all(args: argparse.Namespace) -> None:
    out = Path(args.out)
    extract_args = argparse.Namespace(url=args.url, out=str(out), sample=args.sample, max_pages=args.max_pages, max_pdfs=args.max_pdfs)
    cmd_extract(extract_args)
    cmd_plan(argparse.Namespace(
        run=str(out),
        max_shorts=args.max_shorts,
        allow_partial_plan=getattr(args, "allow_partial_plan", False),
    ))
    cmd_storyboard(argparse.Namespace(run=str(out)))
    cmd_notes(argparse.Namespace(run=str(out), compile=not args.no_pdf, pdf_engine=args.pdf_engine if not args.no_pdf else "none"))
    cmd_manim(argparse.Namespace(run=str(out)))
    if not args.no_render:
        cmd_render(
            argparse.Namespace(
                run=str(out),
                quality=args.quality,
                voice_engine=args.voice_engine,
                piper_model_dir=getattr(args, "piper_model_dir", None),
                piper_model_id=getattr(args, "piper_model_id", None),
                piper_model_manifest=getattr(args, "piper_model_manifest", None),
            )
        )
        if args.quality == "production":
            audit = subprocess.run(
                [sys.executable, str(ROOT / "tools" / "audit_video_frames.py"), str(out), "--interval", "0.25"],
                cwd=ROOT,
                text=True,
                capture_output=True,
            )
            if audit.returncode != 0:
                details = "\n".join(part.strip() for part in (audit.stdout, audit.stderr) if part.strip())
                raise SystemExit("Production frame audit failed." + (f"\n{details}" if details else ""))
            cmd_visual_review(argparse.Namespace(run=str(out)))


def read_json(path: Path) -> dict[str, object]:
    return json.loads(path.read_text(encoding="utf-8"))


def write_json(path: Path, payload: object) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2), encoding="utf-8")


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description="Course-to-notes-and-shorts workflow for Codex skills.")
    sub = parser.add_subparsers(dest="command", required=True)
    p = sub.add_parser("extract")
    p.add_argument("url", nargs="?", default="")
    p.add_argument("--out", required=True)
    p.add_argument("--sample", choices=["linear_algebra"])
    p.add_argument("--max-pages", type=int, default=DEFAULT_MAX_PAGES)
    p.add_argument("--max-pdfs", type=int, default=DEFAULT_MAX_PDFS)
    p.set_defaults(func=cmd_extract)
    p = sub.add_parser("plan")
    p.add_argument("--run", required=True)
    p.add_argument("--max-shorts", type=int, default=0, help="0 plans the full authoritative outline")
    p.add_argument("--allow-partial-plan", action="store_true")
    p.set_defaults(func=cmd_plan)
    p = sub.add_parser("storyboard", aliases=["animation-plan"])
    p.add_argument("--run", required=True)
    p.set_defaults(func=cmd_storyboard)
    p = sub.add_parser("notes")
    p.add_argument("--run", required=True)
    p.add_argument("--compile", action="store_true")
    p.add_argument("--pdf-engine", choices=["auto", "latex", "fallback", "none"], default="none")
    p.set_defaults(func=cmd_notes)
    p = sub.add_parser("manim")
    p.add_argument("--run", required=True)
    p.set_defaults(func=cmd_manim)
    p = sub.add_parser("render")
    p.add_argument("--run", required=True)
    p.add_argument(
        "--quality",
        choices=["production", "preview"],
        default="production",
        help="production (default) renders full-quality Manim frames; preview renders low-quality frames before canonical finalization",
    )
    p.add_argument("--voice-engine", choices=["none", "piper", "say", "edge-tts", "openai"], default="none")
    p.add_argument("--shorts", default="", help="comma-separated short indices to render, for example 1,2")
    p.add_argument("--piper-model-dir", default=None)
    p.add_argument("--piper-model-id", default=None)
    p.add_argument("--piper-model-manifest", default=None)
    p.set_defaults(func=cmd_render)
    p = sub.add_parser("visual-review")
    p.add_argument("--run", required=True)
    p.set_defaults(func=cmd_visual_review)
    p = sub.add_parser("queue")
    p.add_argument("--run", required=True)
    p.add_argument("--playlist", default=None)
    p.add_argument("--public-base-url", default=None)
    p.set_defaults(func=cmd_queue)
    p = sub.add_parser("publish")
    p.add_argument("--run", required=True)
    p.add_argument("--dry-run", action="store_true")
    p.add_argument("--poll-seconds", type=int, default=10)
    p.add_argument("--poll-attempts", type=int, default=30)
    p.set_defaults(func=cmd_publish)
    p = sub.add_parser("all")
    p.add_argument("url", nargs="?", default="")
    p.add_argument("--out", required=True)
    p.add_argument("--sample", choices=["linear_algebra"])
    p.add_argument("--max-pages", type=int, default=DEFAULT_MAX_PAGES)
    p.add_argument("--max-pdfs", type=int, default=DEFAULT_MAX_PDFS)
    p.add_argument("--max-shorts", type=int, default=0, help="0 plans the full authoritative outline")
    p.add_argument("--allow-partial-plan", action="store_true")
    p.add_argument(
        "--quality",
        choices=["production", "preview"],
        default="production",
        help="production is the default; preview opts into a faster low-quality Manim render",
    )
    p.add_argument("--voice-engine", choices=["none", "piper", "say", "edge-tts", "openai"], default="none")
    p.add_argument("--piper-model-dir", default=None)
    p.add_argument("--piper-model-id", default=None)
    p.add_argument("--piper-model-manifest", default=None)
    p.add_argument("--pdf-engine", choices=["auto", "latex", "fallback", "none"], default="auto")
    p.add_argument("--no-pdf", action="store_true")
    p.add_argument("--no-render", action="store_true")
    p.set_defaults(func=cmd_all)
    return parser


def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    args.func(args)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
